function runConvertExport() {
    if (convertActiveTab === 'images') return exportPdfPagesAsImages();
    if (convertActiveTab === 'pdfa') return convertEditedPdfToPdfA();
    if (convertActiveTab === 'word') return convertEditedPdfToWord();
    if (convertActiveTab === 'excel') return convertEditedPdfToExcel();
    setStatus(`${convertTitle?.textContent || 'This conversion'} is not implemented in the PDF.js editor yet.`, true);
    return Promise.resolve();
}

function isPremiumLockedControl(control) {
    return !EDITOR_AUTHENTICATED && Boolean(control?.dataset?.premiumFeature);
}

function showPremiumFeatureMessage(feature = 'This feature') {
    const verb = String(feature).toLowerCase() === 'notes' ? 'are' : 'is';
    setStatus(`${feature} ${verb} a premium feature. Sign in or create an account to activate it.`, true);
}

function setDebugPanelStatus(message = '', isError = false) {
    if (!debugStatus) return;
    debugStatus.textContent = message;
    debugStatus.classList.toggle('is-error', Boolean(isError));
}

function annotationDebugPayloadForAnnotation(annotation) {
    const direct = annotation?.db_annotation_debug || annotation?.annotationDebug || annotation?._debug;
    if (typeof direct === 'string') {
        try {
            const parsed = JSON.parse(direct);
            return parsed && typeof parsed === 'object' ? parsed : {};
        } catch (_) {
            return {};
        }
    }
    return direct && typeof direct === 'object' ? direct : {};
}

function debugPayloadHasContent(debug) {
    if (!debug || typeof debug !== 'object') return false;
    if (String(debug.note || '').trim() !== '') return true;
    if (Array.isArray(debug.images) && debug.images.length > 0) return true;
    if (debug.mask && typeof debug.mask === 'object' && Object.keys(debug.mask).length > 0) return true;
    return Boolean(debug.updated_at);
}

function annotationHasSavedDebug(annotation) {
    return debugPayloadHasContent(annotationDebugPayloadForAnnotation(annotation));
}

function debugCandidateMatchesAnnotationBox(box, annotation, candidate) {
    if (!box || !candidate || typeof candidate !== 'object') return false;
    const boxIds = new Set([
        box.dataset.annotationId,
        box.dataset.persistedAnnotationId,
        annotation?.id,
        annotation?.db_id,
    ].map((value) => String(value || '').trim()).filter(Boolean));
    const candidateIds = [
        candidate.id,
        candidate.db_id,
        candidate.pdfjsDeletedAnnotationId,
    ].map((value) => String(value || '').trim()).filter(Boolean);
    if (candidateIds.some((id) => boxIds.has(id))) return true;

    const pageIndex = Number.parseInt(box.dataset.pageIndex || annotation?.pageIndex || '-1', 10);
    if (Number.isFinite(pageIndex) && pageIndex >= 0 && annotationPageIndex(candidate) !== pageIndex) return false;

    const sourceKeys = [
        annotation?.promotedSourceKey,
        annotation?.rootSourceKey,
        annotation?.sourceKey,
    ].map((value) => String(value || '').trim()).filter(Boolean);
    const candidateSourceKeys = [
        candidate.promotedSourceKey,
        candidate.rootSourceKey,
        candidate.sourceKey,
    ].map((value) => String(value || '').trim()).filter(Boolean);
    if (sourceKeys.length && candidateSourceKeys.some((key) => sourceKeys.includes(key))) return true;

    const anchorUid = String(annotation?.pdfjsAnchorUid || box.dataset.uid || '').trim();
    const candidateAnchorUid = String(candidate.pdfjsAnchorUid || '').trim();
    if (anchorUid && candidateAnchorUid && anchorUid === candidateAnchorUid) return true;

    const targetText = normalizeComparableText(annotation?.pdfjsSourceText || annotation?.originalText || annotation?.text || baseTextForBox(box) || originalTextForBox(box) || textContentForBox(box));
    const candidateText = normalizeComparableText(candidate.pdfjsSourceText || candidate.originalText || candidate.text || '');
    if (targetText && candidateText && targetText !== candidateText) return false;

    const targetRects = [
        annotationSourceMaskPdfBox(annotation),
        annotationBaselinePdfBox(annotation),
        annotationCurrentPdfBox(annotation),
        boxSourceMaskPdfBox(box),
    ].filter(Boolean);
    const candidateRects = [
        annotationSourceMaskPdfBox(candidate),
        annotationBaselinePdfBox(candidate),
        annotationCurrentPdfBox(candidate),
    ].filter(Boolean);
    return targetRects.some((targetRect) => (
        candidateRects.some((candidateRect) => pdfRectsNearlyEqual(targetRect, candidateRect, 3))
    ));
}

function findSavedDebugAnnotationForBox(box, annotation, annotations) {
    return (Array.isArray(annotations) ? annotations : []).find((candidate) => (
        annotationHasSavedDebug(candidate) && debugCandidateMatchesAnnotationBox(box, annotation, candidate)
    )) || null;
}

async function hydrateSavedDebugForAnnotationBox(box, annotation) {
    const localMatch = findSavedDebugAnnotationForBox(box, annotation, Array.from(persistedAnnotationsById.values()));
    if (localMatch) {
        return {
            ...annotation,
            db_annotation_debug: annotationDebugPayloadForAnnotation(localMatch),
        };
    }
    if (!INFO_URL) return annotation;

    const pageIndex = Number.parseInt(box?.dataset?.pageIndex || annotation?.pageIndex || '-1', 10);
    const url = new URL(INFO_URL, window.location.origin);
    url.searchParams.set('session_id', getSessionId());
    url.searchParams.set('skip_meta', '1');
    url.searchParams.set('include_annotation_debug', '1');
    if (Number.isFinite(pageIndex) && pageIndex >= 0) {
        url.searchParams.set('page', String(pageIndex + 1));
    }
    const response = await fetch(url.toString(), {
        headers: { Accept: 'application/json' },
        credentials: 'same-origin',
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    if (!data?.success) throw new Error(data?.message || 'Failed to load saved debug data.');

    const match = findSavedDebugAnnotationForBox(box, annotation, data.annotations || []);
    if (!match) return annotation;

    const debug = annotationDebugPayloadForAnnotation(match);
    const cacheId = String(annotation?.id || box?.dataset?.annotationId || match.id || '');
    if (cacheId) {
        upsertPersistedAnnotation({
            ...(persistedAnnotationsById.get(cacheId) || {}),
            ...annotation,
            id: cacheId,
            db_id: match.db_id ?? annotation?.db_id,
            db_annotation_debug: debug,
        });
    }
    return { ...annotation, db_annotation_debug: debug };
}

function debugMaskFromInputs() {
    const pageIndex = Number.parseInt(activeDebugMask?.pageIndex ?? '0', 10) || 0;
    const x = Number.parseFloat(debugMaskXInput?.value || '0') || 0;
    const y = Number.parseFloat(debugMaskYInput?.value || '0') || 0;
    const w = Math.max(0.1, Number.parseFloat(debugMaskWInput?.value || '0') || 0.1);
    const h = Math.max(0.1, Number.parseFloat(debugMaskHInput?.value || '0') || 0.1);
    return { pageIndex, x, y, w, h };
}

function writeDebugMaskInputs(mask) {
    if (!mask) return;
    const write = (input, value) => {
        if (input) input.value = Number.isFinite(Number(value)) ? String(Math.round(Number(value) * 10) / 10) : '';
    };
    write(debugMaskXInput, mask.x);
    write(debugMaskYInput, mask.y);
    write(debugMaskWInput, mask.w);
    write(debugMaskHInput, mask.h);
}

function currentPdfRectForBox(box) {
    if (!box) return null;
    const layer = box.parentElement;
    const pageIndex = Number.parseInt(box.dataset.pageIndex || '-1', 10);
    const pageView = Number.isFinite(pageIndex) && pageIndex >= 0 ? pdfViewer.getPageView(pageIndex) : null;
    const viewport = pageView?.viewport;
    const scale = Number.parseFloat(layer?.dataset?.scale || String(viewport?.scale || pdfViewer.currentScale || 1)) || 1;
    if (!viewport || !(scale > 0)) return null;
    const leftPx = Number.parseFloat(box.style.left || '0') || 0;
    const topPx = Number.parseFloat(box.style.top || '0') || 0;
    const widthPx = Number.parseFloat(box.style.width || '0') || box.offsetWidth || 0;
    const heightPx = Number.parseFloat(box.style.height || '0') || box.offsetHeight || 0;
    const dxPts = Number.parseFloat(box.dataset.dxPts || '0') || 0;
    const dyPts = Number.parseFloat(box.dataset.dyPts || '0') || 0;
    return {
        pageIndex,
        x: (leftPx / scale) + dxPts,
        y: (Number(viewport.height) - (topPx + heightPx)) / scale - dyPts,
        w: widthPx / scale,
        h: heightPx / scale,
    };
}

function defaultDebugMaskForBox(box, annotation = null) {
    const pageIndex = Number.parseInt(box?.dataset?.pageIndex || annotation?.pageIndex || '0', 10) || 0;
    const existingDebug = annotationDebugPayloadForAnnotation(annotation);
    const existingMask = existingDebug.mask;
    if (existingMask && [existingMask.x, existingMask.y, existingMask.w, existingMask.h].every((value) => Number.isFinite(Number(value)))) {
        return {
            pageIndex: Number.parseInt(existingMask.pageIndex ?? pageIndex, 10) || pageIndex,
            x: Number(existingMask.x),
            y: Number(existingMask.y),
            w: Math.max(0.1, Number(existingMask.w)),
            h: Math.max(0.1, Number(existingMask.h)),
        };
    }

    const sourceMask = {
        x: Number(annotation?.pdfjsSourceMaskX ?? annotation?.pdfjsSourceX ?? box?.dataset?.sourceBboxX ?? box?.dataset?.baseBboxX),
        y: Number(annotation?.pdfjsSourceMaskY ?? annotation?.pdfjsSourceY ?? box?.dataset?.sourceBboxY ?? box?.dataset?.baseBboxY),
        w: Number(annotation?.pdfjsSourceMaskW ?? annotation?.pdfjsSourceW ?? box?.dataset?.sourceBboxW ?? box?.dataset?.baseBboxW),
        h: Number(annotation?.pdfjsSourceMaskH ?? annotation?.pdfjsSourceH ?? box?.dataset?.sourceBboxH ?? box?.dataset?.baseBboxH),
    };
    if ([sourceMask.x, sourceMask.y, sourceMask.w, sourceMask.h].every(Number.isFinite) && sourceMask.w > 0 && sourceMask.h > 0) {
        return { pageIndex, ...sourceMask };
    }

    const current = currentPdfRectForBox(box) || annotationCurrentPdfBox(annotation);
    if (current && [current.x, current.y, current.w, current.h].every(Number.isFinite) && current.w > 0 && current.h > 0) {
        return { pageIndex, x: current.x, y: current.y, w: current.w, h: current.h };
    }

    return { pageIndex, x: 0, y: 0, w: 1, h: 1 };
}

function removeDebugMaskOverlay() {
    activeDebugMaskEl?.remove();
    activeDebugMaskEl = null;
    debugMaskDragState = null;
}

function updateDebugMaskPointerDrag(ev) {
    const eventPointerId = ev.pointerId ?? debugMaskDragState?.pointerId;
    if (!debugMaskDragState || debugMaskDragState.pointerId !== eventPointerId) return;
    ev.preventDefault();
    const dxPts = (ev.clientX - debugMaskDragState.startClientX) / debugMaskDragState.scale;
    const dyPts = (ev.clientY - debugMaskDragState.startClientY) / debugMaskDragState.scale;
    if (debugMaskDragState.mode === 'resize') {
        let x = debugMaskDragState.startX;
        let y = debugMaskDragState.startY;
        let w = Math.max(0.1, debugMaskDragState.startW);
        let h = Math.max(0.1, debugMaskDragState.startH);
        const handle = debugMaskDragState.handle;
        if (handle.includes('e')) {
            w = Math.max(0.1, debugMaskDragState.startW + dxPts);
        }
        if (handle.includes('w')) {
            const nextW = Math.max(0.1, debugMaskDragState.startW - dxPts);
            x = debugMaskDragState.startX + (debugMaskDragState.startW - nextW);
            w = nextW;
        }
        if (handle.includes('n')) {
            h = Math.max(0.1, debugMaskDragState.startH + dyPts);
        }
        if (handle.includes('s')) {
            const nextH = Math.max(0.1, debugMaskDragState.startH - dyPts);
            y = debugMaskDragState.startY + (debugMaskDragState.startH - nextH);
            h = nextH;
        }
        activeDebugMask = { ...activeDebugMask, x: Math.max(0, x), y: Math.max(0, y), w, h };
    } else {
        activeDebugMask = {
            ...activeDebugMask,
            x: Math.max(0, debugMaskDragState.startX + dxPts),
            y: Math.max(0, debugMaskDragState.startY - dyPts),
        };
    }
    writeDebugMaskInputs(activeDebugMask);
    const nextRect = pdfRectToCanvasRect(activeDebugMask, debugMaskDragState.viewport, debugMaskDragState.scale);
    const el = debugMaskDragState.element;
    if (nextRect && el) {
        el.style.left = `${nextRect.left}px`;
        el.style.top = `${nextRect.top}px`;
        el.style.width = `${nextRect.width}px`;
        el.style.height = `${nextRect.height}px`;
    }
}

function endDebugMaskPointerDrag(ev) {
    const eventPointerId = ev.pointerId ?? debugMaskDragState?.pointerId;
    if (!debugMaskDragState || debugMaskDragState.pointerId !== eventPointerId) return;
    try { debugMaskDragState.element?.releasePointerCapture(eventPointerId); } catch (_) {}
    debugMaskDragState = null;
    window.removeEventListener('pointermove', updateDebugMaskPointerDrag, true);
    window.removeEventListener('pointerup', endDebugMaskPointerDrag, true);
    window.removeEventListener('pointercancel', endDebugMaskPointerDrag, true);
    window.removeEventListener('mousemove', updateDebugMaskPointerDrag, true);
    window.removeEventListener('mouseup', endDebugMaskPointerDrag, true);
}

function beginDebugMaskPointerDrag(ev) {
    if (!activeDebugMask || !activeDebugMaskEl || !debugPanel || debugPanel.hidden) return;
    if (debugMaskDragState) return;
    if (ev.button != null && ev.button !== 0) return;
    const maskEl = ev.target?.closest?.('.enpv-debug-mask-preview');
    if (!maskEl || maskEl !== activeDebugMaskEl) return;
    const handle = ev.target?.closest?.('.enpv-debug-mask-handle')?.dataset?.debugMaskHandle || '';
    const pageIndex = Number.parseInt(activeDebugMask.pageIndex ?? '0', 10) || 0;
    const pageView = pdfViewer.getPageView(pageIndex);
    const viewport = pageView?.viewport;
    const scale = Number(viewport?.scale) || Number(pdfViewer.currentScale) || 1;
    if (!viewport || !(scale > 0)) return;
    ev.preventDefault();
    ev.stopPropagation();
    debugMaskDragState = {
        pointerId: ev.pointerId ?? 'mouse',
        mode: handle ? 'resize' : 'move',
        handle,
        startClientX: ev.clientX,
        startClientY: ev.clientY,
        startX: Number(activeDebugMask.x) || 0,
        startY: Number(activeDebugMask.y) || 0,
        startW: Number(activeDebugMask.w) || 0,
        startH: Number(activeDebugMask.h) || 0,
        scale,
        viewport,
        element: activeDebugMaskEl,
    };
    try { activeDebugMaskEl.setPointerCapture(ev.pointerId); } catch (_) {}
    window.addEventListener('pointermove', updateDebugMaskPointerDrag, true);
    window.addEventListener('pointerup', endDebugMaskPointerDrag, true);
    window.addEventListener('pointercancel', endDebugMaskPointerDrag, true);
    window.addEventListener('mousemove', updateDebugMaskPointerDrag, true);
    window.addEventListener('mouseup', endDebugMaskPointerDrag, true);
}

function renderDebugMaskOverlay() {
    removeDebugMaskOverlay();
    if (!activeDebugMask || !debugPanel || debugPanel.hidden) return;
    const pageIndex = Number.parseInt(activeDebugMask.pageIndex ?? '0', 10) || 0;
    const pageView = pdfViewer.getPageView(pageIndex);
    const pageDiv = pageView?.div;
    const viewport = pageView?.viewport;
    const scale = Number(viewport?.scale) || Number(pdfViewer.currentScale) || 1;
    const rect = pdfRectToCanvasRect(activeDebugMask, viewport, scale);
    if (!pageDiv || !rect || rect.width <= 0 || rect.height <= 0) return;

    const el = document.createElement('div');
    el.className = 'enpv-debug-mask-preview';
    el.title = 'Drag to move the debug mask';
    el.style.left = `${rect.left}px`;
    el.style.top = `${rect.top}px`;
    el.style.width = `${rect.width}px`;
    el.style.height = `${rect.height}px`;
    ['nw', 'n', 'ne', 'e', 'se', 's', 'sw', 'w'].forEach((handle) => {
        const grip = document.createElement('span');
        grip.className = `enpv-debug-mask-handle is-${handle}`;
        grip.dataset.debugMaskHandle = handle;
        grip.setAttribute('aria-hidden', 'true');
        el.appendChild(grip);
    });
    pageDiv.appendChild(el);
    activeDebugMaskEl = el;
}

function renderDebugImageList() {
    if (!debugImageList) return;
    debugImageList.replaceChildren();
    activeDebugImages.forEach((image, index) => {
        const item = document.createElement('div');
        item.className = 'enpv-debug-image-item';
        const img = document.createElement('img');
        img.alt = image.name || `Debug image ${index + 1}`;
        img.src = image.dataUrl;
        const name = document.createElement('span');
        name.textContent = image.name || `Image ${index + 1}`;
        const remove = document.createElement('button');
        remove.type = 'button';
        remove.textContent = 'Remove';
        remove.addEventListener('click', () => {
            activeDebugImages.splice(index, 1);
            renderDebugImageList();
        });
        item.append(img, name, remove);
        debugImageList.appendChild(item);
    });
}

function closeAnnotationDebugPanel() {
    if (debugPanel) {
        debugPanel.hidden = true;
        debugPanel.setAttribute('aria-hidden', 'true');
    }
    activeDebugBoxUid = null;
    activeDebugMask = null;
    activeDebugImages = [];
    removeDebugMaskOverlay();
    setDebugPanelStatus('');
}

function clampDebugPanelPosition(left, top) {
    if (!debugPanel) return { left, top };
    const width = debugPanel.offsetWidth || 380;
    const height = debugPanel.offsetHeight || 420;
    const margin = 8;
    return {
        left: Math.max(margin, Math.min(window.innerWidth - width - margin, left)),
        top: Math.max(margin, Math.min(window.innerHeight - Math.min(height, window.innerHeight - (margin * 2)) - margin, top)),
    };
}

function positionDebugPanel(left, top) {
    if (!debugPanel) return;
    const clamped = clampDebugPanelPosition(left, top);
    debugPanel.style.left = `${clamped.left}px`;
    debugPanel.style.top = `${clamped.top}px`;
    debugPanel.style.right = 'auto';
    debugPanel.style.transform = 'none';
}

function centerDebugPanel() {
    if (!debugPanel) return;
    const width = debugPanel.offsetWidth || 380;
    const height = debugPanel.offsetHeight || 420;
    positionDebugPanel(
        (window.innerWidth - width) / 2,
        (window.innerHeight - height) / 2,
    );
}

function beginDebugPanelDrag(ev) {
    if (!debugPanel || ev.button !== 0) return;
    if (ev.target?.closest?.('button, input, textarea, select, a')) return;
    const rect = debugPanel.getBoundingClientRect();
    debugPanelDragState = {
        pointerId: ev.pointerId,
        startClientX: ev.clientX,
        startClientY: ev.clientY,
        startLeft: rect.left,
        startTop: rect.top,
    };
    debugPanel.classList.add('is-dragging');
    ev.preventDefault();
    ev.stopPropagation();
    try { debugPanel.setPointerCapture(ev.pointerId); } catch (_) {}
}

function updateDebugPanelDrag(ev) {
    if (!debugPanelDragState || debugPanelDragState.pointerId !== ev.pointerId) return;
    ev.preventDefault();
    const left = debugPanelDragState.startLeft + (ev.clientX - debugPanelDragState.startClientX);
    const top = debugPanelDragState.startTop + (ev.clientY - debugPanelDragState.startClientY);
    positionDebugPanel(left, top);
}

function endDebugPanelDrag(ev) {
    if (!debugPanelDragState || debugPanelDragState.pointerId !== ev.pointerId) return;
    try { debugPanel?.releasePointerCapture(ev.pointerId); } catch (_) {}
    debugPanelDragState = null;
    debugPanel?.classList.remove('is-dragging');
}

async function copyDebugAnnotationId() {
    const id = String(debugAnnotationIdInput?.value || '').trim();
    if (!id) return;
    try {
        debugAnnotationIdInput?.select?.();
        debugAnnotationIdInput?.setSelectionRange?.(0, id.length);
    } catch (_) { /* noop */ }
    try {
        await navigator.clipboard?.writeText?.(id);
        setDebugPanelStatus('Annotation id copied.');
    } catch (_) {
        setDebugPanelStatus('Annotation id selected. Press Ctrl+C / Cmd+C to copy.');
    }
}

async function openAnnotationDebugPanel(box) {
    if (!box || !debugPanel) return;
    const existing = persistedAnnotationsById.get(String(box.dataset.annotationId || '')) || null;
    let annotation = buildAnnotationFromBox(box, existing) || existing || {
        id: box.dataset.annotationId || box.dataset.uid || '',
        type: box.dataset.annotationType || 'text',
        pageIndex: Number.parseInt(box.dataset.pageIndex || '0', 10) || 0,
        text: baseTextForBox(box) || originalTextForBox(box) || textContentForBox(box) || '',
    };
    try {
        annotation = await hydrateSavedDebugForAnnotationBox(box, annotation);
    } catch (err) {
        console.warn('Failed to hydrate saved annotation debug data', err);
    }
    const debug = annotationDebugPayloadForAnnotation(annotation);
    activeDebugBoxUid = box.dataset.uid || null;
    activeDebugMask = defaultDebugMaskForBox(box, annotation);
    activeDebugImages = Array.isArray(debug.images) ? debug.images.map((image) => ({ ...image })) : [];
    const annotationId = String(box.dataset.annotationId || annotation.id || 'annotation');
    if (debugAnnotationIdInput) {
        debugAnnotationIdInput.value = annotationId;
        debugAnnotationIdInput.title = `Click to copy ${annotationId}`;
    }
    if (debugAnnotationLabel) {
        const label = String(annotation.text || annotation.originalText || originalTextForBox(box) || box.dataset.annotationId || '').replace(/\s+/g, ' ').trim();
        debugAnnotationLabel.textContent = label ? `- ${label.slice(0, 80)}` : '';
    } else if (debugSubtitle) {
        const label = String(annotation.text || annotation.originalText || originalTextForBox(box) || box.dataset.annotationId || '').replace(/\s+/g, ' ').trim();
        debugSubtitle.textContent = `${annotationId}${label ? ` - ${label.slice(0, 80)}` : ''}`;
    }
    if (debugNoteInput) debugNoteInput.value = String(debug.note || '');
    writeDebugMaskInputs(activeDebugMask);
    renderDebugImageList();
    debugPanel.hidden = false;
    debugPanel.setAttribute('aria-hidden', 'false');
    centerDebugPanel();
    setDebugPanelStatus('Drag the white mask on the page or edit the numbers.');
    renderDebugMaskOverlay();
}

async function addDebugImagesFromFiles(files) {
    const selected = Array.from(files || []).filter((file) => file?.type?.startsWith?.('image/'));
    if (!selected.length) return;
    const readers = selected.slice(0, Math.max(0, 12 - activeDebugImages.length)).map((file) => new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve({
            name: file.name || 'debug-image',
            type: file.type || 'image',
            dataUrl: String(reader.result || ''),
        });
        reader.onerror = () => reject(reader.error || new Error('Failed to read image.'));
        reader.readAsDataURL(file);
    }));
    activeDebugImages.push(...(await Promise.all(readers)));
    renderDebugImageList();
}

async function saveAnnotationDebugFromPanel() {
    if (!ANNOTATION_DEBUG_URL) {
        showError('Annotation debug endpoint not configured.');
        return;
    }
    const box = activeDebugBoxUid
        ? document.querySelector(`.enpv-annotation-box[data-uid="${cssEscape(activeDebugBoxUid)}"]`)
        : findSelectedBox();
    if (!box) {
        setDebugPanelStatus('Select an annotation before saving debug data.', true);
        return;
    }
    const existing = persistedAnnotationsById.get(String(box.dataset.annotationId || '')) || null;
    const annotation = buildAnnotationFromBox(box, existing) || existing || {
        id: box.dataset.annotationId || box.dataset.uid || '',
        type: box.dataset.annotationType || 'text',
        pageIndex: Number.parseInt(box.dataset.pageIndex || '0', 10) || 0,
        text: baseTextForBox(box) || originalTextForBox(box) || textContentForBox(box) || '',
    };
    annotation.id = String(annotation.id || box.dataset.annotationId || box.dataset.uid || '');
    const debug = {
        note: String(debugNoteInput?.value || ''),
        mask: debugMaskFromInputs(),
        images: activeDebugImages,
    };
    setDebugPanelStatus('Saving debug data...');
    if (debugSaveButton) debugSaveButton.disabled = true;
    try {
        const response = await fetch(ANNOTATION_DEBUG_URL, {
            method: 'POST',
            credentials: 'same-origin',
            headers: {
                'Content-Type': 'application/json',
                Accept: 'application/json',
                'X-CSRF-TOKEN': CSRF,
            },
            body: JSON.stringify({
                annotation_id: annotation.id,
                annotation: stripTransientAnnotationFields(annotation),
                debug,
                session_id: getSessionId(),
            }),
        });
        const result = await response.json().catch(() => ({}));
        if (!response.ok || result?.success === false) {
            throw new Error(result?.message || `Debug save failed (${response.status})`);
        }
        upsertPersistedAnnotation({
            ...(existing || {}),
            ...annotation,
            db_id: result.db_id ?? existing?.db_id,
            db_annotation_debug: result.debug || debug,
        });
        setDebugPanelStatus('Debug data saved.');
        setStatus('Annotation debug saved.');
    } catch (err) {
        console.error(err);
        setDebugPanelStatus(err.message || 'Debug save failed.', true);
        showError(err.message || 'Debug save failed.');
    } finally {
        if (debugSaveButton) debugSaveButton.disabled = false;
    }
}

function setDrawToolStatus(message) {
    if (drawToolStatus) drawToolStatus.textContent = String(message || '');
}

function activeDirectDrawStrokeColor() {
    return drawToolType === DIRECT_DRAW_TOOL_ERASER ? '#ffffff' : drawStrokeColor;
}

function activeDirectDrawOpacity() {
    return drawToolType === DIRECT_DRAW_TOOL_ERASER ? 1 : drawOpacity;
}

function syncDrawToolPanelUi() {
    const selectedDrawBox = document.querySelector('.enpv-annotation-box.enpv-direct-draw-box.is-selected');
    const shouldShowPanel = drawModeActive || Boolean(selectedDrawBox);
    if (drawToolPanel) {
        drawToolPanel.classList.toggle('is-visible', shouldShowPanel);
        drawToolPanel.setAttribute('aria-hidden', shouldShowPanel ? 'false' : 'true');
    }
    if (floatingDrawButton) {
        floatingDrawButton.classList.toggle('is-active', drawModeActive);
        floatingDrawButton.setAttribute('aria-pressed', drawModeActive ? 'true' : 'false');
        floatingDrawButton.title = drawModeActive
            ? (drawToolType === DIRECT_DRAW_TOOL_ERASER
                ? 'Eraser active — drag on the PDF to cover content'
                : drawToolType === DIRECT_DRAW_TOOL_SMOOTH_CURVE
                    ? 'Smooth curve active — drag on the PDF to draw a fitted curve'
                    : 'Draw active — drag on the PDF to draw')
            : 'Draw — sketch directly on the PDF';
    }
    drawToolButtons.forEach((button) => {
        button.classList.toggle('is-active', button.dataset.drawDirectTool === drawToolType);
    });
    drawColorSwatches.forEach((button) => {
        button.classList.toggle('is-active', cssColorToHex(button.dataset.drawColor, '') === cssColorToHex(drawStrokeColor, '#111827'));
    });
    if (drawToolInkColors) drawToolInkColors.hidden = drawToolType === DIRECT_DRAW_TOOL_ERASER;
    if (drawToolEraserColor) drawToolEraserColor.hidden = drawToolType !== DIRECT_DRAW_TOOL_ERASER;
    if (drawToolColorInput) drawToolColorInput.value = cssColorToHex(drawStrokeColor, '#111827');
    if (drawToolSizeInput) drawToolSizeInput.value = String(Math.round(drawBrushSize));
    if (drawToolSizeValue) drawToolSizeValue.textContent = `${Math.round(drawBrushSize)}px`;
    if (drawToolOpacityInput) {
        drawToolOpacityInput.value = String(Math.round(activeDirectDrawOpacity() * 100));
        drawToolOpacityInput.disabled = drawToolType === DIRECT_DRAW_TOOL_ERASER;
    }
    if (drawToolOpacityValue) drawToolOpacityValue.textContent = `${Math.round(activeDirectDrawOpacity() * 100)}%`;
    setDrawToolStatus(
        drawToolType === DIRECT_DRAW_TOOL_ERASER
            ? 'Eraser mode is active. Drag directly on the page to cover content with white.'
            : drawToolType === DIRECT_DRAW_TOOL_SMOOTH_CURVE
                ? 'Smooth curve mode is active. Drag directly on the page to draw a fitted curve.'
                : 'Pen mode is active. Drag directly on the page to draw.',
    );
}

function clearActiveDrawSession() {
    activeDrawSession?.layer?.remove?.();
    activeDrawSession = null;
}

function directDrawLayerForPage(pageIndex, className, rect = null, intrinsicWidth = null, intrinsicHeight = null) {
    const pageView = pdfViewer.getPageView(pageIndex);
    const pageDiv = pageView?.div;
    const viewport = pageView?.viewport;
    if (!pageDiv || !viewport) return null;
    const width = Math.max(1, Number(intrinsicWidth || rect?.width || viewport.width) || 1);
    const height = Math.max(1, Number(intrinsicHeight || rect?.height || viewport.height) || 1);
    const layer = document.createElement('canvas');
    layer.className = className;
    layer.width = Math.round(width);
    layer.height = Math.round(height);
    layer.style.left = `${Math.max(0, Number(rect?.left) || 0)}px`;
    layer.style.top = `${Math.max(0, Number(rect?.top) || 0)}px`;
    layer.style.width = `${Math.max(1, Number(rect?.width || viewport.width) || 1)}px`;
    layer.style.height = `${Math.max(1, Number(rect?.height || viewport.height) || 1)}px`;
    pageDiv.appendChild(layer);
    return layer;
}

function clampDirectDrawVectorNumber(value, fallback = 0) {
    const number = Number(value);
    return Number.isFinite(number) ? number : fallback;
}

function directDrawSvgPathFromPoints(points, smoothCurve = false) {
    const cleanPoints = Array.isArray(points)
        ? points
            .map((point) => ({
                x: clampDirectDrawVectorNumber(point?.x, 0),
                y: clampDirectDrawVectorNumber(point?.y, 0),
            }))
            .filter((point) => Number.isFinite(point.x) && Number.isFinite(point.y))
        : [];
    if (!cleanPoints.length) return '';
    if (smoothCurve) return smoothDrawCurveSvgPathD(cleanPoints);
    if (cleanPoints.length === 1) {
        const point = cleanPoints[0];
        return `M ${point.x.toFixed(3)} ${point.y.toFixed(3)} L ${(point.x + 0.01).toFixed(3)} ${point.y.toFixed(3)}`;
    }
    const [first, ...rest] = cleanPoints;
    return `M ${first.x.toFixed(3)} ${first.y.toFixed(3)} ${rest.map((point) => `L ${point.x.toFixed(3)} ${point.y.toFixed(3)}`).join(' ')}`;
}

function directDrawVectorToSvgDataUrl(vector) {
    if (!vector || typeof vector !== 'object') return '';
    const width = Math.max(1, clampDirectDrawVectorNumber(vector.width, 0));
    const height = Math.max(1, clampDirectDrawVectorNumber(vector.height, 0));
    const strokes = Array.isArray(vector.strokes) ? vector.strokes : [];
    const paths = strokes.map((stroke) => {
        const pathData = directDrawSvgPathFromPoints(stroke?.points, Boolean(stroke?.smoothCurve));
        if (!pathData) return '';
        const color = cssColorToHex(stroke?.color, '#111827');
        const opacity = clamp01(stroke?.opacity ?? 1, 1);
        const brushSize = Math.max(0.25, clampDirectDrawVectorNumber(stroke?.brushSize, 1));
        return `<path d="${pathData}" fill="none" stroke="${color}" stroke-width="${brushSize.toFixed(3)}" stroke-linecap="round" stroke-linejoin="round" opacity="${opacity.toFixed(4)}"/>`;
    }).filter(Boolean).join('');
    if (!paths) return '';
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">${paths}</svg>`;
    return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}

function restyleDirectDrawVector(vector, style = {}) {
    if (!vector || typeof vector !== 'object') return null;
    const width = Math.max(1, Number(vector.width) || 1);
    const height = Math.max(1, Number(vector.height) || 1);
    const brushSize = Math.max(0.25, Number(style.brushSize) || 1);
    const color = cssColorToHex(style.color, '#111827');
    const opacity = clamp01(style.opacity ?? 1, 1);
    const sourceStrokes = Array.isArray(vector.strokes) ? vector.strokes : [];
    const strokes = sourceStrokes.map((stroke) => {
        const points = Array.isArray(stroke?.points)
            ? stroke.points.map((point) => ({
                x: clampDirectDrawVectorNumber(point?.x, 0),
                y: clampDirectDrawVectorNumber(point?.y, 0),
            }))
            : [];
        return points.length ? {
            color,
            opacity,
            brushSize,
            smoothCurve: Boolean(stroke?.smoothCurve),
            points,
        } : null;
    }).filter(Boolean);
    if (!strokes.length) return null;

    const radius = brushSize / 2;
    let minX = width;
    let minY = height;
    let maxX = 0;
    let maxY = 0;
    strokes.forEach((stroke) => {
        stroke.points.forEach((point) => {
            minX = Math.min(minX, point.x - radius);
            minY = Math.min(minY, point.y - radius);
            maxX = Math.max(maxX, point.x + radius);
            maxY = Math.max(maxY, point.y + radius);
        });
    });
    const addLeft = Math.ceil(Math.max(0, -minX));
    const addTop = Math.ceil(Math.max(0, -minY));
    const addRight = Math.ceil(Math.max(0, maxX - width));
    const addBottom = Math.ceil(Math.max(0, maxY - height));
    if (addLeft || addTop) {
        strokes.forEach((stroke) => {
            stroke.points = stroke.points.map((point) => ({
                x: point.x + addLeft,
                y: point.y + addTop,
            }));
        });
    }
    return {
        vector: {
            version: 1,
            width: width + addLeft + addRight,
            height: height + addTop + addBottom,
            strokes,
        },
        addLeft,
        addTop,
        addRight,
        addBottom,
        oldWidth: width,
        oldHeight: height,
    };
}

function directDrawPrimaryStroke(annotation) {
    const strokes = Array.isArray(annotation?.directDrawVector?.strokes) ? annotation.directDrawVector.strokes : [];
    return strokes[0] || null;
}

function reflectDirectDrawAnnotationToInputs(annotation) {
    if (!isDirectDrawAnnotation(annotation)) return;
    const stroke = directDrawPrimaryStroke(annotation);
    drawToolType = normalizeDirectDrawTool(annotation.directDrawTool);
    if (stroke && drawToolType !== DIRECT_DRAW_TOOL_ERASER) {
        drawStrokeColor = cssColorToHex(stroke.color || annotation.drawStrokeColor, drawStrokeColor);
        drawOpacity = clamp01(stroke.opacity ?? drawOpacity, drawOpacity);
    }
    if (stroke) {
        drawBrushSize = Math.max(2, Number(stroke.brushSize) || drawBrushSize);
    }
    syncDrawToolPanelUi();
}

function applyDrawPanelStateToSelectedDirectDrawAnnotations(options = {}) {
    const boxes = hasMultiSelection()
        ? multiSelectedBoxes().filter((box) => box.classList.contains('enpv-direct-draw-box'))
        : [findSelectedBox()].filter((box) => box?.classList?.contains('enpv-direct-draw-box'));
    const editableBoxes = boxes.filter((box) => box?.isConnected && !isAnnBoxLocked(box));
    if (!editableBoxes.length) return false;

    const updates = [];
    for (const box of editableBoxes) {
        const existing = persistedAnnotationsById.get(String(box.dataset.annotationId || '')) || null;
        if (!isDirectDrawAnnotation(existing) || !existing.directDrawVector) continue;
        const current = buildAnnotationFromBox(box, existing) || existing;
        const directDrawTool = normalizeDirectDrawTool(existing.directDrawTool);
        const isEraser = directDrawTool === DIRECT_DRAW_TOOL_ERASER;
        const styled = restyleDirectDrawVector(existing.directDrawVector, {
            color: isEraser ? '#ffffff' : drawStrokeColor,
            opacity: isEraser ? 1 : drawOpacity,
            brushSize: drawBrushSize,
        });
        if (!styled?.vector) continue;
        updates.push({ box, existing, current, styled, isEraser, directDrawTool });
    }
    if (!updates.length) return false;
    if (options.pushHistory === true) pushHistorySnapshot('change drawing style');

    for (const { box, existing, current, styled, isEraser, directDrawTool } of updates) {
        const unitX = Math.max(0.0001, (Number(current.pdfWidth) || Number(existing.pdfWidth) || 1) / Math.max(1, styled.oldWidth));
        const unitY = Math.max(0.0001, (Number(current.pdfHeight) || Number(existing.pdfHeight) || 1) / Math.max(1, styled.oldHeight));
        const next = normalizeImageAnnotation({
            ...existing,
            ...current,
            imageToolSource: 'direct-draw',
            directDrawTool,
            drawStrokeColor: isEraser ? '#ffffff' : cssColorToHex(drawStrokeColor, '#111827'),
            directDrawVector: styled.vector,
            dataUrl: directDrawVectorToSvgDataUrl(styled.vector),
            fileName: 'drawing.svg',
            mimeType: 'image/svg+xml',
            intrinsicWidth: styled.vector.width,
            intrinsicHeight: styled.vector.height,
            pdfX: (Number(current.pdfX) || 0) - (styled.addLeft * unitX),
            pdfY: (Number(current.pdfY) || 0) - (styled.addBottom * unitY),
            pdfWidth: (Number(current.pdfWidth) || Number(existing.pdfWidth) || 1) + ((styled.addLeft + styled.addRight) * unitX),
            pdfHeight: (Number(current.pdfHeight) || Number(existing.pdfHeight) || 1) + ((styled.addTop + styled.addBottom) * unitY),
            userCreated: true,
        });
        upsertPersistedAnnotation(next);

        const layer = box.parentElement;
        const scale = Number.parseFloat(layer?.dataset?.scale || '1') || 1;
        const pageView = pdfViewer.getPageView(annotationPageIndex(next));
        const viewportHeight = Number(pageView?.viewport?.height) || 0;
        if (layer && viewportHeight > 0) {
            box.style.left = `${next.pdfX * scale}px`;
            box.style.top = `${viewportHeight - ((next.pdfY + next.pdfHeight) * scale)}px`;
            box.style.width = `${Math.max(1, next.pdfWidth * scale)}px`;
            box.style.height = `${Math.max(1, next.pdfHeight * scale)}px`;
        }
        const img = box.querySelector('.enpv-image-img');
        if (img) img.src = directDrawVectorToSvgDataUrl(styled.vector);
        box.dataset.pendingEdit = '1';
        box.dataset.directDraw = '1';
        box.dataset.directDrawTool = next.directDrawTool;
        box.classList.add('enpv-direct-draw-box', 'is-selected');
    }
    if (!hasMultiSelection()) {
        const selected = editableBoxes[0];
        if (selected) selectedAnnBoxUid = selected.dataset.uid || selectedAnnBoxUid;
    }
    markManualSaveNeeded();
    return true;
}

function applyLiveDrawPanelStateToSelectedDirectDrawAnnotations() {
    const applied = applyDrawPanelStateToSelectedDirectDrawAnnotations({
        pushHistory: !drawStyleLiveEditHistoryCaptured,
    });
    if (applied) drawStyleLiveEditHistoryCaptured = true;
    return applied;
}

function finishLiveDrawPanelStateEdit() {
    applyDrawPanelStateToSelectedDirectDrawAnnotations({ pushHistory: false });
    drawStyleLiveEditHistoryCaptured = false;
}

function directDrawVectorFromSession(session, cropLeft, cropTop, cropWidth, cropHeight) {
    let points = (Array.isArray(session?.points) ? session.points : [])
        .map((point) => ({
            x: Math.max(0, Math.min(cropWidth, clampDirectDrawVectorNumber(point.x, 0) - cropLeft)),
            y: Math.max(0, Math.min(cropHeight, clampDirectDrawVectorNumber(point.y, 0) - cropTop)),
        }));
    if (!points.length) return null;
    const smoothCurve = normalizeDirectDrawTool(session?.directDrawTool) === DIRECT_DRAW_TOOL_SMOOTH_CURVE;
    if (smoothCurve) points = smoothDrawCurvePoints(points);
    return {
        version: 1,
        width: Math.max(1, cropWidth),
        height: Math.max(1, cropHeight),
        strokes: [{
            color: cssColorToHex(session.color, '#111827'),
            opacity: clamp01(session.opacity ?? 1, 1),
            brushSize: Math.max(0.25, clampDirectDrawVectorNumber(session.width, 1)),
            smoothCurve,
            points,
        }],
    };
}

function directDrawAnnotationAtPageBox(pageIndex, asset, box) {
    if (!asset?.dataUrl || !box) return null;
    const uid = String(asset.uid || `draw_${generateUuidV4()}`);
    const annotation = normalizeImageAnnotation({
        _uid: uid,
        id: buildPdfjsAnnotationId(pageIndex, uid),
        pageIndex,
        type: 'image',
        pdfX: Math.max(0, Number(box.pdfX) || 0),
        pdfY: Math.max(0, Number(box.pdfY) || 0),
        pdfWidth: Math.max(1, Number(box.pdfWidth) || 1),
        pdfHeight: Math.max(1, Number(box.pdfHeight) || 1),
        rotation: 0,
        opacity: 1,
        userCreated: true,
        zIndex: normalizeDirectDrawTool(asset.directDrawTool) === DIRECT_DRAW_TOOL_ERASER ? 1000 : 2,
        dataUrl: asset.dataUrl,
        src: '',
        fileName: 'drawing.png',
        mimeType: 'image/png',
        intrinsicWidth: Math.max(1, Number(asset.width) || 1),
        intrinsicHeight: Math.max(1, Number(asset.height) || 1),
        imageToolSource: 'direct-draw',
        directDrawTool: normalizeDirectDrawTool(asset.directDrawTool),
        drawStrokeColor: cssColorToHex(asset.drawStrokeColor, '#111827'),
        directDrawVector: asset.directDrawVector || null,
        text: '',
    });
    annotation._drawCreatedAt = Date.now();
    annotation._originalBox = { x: annotation.pdfX, y: annotation.pdfY, w: annotation.pdfWidth, h: annotation.pdfHeight };
    annotation._originalPdfBox = { ...annotation._originalBox };
    return annotation;
}

function upsertDirectDrawAnnotation(annotation, historyLabel = 'add drawing') {
    if (!annotation) return false;
    pushHistorySnapshot(historyLabel);
    upsertPersistedAnnotation(annotation);
    renderAnnotationBoxLayer(annotationPageIndex(annotation));
    const pageDiv = pdfViewer.getPageView(annotationPageIndex(annotation))?.div;
    const box = pageDiv?.querySelector(`.enpv-annotation-box[data-annotation-id="${cssEscape(annotation.id)}"]`) || null;
    if (box) selectAnnBox(box);
    markManualSaveNeeded();
    return true;
}

function beginDirectPenStroke(event, pageIndex) {
    const point = pdfjsPointFromPageClient(pageIndex, event.clientX, event.clientY);
    if (!point) return false;
    const layer = directDrawLayerForPage(pageIndex, 'enpv-draw-preview-layer');
    const ctx = layer?.getContext('2d');
    if (!layer || !ctx) return false;
    clearActiveDrawSession();
    event.preventDefault();
    event.stopPropagation();
    try { point.pageDiv.setPointerCapture?.(event.pointerId); } catch (_) {}
    const strokeColor = activeDirectDrawStrokeColor();
    const strokeOpacity = activeDirectDrawOpacity();
    layer.style.opacity = String(strokeOpacity);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.imageSmoothingEnabled = true;
    paintDrawDot(ctx, point.canvasX, point.canvasY, drawBrushSize, strokeColor);
    activeDrawSession = {
        kind: 'pen',
        pageIndex,
        pageDiv: point.pageDiv,
        pointerId: event.pointerId,
        layer,
        ctx,
        directDrawTool: drawToolType,
        color: strokeColor,
        width: drawBrushSize,
        opacity: strokeOpacity,
        points: [{ x: point.canvasX, y: point.canvasY }],
        lastMidPoint: { x: point.canvasX, y: point.canvasY },
        minX: point.canvasX - (drawBrushSize / 2),
        minY: point.canvasY - (drawBrushSize / 2),
        maxX: point.canvasX + (drawBrushSize / 2),
        maxY: point.canvasY + (drawBrushSize / 2),
        viewport: point.viewport,
        scale: point.scale,
    };
    return true;
}

function moveDirectPenStroke(event) {
    const session = activeDrawSession;
    if (!session || session.kind !== 'pen' || session.pointerId !== event.pointerId) return false;
    const pointInfo = pdfjsPointFromPageClient(session.pageIndex, event.clientX, event.clientY);
    if (!pointInfo) return true;
    event.preventDefault();
    const point = { x: pointInfo.canvasX, y: pointInfo.canvasY };
    const lastPoint = session.points[session.points.length - 1];
    const dx = point.x - lastPoint.x;
    const dy = point.y - lastPoint.y;
    if ((dx * dx) + (dy * dy) < 0.5) return true;
    session.points.push(point);
    session.minX = Math.min(session.minX, point.x - (session.width / 2));
    session.minY = Math.min(session.minY, point.y - (session.width / 2));
    session.maxX = Math.max(session.maxX, point.x + (session.width / 2));
    session.maxY = Math.max(session.maxY, point.y + (session.width / 2));
    if (session.directDrawTool === DIRECT_DRAW_TOOL_SMOOTH_CURVE) {
        session.ctx.clearRect(0, 0, session.layer.width, session.layer.height);
        paintSmoothDrawCurve(session.ctx, session, session.color, session.width);
    } else {
        const midPoint = { x: (lastPoint.x + point.x) / 2, y: (lastPoint.y + point.y) / 2 };
        paintDrawSegment(session.ctx, session.lastMidPoint, lastPoint, midPoint, session.width, session.color);
        session.lastMidPoint = midPoint;
    }
    return true;
}

function finishDirectPenStroke(event) {
    const session = activeDrawSession;
    if (!session || session.kind !== 'pen' || session.pointerId !== event.pointerId) return false;
    event.preventDefault();
    event.stopPropagation();
    try { session.pageDiv?.releasePointerCapture?.(event.pointerId); } catch (_) {}
    if (session.points.length > 1 && session.directDrawTool !== DIRECT_DRAW_TOOL_SMOOTH_CURVE) {
        const lastPoint = session.points[session.points.length - 1];
        paintDrawSegment(session.ctx, session.lastMidPoint, lastPoint, lastPoint, session.width, session.color);
    }
    const padding = Math.max(session.width, 8);
    const cropLeft = Math.max(0, Math.floor(session.minX - padding));
    const cropTop = Math.max(0, Math.floor(session.minY - padding));
    const cropRight = Math.min(session.layer.width, Math.ceil(session.maxX + padding));
    const cropBottom = Math.min(session.layer.height, Math.ceil(session.maxY + padding));
    if (cropRight <= cropLeft || cropBottom <= cropTop) {
        clearActiveDrawSession();
        return true;
    }
    const cropWidth = cropRight - cropLeft;
    const cropHeight = cropBottom - cropTop;
    const outputScale = 2;
    const outputCanvas = document.createElement('canvas');
    outputCanvas.width = Math.max(1, Math.ceil(cropWidth * outputScale));
    outputCanvas.height = Math.max(1, Math.ceil(cropHeight * outputScale));
    const outputCtx = outputCanvas.getContext('2d');
    outputCtx.scale(outputScale, outputScale);
    outputCtx.globalAlpha = session.opacity;
    if (session.directDrawTool === DIRECT_DRAW_TOOL_SMOOTH_CURVE) {
        paintSmoothDrawCurve(outputCtx, {
            color: session.color,
            width: session.width,
            points: session.points.map((point) => ({
                x: point.x - cropLeft,
                y: point.y - cropTop,
            })),
        }, session.color, session.width);
    } else {
        outputCtx.drawImage(session.layer, -cropLeft, -cropTop);
    }
    const pdfWidth = cropWidth / session.scale;
    const pdfHeight = cropHeight / session.scale;
    const annotation = directDrawAnnotationAtPageBox(session.pageIndex, {
        dataUrl: outputCanvas.toDataURL('image/png'),
        width: outputCanvas.width,
        height: outputCanvas.height,
        drawStrokeColor: session.color,
        directDrawTool: session.directDrawTool,
        directDrawVector: directDrawVectorFromSession(session, cropLeft, cropTop, cropWidth, cropHeight),
    }, {
        pdfX: cropLeft / session.scale,
        pdfY: ((Number(session.viewport.height) || session.layer.height) - cropBottom) / session.scale,
        pdfWidth,
        pdfHeight,
    });
    clearActiveDrawSession();
    if (upsertDirectDrawAnnotation(annotation, 'add drawing')) {
        setDrawToolStatus(
            session.directDrawTool === DIRECT_DRAW_TOOL_ERASER
                ? 'Eraser stroke added. Keep dragging to cover more content.'
                : session.directDrawTool === DIRECT_DRAW_TOOL_SMOOTH_CURVE
                    ? 'Smooth curve added. Keep drawing on the page.'
                    : 'Drawing added. Keep drawing on the page.',
        );
    }
    return true;
}

function cancelDirectDrawPointer(event) {
    if (!activeDrawSession) return false;
    if (event && activeDrawSession.pointerId !== event.pointerId) return false;
    try { activeDrawSession.pageDiv?.releasePointerCapture?.(activeDrawSession.pointerId); } catch (_) {}
    clearActiveDrawSession();
    return true;
}

function setDrawMode(active) {
    const nextActive = Boolean(active);
    if (nextActive && document.body.classList.contains('enpv-edit-on')) setEditMode(false);
    if (nextActive && document.body.classList.contains('enpv-add-text-on')) setAddTextMode(false);
    if (nextActive && document.body.classList.contains('enpv-shape-on')) setShapeMode(false);
    if (nextActive && highlightModeActive) setHighlightMode(false);
    if (nextActive) cancelFieldPlacement({ showStatus: false });
    if (nextActive) signatureFeature?.cancelSignaturePlacement?.();
    if (nextActive) {
        closeNotesPanel();
        hideAnnotationFormatBar();
        shapeToolPanel?.classList.remove('is-visible');
    }
    if (!nextActive) clearActiveDrawSession();
    drawModeActive = nextActive;
    document.body.classList.toggle('enpv-draw-on', drawModeActive);
    syncDrawToolPanelUi();
    if (drawModeActive) {
        deselectAnnBox();
        setStatus(
            drawToolType === DIRECT_DRAW_TOOL_SMOOTH_CURVE
                ? 'Smooth curve mode active. Drag on the PDF to draw a fitted curve.'
                : drawToolType === DIRECT_DRAW_TOOL_ERASER
                    ? 'Eraser mode active. Drag on the PDF to cover content.'
                    : 'Draw mode active. Drag on the PDF to draw.',
        );
    } else if (!document.body.classList.contains('enpv-edit-on')
        && !document.body.classList.contains('enpv-add-text-on')
        && !document.body.classList.contains('enpv-shape-on')
        && !highlightModeActive) {
        setStatus('Ready.');
    }
    renderAllAnnotationBoxLayers();
    scheduleRenderAllAnnotationBoxLayers();
}

function setHighlightToolStatus(message) {
    if (highlightToolStatus) highlightToolStatus.textContent = String(message || '');
}

function syncHighlightToolPanelUi() {
    const selectedHighlightBox = document.querySelector('.enpv-annotation-box.enpv-highlight-box.is-selected');
    const shouldShowPanel = highlightModeActive || Boolean(selectedHighlightBox);
    if (highlightToolPanel) {
        highlightToolPanel.classList.toggle('is-visible', shouldShowPanel);
        highlightToolPanel.setAttribute('aria-hidden', shouldShowPanel ? 'false' : 'true');
    }
    if (floatingHighlightButton) {
        floatingHighlightButton.classList.toggle('active', highlightModeActive);
        floatingHighlightButton.classList.toggle('is-active', highlightModeActive);
        floatingHighlightButton.setAttribute('aria-pressed', highlightModeActive ? 'true' : 'false');
        floatingHighlightButton.title = highlightModeActive
            ? 'Highlight active - select text or drag over the PDF'
            : 'Highlight - select text or drag over the page';
    }
    highlightColorSwatches.forEach((button) => {
        button.classList.toggle('is-active', cssColorToHex(button.dataset.highlightColor, '') === cssColorToHex(highlightColor, '#facc15'));
    });
    if (highlightColorInput) highlightColorInput.value = cssColorToHex(highlightColor, '#facc15');
    if (highlightOpacityInput) highlightOpacityInput.value = String(Math.round(highlightOpacity * 100));
    if (highlightOpacityValue) highlightOpacityValue.textContent = `${Math.round(highlightOpacity * 100)}%`;
    setHighlightToolStatus(highlightModeActive
        ? 'Select text to highlight it, or drag over the page.'
        : 'Select text to highlight it, or drag over the page.');
}

function reflectHighlightAnnotationToInputs(annotation) {
    if (!isHighlightAnnotation(annotation)) return;
    highlightColor = cssColorToHex(
        annotation.highlightColor
        || annotation.fillColor
        || annotation.strokeColor
        || highlightColor,
        '#facc15',
    );
    highlightOpacity = clamp01(
        annotation.highlightOpacity
        ?? annotation.fillOpacity
        ?? annotation.opacity
        ?? highlightOpacity,
        0.35,
    );
    syncHighlightToolPanelUi();
}

function applyHighlightPanelStateToSelectedAnnotations(options = {}) {
    const boxes = hasMultiSelection()
        ? multiSelectedBoxes().filter((box) => box.classList.contains('enpv-highlight-box'))
        : [findSelectedBox()].filter((box) => box?.classList?.contains('enpv-highlight-box'));
    const editableBoxes = boxes.filter((box) => box?.isConnected && !isAnnBoxLocked(box));
    if (!editableBoxes.length) return false;
    if (options.pushHistory === true) pushHistorySnapshot('change highlight style');

    for (const box of editableBoxes) {
        const existing = persistedAnnotationsById.get(String(box.dataset.annotationId || '')) || null;
        if (!isHighlightAnnotation(existing)) continue;
        const current = buildAnnotationFromBox(box, existing) || existing;
        const annotation = normalizeShapeAnnotation({
            ...existing,
            ...current,
            type: 'shape',
            shapeType: 'highlight',
            strokeColor: highlightColor,
            strokeOpacity: 0,
            strokeWidth: Number(current.strokeWidth || existing.strokeWidth || 1) || 1,
            strokeTransparent: true,
            fillColor: highlightColor,
            fillOpacity: highlightOpacity,
            fillTransparent: false,
            opacity: highlightOpacity,
            highlightColor,
            highlightOpacity,
            userCreated: true,
            userAuthored: true,
        });
        upsertPersistedAnnotation(annotation);
        applyShapeAnnotationToBoxDataset(box, annotation);
        updateShapeSvgForBox(box, annotation, Number.parseFloat(box.parentElement?.dataset?.scale || '1') || 1);
        box.classList.add('is-selected', 'enpv-highlight-box');
        box.dataset.pendingEdit = '1';
    }
    markManualSaveNeeded();
    return true;
}

function clearHighlightDragSession() {
    activeHighlightDragSession?.previewEl?.remove?.();
    activeHighlightDragSession = null;
}

function setHighlightMode(active) {
    const nextActive = Boolean(active);
    if (nextActive && document.body.classList.contains('enpv-edit-on')) setEditMode(false);
    if (nextActive && document.body.classList.contains('enpv-add-text-on')) setAddTextMode(false);
    if (nextActive && document.body.classList.contains('enpv-shape-on')) setShapeMode(false);
    if (nextActive && drawModeActive) setDrawMode(false);
    if (nextActive) cancelFieldPlacement({ showStatus: false });
    if (nextActive) signatureFeature?.cancelSignaturePlacement?.();
    if (nextActive) {
        closeNotesPanel();
        hideAnnotationFormatBar();
        shapeToolPanel?.classList.remove('is-visible');
    }
    if (!nextActive) clearHighlightDragSession();
    highlightModeActive = nextActive;
    document.body.classList.toggle('enpv-highlight-on', highlightModeActive);
    syncHighlightToolPanelUi();
    if (highlightModeActive) {
        deselectAnnBox();
        setStatus('Highlight mode active. Select text or drag over the page.');
        window.setTimeout(() => maybeCommitTextSelectionHighlight(), 0);
    } else if (!document.body.classList.contains('enpv-edit-on')
        && !document.body.classList.contains('enpv-add-text-on')
        && !document.body.classList.contains('enpv-shape-on')
        && !drawModeActive) {
        setStatus('Ready.');
    }
    renderAllAnnotationBoxLayers();
    scheduleRenderAllAnnotationBoxLayers();
}

function pageIndexForClientRect(clientRect) {
    if (!clientRect || !pdfViewer?.pagesCount) return -1;
    let bestPageIndex = -1;
    let bestArea = 0;
    for (let pageIndex = 0; pageIndex < pdfViewer.pagesCount; pageIndex += 1) {
        const pageDiv = pdfViewer.getPageView(pageIndex)?.div;
        const pageRect = pageDiv?.getBoundingClientRect?.();
        if (!pageRect) continue;
        const left = Math.max(clientRect.left, pageRect.left);
        const top = Math.max(clientRect.top, pageRect.top);
        const right = Math.min(clientRect.right, pageRect.right);
        const bottom = Math.min(clientRect.bottom, pageRect.bottom);
        const area = Math.max(0, right - left) * Math.max(0, bottom - top);
        if (area > bestArea) {
            bestArea = area;
            bestPageIndex = pageIndex;
        }
    }
    return bestArea > 0 ? bestPageIndex : -1;
}

function canvasRectFromClientRect(pageIndex, clientRect, paddingPx = 1) {
    const pageView = pdfViewer.getPageView(pageIndex);
    const pageDiv = pageView?.div;
    const viewport = pageView?.viewport;
    const pageRect = pageDiv?.getBoundingClientRect?.();
    if (!pageRect || !viewport || !clientRect) return null;
    const left = Math.max(0, Math.min(Number(viewport.width) || pageRect.width, clientRect.left - pageRect.left - paddingPx));
    const top = Math.max(0, Math.min(Number(viewport.height) || pageRect.height, clientRect.top - pageRect.top - paddingPx));
    const right = Math.max(left, Math.min(Number(viewport.width) || pageRect.width, clientRect.right - pageRect.left + paddingPx));
    const bottom = Math.max(top, Math.min(Number(viewport.height) || pageRect.height, clientRect.bottom - pageRect.top + paddingPx));
    const width = right - left;
    const height = bottom - top;
    if (width < 2 || height < 2) return null;
    return { left, top, width, height };
}

function mergeHighlightCanvasRects(rects) {
    const sorted = (Array.isArray(rects) ? rects : [])
        .filter((rect) => rect && rect.width >= 2 && rect.height >= 2)
        .sort((a, b) => (a.pageIndex - b.pageIndex) || (a.top - b.top) || (a.left - b.left));
    const merged = [];
    for (const rect of sorted) {
        const last = merged[merged.length - 1];
        const samePage = last && last.pageIndex === rect.pageIndex;
        const verticalOverlap = samePage
            ? Math.min(last.top + last.height, rect.top + rect.height) - Math.max(last.top, rect.top)
            : 0;
        const minHeight = samePage ? Math.min(last.height, rect.height) : 1;
        const centerDistance = samePage
            ? Math.abs((last.top + (last.height / 2)) - (rect.top + (rect.height / 2)))
            : Number.POSITIVE_INFINITY;
        const horizontalGap = samePage ? rect.left - (last.left + last.width) : Number.POSITIVE_INFINITY;
        const maxInlineGap = Math.max(8, minHeight * 1.5);
        const sameTextLine = verticalOverlap >= minHeight * 0.45
            && centerDistance <= Math.max(3, minHeight * 0.65);
        if (samePage && sameTextLine && horizontalGap <= maxInlineGap) {
            const left = Math.min(last.left, rect.left);
            const top = Math.min(last.top, rect.top);
            const right = Math.max(last.left + last.width, rect.left + rect.width);
            const bottom = Math.max(last.top + last.height, rect.top + rect.height);
            last.left = left;
            last.top = top;
            last.width = right - left;
            last.height = bottom - top;
        } else {
            merged.push({ ...rect });
        }
    }
    return merged;
}

function highlightAnnotationFromCanvasRect(pageIndex, canvasRect) {
    const pageView = pdfViewer.getPageView(pageIndex);
    const viewport = pageView?.viewport;
    const scale = Number(viewport?.scale) || Number(pdfViewer.currentScale) || 1;
    if (!viewport || !(scale > 0) || !canvasRect) return null;
    const pageWidth = Number(viewport.width) || 0;
    const pageHeight = Number(viewport.height) || 0;
    const left = Math.max(0, Math.min(pageWidth, Number(canvasRect.left) || 0));
    const top = Math.max(0, Math.min(pageHeight, Number(canvasRect.top) || 0));
    const width = Math.max(1, Math.min(Number(canvasRect.width) || 0, pageWidth - left));
    const height = Math.max(1, Math.min(Number(canvasRect.height) || 0, pageHeight - top));
    if (width < 2 || height < 2) return null;
    const pdfRect = viewportRectToPdfRect({ left, top, width, height }, viewport, scale);
    if (!pdfRect || pdfRect.w <= 0 || pdfRect.h <= 0) return null;
    const uid = `highlight_${generateUuidV4()}`;
    return normalizeShapeAnnotation({
        _uid: uid,
        id: buildPdfjsAnnotationId(pageIndex, uid),
        pageIndex,
        type: 'shape',
        shapeType: 'highlight',
        userCreated: true,
        userAuthored: true,
        text: '',
        pdfX: pdfRect.x,
        pdfY: pdfRect.y,
        pdfWidth: pdfRect.w,
        pdfHeight: pdfRect.h,
        strokeColor: highlightColor,
        strokeOpacity: 0,
        strokeWidth: 1,
        strokeTransparent: true,
        fillColor: highlightColor,
        fillOpacity: highlightOpacity,
        fillTransparent: false,
        opacity: highlightOpacity,
        rotation: 0,
        locked: false,
        zIndex: 1,
        highlightColor,
        highlightOpacity,
        _originalBox: { ...pdfRect },
        _originalPdfBox: { ...pdfRect },
    });
}

function commitHighlightAnnotations(rects, historyLabel = 'add highlight') {
    const annotations = mergeHighlightCanvasRects(rects)
        .map((rect) => highlightAnnotationFromCanvasRect(rect.pageIndex, rect))
        .filter(Boolean);
    if (!annotations.length) return false;
    pushHistorySnapshot(historyLabel);
    const touchedPages = new Set();
    annotations.forEach((annotation) => {
        upsertPersistedAnnotation(annotation);
        touchedPages.add(annotationPageIndex(annotation));
    });
    touchedPages.forEach((pageIndex) => renderAnnotationBoxLayer(pageIndex));
    markManualSaveNeeded();
    setHighlightToolStatus(`${annotations.length} highlight${annotations.length === 1 ? '' : 's'} added.`);
    setStatus(`${annotations.length} highlight${annotations.length === 1 ? '' : 's'} added.`);
    return true;
}

function selectionBelongsToPdfViewer(selection) {
    if (!selection || selection.isCollapsed || selection.rangeCount <= 0) return false;
    for (let index = 0; index < selection.rangeCount; index += 1) {
        const range = selection.getRangeAt(index);
        const ancestor = range.commonAncestorContainer?.nodeType === Node.ELEMENT_NODE
            ? range.commonAncestorContainer
            : range.commonAncestorContainer?.parentElement;
        if (ancestor?.closest?.('.pdfViewer .textLayer')) return true;
    }
    return false;
}

function highlightRectsFromSelection(selection) {
    const rects = [];
    if (!selection || selection.rangeCount <= 0) return rects;
    for (let rangeIndex = 0; rangeIndex < selection.rangeCount; rangeIndex += 1) {
        const range = selection.getRangeAt(rangeIndex);
        Array.from(range.getClientRects()).forEach((clientRect) => {
            if (!clientRect || clientRect.width < 2 || clientRect.height < 2) return;
            const pageIndex = pageIndexForClientRect(clientRect);
            if (!Number.isFinite(pageIndex) || pageIndex < 0) return;
            const canvasRect = canvasRectFromClientRect(pageIndex, clientRect, 1);
            if (canvasRect) rects.push({ pageIndex, ...canvasRect });
        });
    }
    return rects;
}

function highlightRectsFromDragArea(state, canvasRect) {
    const rects = [];
    const pageIndex = Number(state?.pageIndex);
    const pageDiv = state?.pageDiv;
    const pageRect = state?.pageRect;
    if (!Number.isFinite(pageIndex) || pageIndex < 0 || !pageDiv || !pageRect || !canvasRect) return rects;

    const dragClientRect = [
        state.startClientX,
        state.startClientY,
        state.currentClientX,
        state.currentClientY,
    ].every(Number.isFinite)
        ? {
            left: Math.min(state.startClientX, state.currentClientX),
            top: Math.min(state.startClientY, state.currentClientY),
            right: Math.max(state.startClientX, state.currentClientX),
            bottom: Math.max(state.startClientY, state.currentClientY),
        }
        : {
            left: pageRect.left + canvasRect.left,
            top: pageRect.top + canvasRect.top,
            right: pageRect.left + canvasRect.left + canvasRect.width,
            bottom: pageRect.top + canvasRect.top + canvasRect.height,
        };
    if (dragClientRect.bottom - dragClientRect.top < 6) {
        const centerY = (dragClientRect.top + dragClientRect.bottom) / 2;
        dragClientRect.top = centerY - 3;
        dragClientRect.bottom = centerY + 3;
    }
    const seen = new Set();
    const appendTextClientRects = (clientRects) => {
        Array.from(clientRects || []).forEach((textRect) => {
            if (!textRect || textRect.width < 2 || textRect.height < 2) return;
            const overlapTop = Math.max(textRect.top, dragClientRect.top);
            const overlapBottom = Math.min(textRect.bottom, dragClientRect.bottom);
            const overlapHeight = overlapBottom - overlapTop;
            if (overlapHeight < Math.min(3, textRect.height * 0.2)) return;
            const left = Math.max(textRect.left, dragClientRect.left);
            const right = Math.min(textRect.right, dragClientRect.right);
            if (right - left < 2) return;

            // Keep the complete glyph height, like an inline background color,
            // while clipping the first and last line to the horizontal drag.
            const clientRect = {
                left,
                right,
                top: textRect.top,
                bottom: textRect.bottom,
                width: right - left,
                height: textRect.height,
            };
            const canvasTextRect = canvasRectFromClientRect(pageIndex, clientRect, 0.5);
            if (!canvasTextRect) return;
            const key = [
                Math.round(canvasTextRect.left * 10),
                Math.round(canvasTextRect.top * 10),
                Math.round(canvasTextRect.width * 10),
                Math.round(canvasTextRect.height * 10),
            ].join(':');
            if (seen.has(key)) return;
            seen.add(key);
            rects.push({ pageIndex, ...canvasTextRect });
        });
    };

    pageDiv.querySelectorAll(':scope > .textLayer span:not(.markedContent)').forEach((span) => {
        if (!String(span.textContent || '').trim()) return;
        if (span.closest('[data-enpv-moved-source-hidden="1"], [data-enpv-deleted-source="1"], [data-enpv-promoted-block-hidden="1"], [data-enpv-clean-promoted-hidden="1"]')) return;
        appendTextClientRects(span.getClientRects?.());
    });

    // Edited, added, and promoted text can replace its PDF.js source span
    // with visible overlay markup. Range rectangles give us the same inline
    // fragments (including wrapped lines and formatted runs) that browser
    // selection exposes for untouched text-layer spans.
    pageDiv.querySelectorAll(':scope > .enpv-annotation-box-layer .enpv-text-content').forEach((root) => {
        if (!String(root.textContent || '').trim()) return;
        const style = window.getComputedStyle(root);
        if (style.display === 'none' || style.visibility === 'hidden' || Number(style.opacity) === 0) return;
        const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
        let textNode = walker.nextNode();
        while (textNode) {
            if (String(textNode.nodeValue || '').trim()) {
                const range = document.createRange();
                range.selectNodeContents(textNode);
                appendTextClientRects(range.getClientRects());
                range.detach?.();
            }
            textNode = walker.nextNode();
        }
    });
    return mergeHighlightCanvasRects(rects);
}

function maybeCommitTextSelectionHighlight() {
    if (!highlightModeActive || activeHighlightDragSession) return false;
    const selection = window.getSelection?.();
    if (!selectionBelongsToPdfViewer(selection)) return false;
    const rects = highlightRectsFromSelection(selection);
    if (!rects.length) return false;
    const ok = commitHighlightAnnotations(rects, 'highlight text');
    if (ok) selection.removeAllRanges?.();
    return ok;
}

function startHighlightDrag(ev) {
    if (!highlightModeActive) return;
    if (ev.button !== 0 || dragState || multiDragState || resizeState || shapeRotateState || shapeCutState?.armed || marqueeSelectionState) return;
    if (ev.target?.closest?.('#highlight-tool-panel, .floating-tool-bar, .top-bar, .enpv-ann-menu')) return;
    const pageIndex = pageIndexFromEventTarget(ev.target);
    if (!Number.isFinite(pageIndex) || pageIndex < 0) return;
    const point = pdfjsPointFromPageClient(pageIndex, ev.clientX, ev.clientY);
    if (!point) return;
    ev.preventDefault();
    ev.stopPropagation();
    deselectAnnBox();
    const previewEl = document.createElement('div');
    previewEl.className = 'text-drag-selection enpv-highlight-drag-selection';
    previewEl.style.left = `${point.canvasX}px`;
    previewEl.style.top = `${point.canvasY}px`;
    previewEl.style.width = '0px';
    previewEl.style.height = '0px';
    previewEl.style.setProperty('--enpv-highlight-preview-color', highlightColor);
    previewEl.style.setProperty('--enpv-highlight-preview-opacity', String(highlightOpacity));
    point.pageDiv.appendChild(previewEl);
    activeHighlightDragSession = {
        pageIndex,
        pointerId: ev.pointerId,
        pageDiv: point.pageDiv,
        pageRect: point.pageRect,
        startCanvasX: point.canvasX,
        startCanvasY: point.canvasY,
        startClientX: point.pageRect.left + point.canvasX,
        startClientY: point.pageRect.top + point.canvasY,
        currentClientX: point.pageRect.left + point.canvasX,
        currentClientY: point.pageRect.top + point.canvasY,
        previewEl,
        moved: false,
    };
    try { point.pageDiv.setPointerCapture?.(ev.pointerId); } catch (_) {}
}

function updateHighlightDrag(ev) {
    const state = activeHighlightDragSession;
    if (!state || state.pointerId !== ev.pointerId) return;
    ev.preventDefault();
    ev.stopPropagation();
    const currentX = Math.max(0, Math.min(ev.clientX - state.pageRect.left, state.pageRect.width));
    const currentY = Math.max(0, Math.min(ev.clientY - state.pageRect.top, state.pageRect.height));
    const left = Math.min(state.startCanvasX, currentX);
    const top = Math.min(state.startCanvasY, currentY);
    const width = Math.abs(currentX - state.startCanvasX);
    const height = Math.abs(currentY - state.startCanvasY);
    state.currentClientX = state.pageRect.left + currentX;
    state.currentClientY = state.pageRect.top + currentY;
    state.previewEl.style.left = `${left}px`;
    state.previewEl.style.top = `${top}px`;
    state.previewEl.style.width = `${width}px`;
    state.previewEl.style.height = `${height}px`;
    if (width > 4 || height > 4) state.moved = true;
}

function finishHighlightDrag(ev) {
    const state = activeHighlightDragSession;
    if (!state || state.pointerId !== ev.pointerId) return;
    ev.preventDefault();
    ev.stopPropagation();
    try { state.pageDiv?.releasePointerCapture?.(ev.pointerId); } catch (_) {}
    const left = Number.parseFloat(state.previewEl.style.left || '0') || 0;
    const top = Number.parseFloat(state.previewEl.style.top || '0') || 0;
    const width = Number.parseFloat(state.previewEl.style.width || '0') || 0;
    const height = Number.parseFloat(state.previewEl.style.height || '0') || 0;
    clearHighlightDragSession();
    if (!state.moved || width < 6) return;
    const canvasRect = { left, top, width, height };
    const textRects = highlightRectsFromDragArea(state, canvasRect);
    if (textRects.length) {
        commitHighlightAnnotations(textRects, 'highlight text');
        return;
    }
    if (height < 6) return;
    commitHighlightAnnotations([{ pageIndex: state.pageIndex, ...canvasRect }], 'add highlight');
}

function cancelHighlightDrag(ev) {
    const state = activeHighlightDragSession;
    if (!state || state.pointerId !== ev.pointerId) return;
    try { state.pageDiv?.releasePointerCapture?.(ev.pointerId); } catch (_) {}
    clearHighlightDragSession();
}

function createNewTextAnnotation(pageIndex, canvasX, canvasY, canvasWidth = null, canvasHeight = null) {
    const pageView = pdfViewer.getPageView(pageIndex);
    const viewport = pageView?.viewport;
    if (!viewport) return null;
    const scale = Number(viewport.scale) || Number(pdfViewer.currentScale) || 1;
    if (!(scale > 0)) return null;

    const defaultFontSize = 12;
    const defaultWidthPts = 36;
    const defaultHeightPts = Math.ceil(defaultFontSize * 1.25);
    const hasDraggedSize = Number.isFinite(canvasWidth) && Number.isFinite(canvasHeight);
    const draggedPdfRect = hasDraggedSize
        ? viewportRectToPdfRect({
            left: Number(canvasX),
            top: Number(canvasY),
            width: Math.max(60, Number(canvasWidth)),
            height: Math.max(28, Number(canvasHeight)),
        }, viewport, scale)
        : null;
    const clickedPdfPoint = viewportPointToPdfPoint(canvasX, canvasY, viewport, scale);
    if (!clickedPdfPoint) return null;
    const widthPts = draggedPdfRect ? draggedPdfRect.w : defaultWidthPts;
    const heightPts = draggedPdfRect ? draggedPdfRect.h : defaultHeightPts;
    const rawX = draggedPdfRect ? draggedPdfRect.x : clickedPdfPoint.x;
    const rawY = draggedPdfRect ? draggedPdfRect.y : clickedPdfPoint.y - defaultHeightPts;
    const pageSizePts = viewportPdfDimensions(viewport, scale);
    const pageWidthPts = pageSizePts.width;
    const pageHeightPts = pageSizePts.height;
    const pdfX = Math.max(0, Math.min(rawX, Math.max(0, pageWidthPts - widthPts)));
    const pdfY = Math.max(0, Math.min(rawY, Math.max(0, pageHeightPts - heightPts)));
    const uid = `new_${generateUuidV4()}`;
    const id = buildPdfjsAnnotationId(pageIndex, uid);
    return {
        id,
        type: 'text',
        pageIndex,
        text: '',
        originalText: '',
        pdfX,
        pdfY,
        pdfWidth: widthPts,
        pdfHeight: heightPts,
        fontSize: defaultFontSize,
        requestedFontSize: defaultFontSize,
        lineHeight: defaultFontSize * 1.2,
        fontFamily: 'Helvetica',
        fontWeight: '400',
        fontStyle: 'normal',
        textColor: '#000000',
        color: '#000000',
        backgroundColor: 'transparent',
        opacity: 1,
        underline: false,
        textAlign: 'left',
        verticalAlign: 'top',
        locked: false,
        zIndex: 6,
        savedTextOverlay: true,
        styleDirty: true,
        userCreated: true,
        userAuthored: true,
        userSizedTextBox: hasDraggedSize,
        userForcedRichText: true,
        pdfjsEditorMode: 'rich',
        skipPdfjsSourceMask: true,
        pdfjsAnchorUid: uid,
        _originalBox: { x: pdfX, y: pdfY, w: widthPts, h: heightPts },
        _originalPdfBox: { x: pdfX, y: pdfY, w: widthPts, h: heightPts },
    };
}

function createImageAnnotationOnPage(pageIndex, asset, centerPt = null) {
    if (!asset || (!asset.dataUrl && !asset.src)) return null;
    const pageView = pdfViewer.getPageView(pageIndex);
    const viewport = pageView?.viewport;
    if (!viewport) return null;
    const scale = Number(viewport.scale) || Number(pdfViewer.currentScale) || 1;
    if (!(scale > 0)) return null;

    const pageSizePts = viewportPdfDimensions(viewport, scale);
    const pageWidthPts = pageSizePts.width;
    const pageHeightPts = pageSizePts.height;
    const intrinsicWidth = Math.max(1, Number(asset.width || asset.intrinsicWidth) || 1);
    const intrinsicHeight = Math.max(1, Number(asset.height || asset.intrinsicHeight) || 1);
    const aspectRatio = intrinsicWidth / intrinsicHeight;
    const maxWidthPts = pageWidthPts * 0.4;
    const maxHeightPts = pageHeightPts * 0.28;
    let pdfWidth = Math.max(72, Math.min(220, maxWidthPts));
    let pdfHeight = pdfWidth / Math.max(0.01, aspectRatio);
    if (pdfHeight > maxHeightPts) {
        pdfHeight = maxHeightPts;
        pdfWidth = pdfHeight * Math.max(0.01, aspectRatio);
    }
    pdfWidth = Math.max(48, Math.min(pdfWidth, pageWidthPts - 24));
    pdfHeight = Math.max(24, Math.min(pdfHeight, pageHeightPts - 24));
    const centerX = Number.isFinite(Number(centerPt?.x)) ? Number(centerPt.x) : pageWidthPts / 2;
    const centerY = Number.isFinite(Number(centerPt?.y)) ? Number(centerPt.y) : pageHeightPts / 2;
    const pdfX = Math.max(12, Math.min(pageWidthPts - pdfWidth - 12, centerX - (pdfWidth / 2)));
    const pdfY = Math.max(12, Math.min(pageHeightPts - pdfHeight - 12, centerY - (pdfHeight / 2)));
    const uid = `new_${generateUuidV4()}`;
    const id = buildPdfjsAnnotationId(pageIndex, uid);
    const annotation = normalizeImageAnnotation({
        id,
        _uid: uid,
        type: 'image',
        pageIndex,
        pdfX,
        pdfY,
        pdfWidth,
        pdfHeight,
        rotation: 0,
        opacity: 1,
        locked: false,
        zIndex: 6,
        userCreated: true,
        dataUrl: asset.dataUrl || '',
        src: asset.src || '',
        fileName: asset.fileName || 'image.png',
        mimeType: asset.mimeType || 'image/png',
        assetPath: asset.assetPath || asset.imagePath || null,
        intrinsicWidth,
        intrinsicHeight,
        pdfjsSourceX: pdfX,
        pdfjsSourceY: pdfY,
        pdfjsSourceW: pdfWidth,
        pdfjsSourceH: pdfHeight,
        pdfjsSourcePageHeight: pageHeightPts,
        pdfjsAnchorUid: uid,
        text: '',
        _originalBox: { x: pdfX, y: pdfY, w: pdfWidth, h: pdfHeight },
        _originalPdfBox: { x: pdfX, y: pdfY, w: pdfWidth, h: pdfHeight },
    });
    return annotation;
}

function createImageBoxElement(annotation, pageIndex, viewport, scale, editModeOn, hooks) {
    if (!isImageAnnotation(annotation)) return null;
    const pdfRect = annotationCurrentPdfBox(annotation) || annotation._originalPdfBox || null;
    const rect = pdfRectToCanvasRect(pdfRect, viewport, scale);
    if (!rect || rect.width <= 0 || rect.height <= 0) return null;

    const box = document.createElement('div');
    box.className = 'enpv-annotation-box enpv-image-box is-persisted-overlay';
    box.dataset.uid = String(annotation.pdfjsAnchorUid || annotation.id || `${pageIndex}:image`);
    box.dataset.annotationId = String(annotation.id || '');
    box.dataset.pageIndex = String(pageIndex);
    box.dataset.annotationType = 'image';
    box.dataset.locked = annotation.locked ? '1' : '0';
    box.dataset.zIndex = String(Number(annotation.zIndex) || (isDirectDrawEraserAnnotation(annotation) ? 1000 : (isDirectDrawAnnotation(annotation) ? 2 : 6)));
    if (isDirectDrawAnnotation(annotation)) {
        box.dataset.directDraw = '1';
        box.dataset.directDrawTool = normalizeDirectDrawTool(annotation.directDrawTool);
        box.classList.add('enpv-direct-draw-box');
    }
    box.dataset.basePageHeight = String(viewportPdfDimensions(viewport, scale).height);
    box.style.left = `${rect.left}px`;
    box.style.top = `${rect.top}px`;
    box.style.width = `${Math.max(1, rect.width)}px`;
    box.style.height = `${Math.max(1, rect.height)}px`;
    box.style.zIndex = box.dataset.zIndex;
    box.style.opacity = String(normalizeOpacity(annotation.opacity, 1));
    box.classList.toggle('is-locked', annotation.locked === true);

    const img = document.createElement('img');
    img.className = 'enpv-image-img';
    img.draggable = false;
    const vectorSrc = isDirectDrawAnnotation(annotation) ? directDrawVectorToSvgDataUrl(annotation.directDrawVector) : '';
    const src = vectorSrc || getImageAnnotationSource(annotation);
    if (src) img.src = src;
    img.alt = isDirectDrawAnnotation(annotation) ? 'Drawing' : 'Image';
    appendViewportRotatedContent(box, img, viewport, rect);

    const label = document.createElement('span');
    label.className = 'enpv-image-selection-label';
    label.textContent = isDirectDrawAnnotation(annotation) ? 'drawing' : 'image';
    box.appendChild(label);

    if (hooks) {
        box.addEventListener('pointerdown', hooks.onAnnBoxPointerDown);
        for (const edge of ['nw', 'ne', 'sw', 'se']) {
            const handle = document.createElement('div');
            handle.className = `enpv-resize-handle ${edge}`;
            handle.dataset.edge = edge;
            handle.addEventListener('pointerdown', hooks.onResizeHandlePointerDown);
            box.appendChild(handle);
        }
    } else {
        box.classList.add('is-readonly');
    }
    return box;
}

function createFieldAnnotationOnPage(pageIndex, fieldKind = 'text', centerPt = null) {
    const pageView = pdfViewer.getPageView(pageIndex);
    const viewport = pageView?.viewport;
    if (!viewport) return null;
    const scale = Number(viewport.scale) || Number(pdfViewer.currentScale) || 1;
    if (!(scale > 0)) return null;

    const kind = normalizeFieldKind(fieldKind);
    const pageSizePts = viewportPdfDimensions(viewport, scale);
    const pageWidthPts = pageSizePts.width;
    const pageHeightPts = pageSizePts.height;
    const defaultWidth = kind === 'signature' ? 180 : 190;
    const defaultHeight = kind === 'signature' ? 54 : 28;
    const pdfWidth = Math.max(48, Math.min(defaultWidth, pageWidthPts - 24));
    const pdfHeight = Math.max(18, Math.min(defaultHeight, pageHeightPts - 24));
    const centerX = Number.isFinite(Number(centerPt?.x)) ? Number(centerPt.x) : pageWidthPts / 2;
    const centerY = Number.isFinite(Number(centerPt?.y)) ? Number(centerPt.y) : pageHeightPts / 2;
    const pdfX = Math.max(12, Math.min(pageWidthPts - pdfWidth - 12, centerX - (pdfWidth / 2)));
    const pdfY = Math.max(12, Math.min(pageHeightPts - pdfHeight - 12, centerY - (pdfHeight / 2)));
    const uid = `field_${generateUuidV4()}`;
    return normalizeFieldAnnotation({
        id: buildPdfjsAnnotationId(pageIndex, uid),
        _uid: uid,
        type: 'field',
        pageIndex,
        fieldKind: kind,
        fieldName: '',
        pdfX,
        pdfY,
        pdfWidth,
        pdfHeight,
        locked: false,
        zIndex: 7,
        userCreated: true,
        userAuthored: true,
        pdfjsAnchorUid: uid,
        text: '',
        _originalBox: { x: pdfX, y: pdfY, w: pdfWidth, h: pdfHeight },
        _originalPdfBox: { x: pdfX, y: pdfY, w: pdfWidth, h: pdfHeight },
    });
}

function createFieldBoxElement(annotation, pageIndex, viewport, scale, hooks) {
    if (!isFieldAnnotation(annotation)) return null;
    const normalized = normalizeFieldAnnotation({ ...annotation });
    const pdfRect = annotationCurrentPdfBox(normalized) || normalized._originalPdfBox || null;
    const rect = pdfRectToCanvasRect(pdfRect, viewport, scale);
    if (!rect || rect.width <= 0 || rect.height <= 0) return null;

    const box = document.createElement('div');
    box.className = 'enpv-annotation-box enpv-field-box is-persisted-overlay';
    box.dataset.uid = String(normalized.pdfjsAnchorUid || normalized._uid || normalized.id || `${pageIndex}:field`);
    box.dataset.annotationId = String(normalized.id || '');
    box.dataset.pageIndex = String(pageIndex);
    box.dataset.annotationType = 'field';
    box.dataset.fieldKind = normalizeFieldKind(normalized.fieldKind);
    box.dataset.fieldName = String(normalized.fieldName || '');
    box.dataset.locked = normalized.locked ? '1' : '0';
    box.dataset.zIndex = String(Number(normalized.zIndex) || 7);
    box.dataset.basePageHeight = String(viewportPdfDimensions(viewport, scale).height);
    box.style.left = `${rect.left}px`;
    box.style.top = `${rect.top}px`;
    box.style.width = `${Math.max(1, rect.width)}px`;
    box.style.height = `${Math.max(1, rect.height)}px`;
    box.style.zIndex = box.dataset.zIndex;
    box.classList.toggle('is-locked', normalized.locked === true);

    const preview = document.createElement('div');
    preview.className = 'enpv-field-preview';
    box.appendChild(preview);

    const label = document.createElement('span');
    label.className = 'enpv-field-selection-label';
    label.textContent = box.dataset.fieldKind === 'signature' ? 'signature field' : 'text field';
    box.appendChild(label);

    if (hooks) {
        box.addEventListener('pointerdown', hooks.onAnnBoxPointerDown);
        for (const edge of ['nw', 'ne', 'sw', 'se']) {
            const handle = document.createElement('div');
            handle.className = `enpv-resize-handle ${edge}`;
            handle.dataset.edge = edge;
            handle.addEventListener('pointerdown', hooks.onResizeHandlePointerDown);
            box.appendChild(handle);
        }
    } else {
        box.classList.add('is-readonly');
    }
    return box;
}

/**
 * Nudge a freshly placed text box back inside its page.
 *
 * createNewTextAnnotation() clamps against a nominal one-line height, but the
 * box is laid out at its own line-height plus padding, which is taller. A box
 * placed hard against an edge therefore rendered outside the page even though
 * its annotation looked clamped — and a save, which reads geometry back off the
 * DOM, then persisted the overhang.
 *
 * Only the position moves: the rendered size is the renderer's business, and
 * measuring it here keeps this correct if the line-height or padding changes.
 *
 * @returns {boolean} true when the annotation was moved and needs re-rendering
 */
function keepNewTextBoxWithinPage(annotation, box, pageIndex) {
    const viewport = pdfViewer.getPageView(pageIndex)?.viewport;
    const scale = Number(viewport?.scale) || Number.parseFloat(box?.dataset?.renderScale || '');
    const pageDiv = box?.closest?.('.page');
    if (!viewport || !(scale > 0) || !pageDiv) return false;

    const rect = box.getBoundingClientRect();
    const pageRect = pageDiv.getBoundingClientRect();
    if (!(rect.height > 0) || !(pageRect.height > 0)) return false;

    const { width: pageWidthPts, height: pageHeightPts } = viewportPdfDimensions(viewport, scale);
    if (!(pageWidthPts > 0) || !(pageHeightPts > 0)) return false;

    // Laid-out geometry in PDF points, measured from the page's top-left.
    const left = (rect.left - pageRect.left) / scale;
    const top = (rect.top - pageRect.top) / scale;
    const width = rect.width / scale;
    const height = rect.height / scale;

    const nextLeft = Math.min(Math.max(0, left), Math.max(0, pageWidthPts - width));
    const nextTop = Math.min(Math.max(0, top), Math.max(0, pageHeightPts - height));
    if (Math.abs(nextLeft - left) < 0.01 && Math.abs(nextTop - top) < 0.01) return false;

    // PDF space is bottom-up, and pdfY is the box's bottom edge.
    const pdfX = nextLeft;
    const pdfY = pageHeightPts - nextTop - (Number(annotation.pdfHeight) || height);
    annotation.pdfX = pdfX;
    annotation.pdfY = pdfY;
    const box0 = { x: pdfX, y: pdfY, w: annotation.pdfWidth, h: annotation.pdfHeight };
    annotation._originalBox = { ...box0 };
    annotation._originalPdfBox = { ...box0 };
    return true;
}

function createNewTextBoxOnPage(pageIndex, canvasX, canvasY, canvasWidth = null, canvasHeight = null) {
    const annotation = createNewTextAnnotation(pageIndex, canvasX, canvasY, canvasWidth, canvasHeight);
    if (!annotation) return null;
    pushHistorySnapshot('add text');
    upsertPersistedAnnotation(annotation);
    renderAnnotationBoxLayer(pageIndex);
    const findBox = () => pdfViewer.getPageView(pageIndex)?.div
        ?.querySelector(`.enpv-annotation-box[data-annotation-id="${cssEscape(annotation.id)}"]`) || null;
    let box = findBox();
    if (box && keepNewTextBoxWithinPage(annotation, box, pageIndex)) {
        upsertPersistedAnnotation(annotation);
        renderAnnotationBoxLayer(pageIndex);
        box = findBox();
    }
    if (box) {
        selectAnnBox(box);
        beginEditMode(box);
        box.dataset.pendingEdit = '1';
        positionAnnMenuOver(box);
        updateAnnotationFormatBarForBox(box);
    }
    markManualSaveNeeded();
    return annotation;
}

function pickImageImportTargetPage() {
    const pageDivs = Array.from(container?.querySelectorAll?.('.pdfViewer .page[data-page-number]') || []);
    if (!pageDivs.length) return null;
    const containerRect = container.getBoundingClientRect();
    const viewportLeft = containerRect.left;
    const viewportRight = containerRect.right;
    const viewportTop = containerRect.top;
    const viewportBottom = containerRect.bottom;
    const viewportCenterX = (viewportLeft + viewportRight) / 2;
    const viewportCenterY = (viewportTop + viewportBottom) / 2;
    let best = null;
    let bestOverlap = -Infinity;
    for (const pageDiv of pageDivs) {
        const rect = pageDiv.getBoundingClientRect();
        const overlapW = Math.max(0, Math.min(rect.right, viewportRight) - Math.max(rect.left, viewportLeft));
        const overlapH = Math.max(0, Math.min(rect.bottom, viewportBottom) - Math.max(rect.top, viewportTop));
        const overlap = overlapW * overlapH;
        if (overlap > bestOverlap) {
            bestOverlap = overlap;
            best = { pageDiv, rect };
        }
    }
    if (!best) return null;
    const pageNumber = Number.parseInt(best.pageDiv.dataset.pageNumber || '1', 10);
    const pageIndex = Number.isFinite(pageNumber) ? pageNumber - 1 : 0;
    const pageView = pdfViewer.getPageView(pageIndex);
    const viewport = pageView?.viewport;
    const scale = Number(viewport?.scale) || Number(pdfViewer.currentScale) || 1;
    if (!viewport || !(scale > 0)) return { pageIndex, centerPt: null };
    const localX = Math.max(0, Math.min(best.rect.width || 1, viewportCenterX - best.rect.left));
    const localY = Math.max(0, Math.min(best.rect.height || 1, viewportCenterY - best.rect.top));
    return {
        pageIndex,
        centerPt: {
            x: localX / scale,
            y: (Number(viewport.height) - localY) / scale,
        },
    };
}

function insertImageImportAsset(asset, target = null) {
    if (!asset || (!asset.dataUrl && !asset.src)) return null;
    const pageIndex = Number.isInteger(target?.pageIndex) ? target.pageIndex : Math.max(0, pdfViewer.currentPageNumber - 1);
    const annotation = createImageAnnotationOnPage(pageIndex, asset, target?.centerPt || null);
    if (!annotation) return null;
    pushHistorySnapshot('add image');
    upsertPersistedAnnotation(annotation);
    renderAnnotationBoxLayer(pageIndex);
    requestAnimationFrame(() => {
        const pageDiv = pdfViewer.getPageView(pageIndex)?.div;
        const box = pageDiv?.querySelector(`.enpv-annotation-box[data-annotation-id="${cssEscape(annotation.id)}"]`) || null;
        if (box) selectAnnBox(box);
    });
    markManualSaveNeeded();
    setStatus('Image placed. Drag to reposition or resize, then click Save.');
    return annotation;
}

function insertFieldOnPage(fieldKind, target = null) {
    const pageIndex = Number.isInteger(target?.pageIndex) ? target.pageIndex : Math.max(0, pdfViewer.currentPageNumber - 1);
    const annotation = createFieldAnnotationOnPage(pageIndex, fieldKind, target?.centerPt || null);
    if (!annotation) return null;
    pushHistorySnapshot(`add ${annotation.fieldKind === 'signature' ? 'signature' : 'text'} field`);
    upsertPersistedAnnotation(annotation);
    renderAnnotationBoxLayer(pageIndex);
    requestAnimationFrame(() => {
        const pageDiv = pdfViewer.getPageView(pageIndex)?.div;
        const box = pageDiv?.querySelector(`.enpv-annotation-box[data-annotation-id="${cssEscape(annotation.id)}"]`) || null;
        if (box) selectAnnBox(box);
    });
    markManualSaveNeeded();
    setStatus(`${annotation.fieldKind === 'signature' ? 'Signature' : 'Text'} field placed. Drag to reposition or resize, then click Save.`);
    return annotation;
}

function cancelImagePlacement(options = {}) {
    if (!imagePlacementState) return;
    imagePlacementState = null;
    document.body.classList.remove('enpv-image-placing');
    if (options.showStatus !== false) setStatus('Image placement cancelled.');
}

function cancelFieldPlacement(options = {}) {
    if (!fieldPlacementState) return;
    fieldPlacementState = null;
    document.body.classList.remove('enpv-field-placing');
    floatingFieldsButton?.classList.remove('active', 'is-active');
    floatingFieldsButton?.setAttribute('aria-pressed', 'false');
    if (options.showStatus !== false) setStatus('Field placement cancelled.');
}

function beginImagePlacement(asset) {
    if (!asset || (!asset.dataUrl && !asset.src)) return false;
    imagePlacementState = { asset: { ...asset } };
    document.body.classList.add('enpv-image-placing');
    setStatus('Click the page location for the image.');
    return true;
}

function beginFieldPlacement(fieldKind) {
    const kind = normalizeFieldKind(fieldKind);
    cancelImagePlacement({ showStatus: false });
    setAddTextMode(false, { skipRender: true });
    setShapeMode(false);
    setHighlightMode(false);
    if (drawModeActive) setDrawMode(false);
    signatureFeature?.cancelSignaturePlacement?.();
    fieldPlacementState = { fieldKind: kind };
    document.body.classList.add('enpv-field-placing');
    floatingFieldsButton?.classList.add('active', 'is-active');
    floatingFieldsButton?.setAttribute('aria-pressed', 'true');
    setStatus(`Click the page location for the ${kind === 'signature' ? 'signature' : 'text'} field.`);
    return true;
}

function placePendingImageAtPointer(event) {
    if (!imagePlacementState) return;
    if (event.button !== 0) return;
    const pageIndex = pageIndexFromEventTarget(event.target);
    if (!Number.isFinite(pageIndex) || pageIndex < 0) return;
    const point = pdfjsPointFromPageClient(pageIndex, event.clientX, event.clientY);
    if (!point) return;

    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation?.();
    const asset = imagePlacementState.asset;
    const annotation = insertImageImportAsset(asset, {
        pageIndex,
        centerPt: { x: point.pdfX, y: point.pdfY },
    });
    if (!annotation) {
        setStatus('Could not place that image.', true);
        return;
    }
    cancelImagePlacement({ showStatus: false });
}

function placePendingFieldAtPointer(event) {
    if (!fieldPlacementState) return;
    if (event.button !== 0) return;
    const pageIndex = pageIndexFromEventTarget(event.target);
    if (!Number.isFinite(pageIndex) || pageIndex < 0) return;
    const point = pdfjsPointFromPageClient(pageIndex, event.clientX, event.clientY);
    if (!point) return;

    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation?.();
    const annotation = insertFieldOnPage(fieldPlacementState.fieldKind, {
        pageIndex,
        centerPt: { x: point.pdfX, y: point.pdfY },
    });
    if (!annotation) {
        setStatus('Could not place that field.', true);
        return;
    }
    cancelFieldPlacement({ showStatus: false });
}

function findExistingAnnotationBoxForSpan(spanEl, pageIndex, layer = null) {
    const persistentId = String(spanEl?.dataset?.enpvPersistentId || '').trim();
    if (!persistentId || !Number.isFinite(pageIndex) || pageIndex < 0) return null;
    const selector = [
        `.enpv-annotation-box[data-annotation-id="${cssEscape(persistentId)}"]`,
        `.enpv-annotation-box[data-persisted-annotation-id="${cssEscape(persistentId)}"]`,
    ].join(',');
    return layer?.querySelector?.(selector)
        || pdfViewer.getPageView(pageIndex)?.div?.querySelector?.(selector)
        || null;
}

function spanCenterCoveredByEditableOverlay(spanEl) {
    const rect = spanEl?.getBoundingClientRect?.();
    if (!rect || rect.width <= 0 || rect.height <= 0) return false;
    const hit = document.elementFromPoint(rect.left + (rect.width / 2), rect.top + (rect.height / 2));
    const box = hit?.closest?.('.enpv-annotation-box') || null;
    return Boolean(box && !box.classList.contains('enpv-shape-box'));
}

function spanCoveredByRenderedPromotedSourceBlock(spanEl, pageIndex) {
    const rect = spanEl?.getBoundingClientRect?.();
    if (!rect || rect.width <= 0 || rect.height <= 0) return false;
    const pageDiv = pdfViewer.getPageView(pageIndex)?.div;
    if (!pageDiv) return false;
    const targetText = sourceSpanOriginalText(spanEl) || spanEl.textContent || '';
    const centerX = rect.left + (rect.width / 2);
    const centerY = rect.top + (rect.height / 2);
    return Array.from(pageDiv.querySelectorAll('.enpv-annotation-box.is-promoted-source-block')).some((box) => {
        const blockRect = box.getBoundingClientRect();
        if (centerX < blockRect.left
            || centerX > blockRect.right
            || centerY < blockRect.top
            || centerY > blockRect.bottom) return false;
        const blockText = box.querySelector('.enpv-text-content')?.textContent || baseTextForBox(box) || '';
        return textCanBelongToPromotedSourceBlock(blockText, targetText);
    });
}

function appendMissingEditableSourceHandlesForPage(pageIndex, layer, textLayerEl, options = {}) {
    if (!layer || !textLayerEl || !Number.isFinite(pageIndex) || pageIndex < 0) return;
    const pageView = pdfViewer.getPageView(pageIndex);
    const viewport = pageView?.viewport;
    const scale = Number(viewport?.scale) || Number(pdfViewer.currentScale) || 1;
    const promotedSourceBlockOwners = Array.isArray(options.promotedSourceBlockOwners)
        ? options.promotedSourceBlockOwners
        : [];
    const spans = Array.from(textLayerEl.querySelectorAll(`span[data-enpv-page="${pageIndex}"][data-enpv-group-anchor="1"]`));
    for (const span of spans) {
        if (!String(span.textContent || sourceSpanOriginalText(span) || '').trim()) continue;
        if (span.dataset.enpvMovedSourceHidden === '1'
            || span.dataset.enpvPromotedBlockHidden === '1'
            || span.dataset.enpvDeletedSource === '1') continue;
        const group = sourceGroupForSpan(span);
        if (group && promotedSourceBlocksOwnSourceGroup(promotedSourceBlockOwners, group, viewport, scale)) continue;
        if (findExistingAnnotationBoxForSpan(span, pageIndex, layer)) continue;
        if (spanCenterCoveredByEditableOverlay(span)) continue;
        createAnnotationBoxFromSpan(span);
    }
}

function removeAddTextPreview() {
    if (addTextCreationState?.previewEl) addTextCreationState.previewEl.remove();
    addTextCreationState = null;
}

function createAnnotationBoxFromSpan(spanEl) {
    if (!spanEl) return null;
    if (hydratingPersistedAnnotations && annotationBoxesByPage.size === 0) return null;
    // Source rows already claimed by a promoted/moved overlay must not spawn a
    // separate on-demand source editor box (that would draw the row twice).
    if (spanEl.dataset.enpvPromotedBlockHidden === '1'
        || spanEl.dataset.enpvMovedSourceHidden === '1') return null;
    const pageIndex = Number.parseInt(spanEl.dataset.enpvPage || '-1', 10);
    if (!Number.isFinite(pageIndex) || pageIndex < 0) return null;
    const pageView = pdfViewer.getPageView(pageIndex);
    const viewport = pageView?.viewport;
    const textLayerEl = pageView?.textLayer?.div || pageView?.textLayer?.textLayerDiv;
    if (!pageView?.div || !viewport || !textLayerEl) return null;
    if (spanCoveredByRenderedPromotedSourceBlock(spanEl, pageIndex)) {
        spanEl.dataset.enpvPromotedBlockHidden = '1';
        return null;
    }

    const scale = Number(viewport.scale) || Number(pdfViewer.currentScale) || 1;
    const layer = ensureAnnotationBoxLayer(pageIndex, scale);
    if (!layer) return null;

    const existingPersistentBox = findExistingAnnotationBoxForSpan(spanEl, pageIndex, layer);
    if (existingPersistentBox) return existingPersistentBox;

    const sourceInfo = sourceInfoForSpan(spanEl);
    if (!sourceInfo) return null;
    const uid = sourceInfo.uid;
    const spanRect = sourceInfo.clientRect || spanEl.getBoundingClientRect();
    const anchorSpan = sourceInfo.anchor || spanEl;
    const rawRect = {
        left: sourceInfo.rect.left,
        top: sourceInfo.rect.top,
        width: sourceInfo.rect.width,
        height: sourceInfo.rect.height,
    };
    if (rawRect.width <= 0 || rawRect.height <= 0) return null;
    const onDemandFsPx = parseFloat(window.getComputedStyle(anchorSpan)?.fontSize || '') || spanRect.height || rawRect.height;
    const sourceGroup = sourceGroupForSpan(spanEl);
    const rect = expandSourceRectToGlyphLine(rawRect, onDemandFsPx, sourceGroup, sourceGroupsByPage.get(pageIndex)?.groups);
    const textLayerRect = textLayerEl.getBoundingClientRect?.();
    if (textLayerRect && sourceGroupLooksLikeAcroWidgetChrome(
        sourceGroup,
        rect,
        collectAcroWidgetLayerRects(pageView, pageView.div, textLayerRect),
        scale,
    )) return null;

    const sourceBbox = {
        x: rect.left / scale,
        y: (Number(viewport.height) - (rect.top + rect.height)) / scale,
        w: rect.width / scale,
        h: rect.height / scale,
    };
    const matchedAnnotation = findPersistedAnnotationForSpan(
        pageIndex,
        sourceBbox,
        sourceInfo.text || '',
        sourceInfo.text || sourceSpanOriginalText(spanEl) || spanEl.textContent || '',
        false,
        uid,
    );
    const handleUid = sourceHandleUid(pageIndex, uid, matchedAnnotation);
    const annotationId = sourceHandleAnnotationId(pageIndex, uid, matchedAnnotation);
    if (deletedPdfjsSourceOwnsSpan(
        pageIndex,
        sourceBbox,
        sourceInfo.text || '',
        sourceInfo.text || sourceSpanOriginalText(spanEl) || spanEl.textContent || '',
        uid,
        annotationId,
    )) {
        spanEl.dataset.enpvDeletedSource = '1';
        return null;
    }
    delete spanEl.dataset.enpvDeletedSource;
    const existingBox = layer.querySelector(`.enpv-annotation-box[data-uid="${cssEscape(handleUid)}"]`);
    if (existingBox) return existingBox;
    const sourceSnapshotRect = annotationBaselinePdfBox(matchedAnnotation) || sourceBbox;
    const baseRect = matchedAnnotation?._baselinePdfBox || sourceSnapshotRect;
    const baseText = String(matchedAnnotation?.pdfjsSourceText || matchedAnnotation?.originalText || sourceInfo.text || sourceSpanOriginalText(spanEl) || spanEl.textContent || '');

    const box = document.createElement('div');
    box.className = 'enpv-annotation-box is-on-demand';
    box.dataset.uid = handleUid;
    box.dataset.annotationId = annotationId;
    box.dataset.pageIndex = String(pageIndex);
    setOriginalTextForBox(box, matchedAnnotation?.originalText || baseText);
    box.dataset.occurrence = String(sourceInfo.occurrence || 0);
    box.dataset.sourceBboxX = String(sourceSnapshotRect.x);
    box.dataset.sourceBboxY = String(sourceSnapshotRect.y);
    box.dataset.sourceBboxW = String(sourceSnapshotRect.w);
    box.dataset.sourceBboxH = String(sourceSnapshotRect.h);
    box.dataset.baseBboxX = String(baseRect.x);
    box.dataset.baseBboxY = String(baseRect.y);
    box.dataset.baseBboxW = String(baseRect.w);
    box.dataset.baseBboxH = String(baseRect.h);
    box.dataset.basePageHeight = String(Number(matchedAnnotation?.pdfjsSourcePageHeight) || (Number(viewport.height) / scale));
    setBaseTextForBox(box, baseText);
    box.dataset.renderScale = String(scale);
    if (boolish(matchedAnnotation?.styleDirty)) box.dataset.styleDirty = '1';
    const displayRect = sourceBoxDisplayRect(rect);
    box.style.left = `${rect.left}px`;
    box.style.top = `${rect.top}px`;
    box.style.width = `${Math.max(1, displayRect.width)}px`;
    box.style.height = `${Math.max(1, displayRect.height)}px`;
    for (const span of sourceGroupForSpan(spanEl)?.spans || [spanEl]) {
        span.dataset.enpvPersistentId = annotationId;
    }

    const sourcePageHeight = Number(viewport.height) / scale;
    const sourceStyle = promotedSourceStyleForPdfjsSource(pageIndex, sourceBbox, sourceInfo.text || baseText, sourcePageHeight);
    const cs = window.getComputedStyle(anchorSpan);
    let fsPx = parseFloat(cs.fontSize) || 0;
    if (spanRect.height > fsPx) fsPx = spanRect.height;
    if (!(fsPx > 1)) fsPx = Math.max(8, rect.height);
    captureSourceSpanMetrics(box, anchorSpan, spanRect, scale, pageView.div, sourceStyle);
    captureSourceSpanRunsForBox(box, sourceGroupForSpan(anchorSpan), pageView?.textLayer?.div || pageView?.textLayer?.textLayerDiv || null);
    restoreSourceSpanMetricsFromAnnotation(box, matchedAnnotation);
    if (matchedAnnotation?.fontFamily) box.style.setProperty('--enpv-font-family', matchedAnnotation.fontFamily);
    if (Number(matchedAnnotation?.fontSize) > 0) box.dataset.fontSizePts = String(Number(matchedAnnotation.fontSize));
    const matchedTextColor = cssColorToHex(
        (!boolish(matchedAnnotation?.styleDirty) && (matchedAnnotation?.pdfjsSourceTextColor || box.dataset.sourceTextColor))
        || matchedAnnotation?.textColor
        || matchedAnnotation?.color
        || '#000000',
    );
    box.style.setProperty('--enpv-text-color', matchedTextColor);
    if (matchedAnnotation) applyAnnotationTypographyToBox(box, matchedAnnotation, scale);
    restoreSourceTypographyForBox(box, matchedAnnotation, scale);

    const tc = document.createElement('div');
    tc.className = 'enpv-text-content';
    tc.setAttribute('role', 'textbox');
    tc.setAttribute('aria-multiline', 'true');
    tc.contentEditable = 'false';
    tc.spellcheck = false;
    const richTextHtml = sanitizeRichTextHtmlForAnnotation(matchedAnnotation?.richTextHtml || '');
    if (renderRichTextRunsIntoElement(tc, matchedAnnotation?.richTextRuns, scale, matchedAnnotation?.text || '')) {
        // Structured runs already populated the element at this render scale.
    } else if (richTextHtml) {
        tc.innerHTML = richTextHtml;
        restoreAuthoredRichTextLineBreaks(tc, matchedAnnotation);
        rescaleRichTextInlineStylesForAnnotation(tc, matchedAnnotation, scale);
    } else {
        tc.textContent = normalizeAnnotationTextForDisplay(matchedAnnotation?.text || sourceInfo.visualText || sourceInfo.text || spanEl.textContent || sourceSpanOriginalText(spanEl) || '');
    }
    box.appendChild(tc);
    if (matchedAnnotation?.userForcedRichText === true || matchedAnnotation?.pdfjsEditorMode === 'rich') {
        box.dataset.userForcedRichText = '1';
        setBoxEditorMode(box, 'rich');
    } else {
        setBoxEditorMode(box, editorModeForBox(box));
    }
    addEditableBoxChrome(box);
    layer.appendChild(box);
    return box;
}

function syncSelectedBoxToPersistedAnnotations(options = {}) {
    const selectedBox = findSelectedBox()
        || document.querySelector('.enpv-annotation-box.is-editing')
        || document.querySelector('.enpv-annotation-box.is-selected');
    if (!selectedBox) return;
    syncAnnotationBoxToPersistedAnnotations(selectedBox, options);
}

function syncAnnotationBoxToPersistedAnnotations(box, options = {}) {
    if (!box) return;
    const existing = persistedAnnotationsById.get(String(box.dataset.annotationId || '')) || null;
    if (isUserCreatedTextBox(box, existing) && !userCreatedBoxHasText(box)) {
        if (options.preserveEmptyUserCreated === true) {
            return;
        }
        removeUserCreatedTextBox(box, { skipHistory: true });
        return;
    }
    const wasEditingPromotedFlow = box.classList.contains('is-editing')
        && box.classList.contains('is-promoted-source-block')
        && box.dataset.pendingEdit !== '1'
        && box.dataset.pendingResize !== '1'
        && box.dataset.styleDirty !== '1'
        && existing
        && isPromotedExtractionAnnotation(existing)
        && (() => {
            // Only treat this as a no-op edit if the text was not actually
            // changed. The promoted source block now keeps its verbatim
            // multi-line text in the in-place editor (no reflow), so compare
            // against the source/original text to detect a genuine edit.
            const currentText = textContentForBox(box);
            const sourceText = existing.text
                || existing.pdfjsSourceText
                || existing.originalText
                || baseTextForBox(box)
                || originalTextForBox(box)
                || '';
            return normalizeComparableText(currentText) === normalizeComparableText(sourceText);
        })();
    if (box.classList.contains('is-editing') && !options.preserveEditMode) {
        endEditMode(box);
    }
    // Escaping in-place edit on a promoted paragraph block without making any
    // real change must not overwrite the persisted multi-line block. The
    // block keeps its per-line source geometry, so committing an unchanged
    // edit would flatten the paragraph (dropping its source line boxes) and the
    // block would later be discarded as a redundant single-line overlay.
    // Leave the original block annotation untouched so it keeps paragraph-level
    // geometry through edit-mode entry/exit and undo.
    if (wasEditingPromotedFlow) {
        return;
    }
    const annotation = buildAnnotationFromBox(box, existing);
    if (annotation) {
        upsertPersistedAnnotation(annotation);
        box.classList.add('is-persisted-overlay');
        if (shouldMaskSourceForAnnotation(annotation)) {
            box.classList.remove('is-source-handle');
            attachSourceMaskForBox(box);
        } else {
            removeAnnBoxSourceMasks(box);
        }
        delete box.dataset.pendingEdit;
        delete box.dataset.pendingResize;
        // Normalize the visible committed paragraph to natural-width glyphs
        // and ordinary wrapping now that its text element can be measured.
        applyPromotedOverlayDisplayHorizontalFit(box);
        const refreshed = buildAnnotationFromBox(box, annotation);
        if (refreshed) upsertPersistedAnnotation(refreshed);
        // The live box already reflects both upserts above. Keep its page
        // layer on the same revision so the next passive scroll does not
        // discard and reconstruct the DOM that the user just edited.
        const liveLayer = box.closest('.enpv-annotation-box-layer');
        if (liveLayer) {
            liveLayer.dataset.annotationRevision = String(persistedAnnotationsRevision);
        }
    } else if (box.dataset.annotationId) {
        deletePersistedAnnotation(box.dataset.annotationId);
        box.classList.remove('is-persisted-overlay');
        // An autosave sweep (preserveEditMode) can hit an untouched source
        // handle that is still in edit mode. Stripping its source mask and
        // fidelity typography mid-edit leaves the editable text rendered with
        // default typography on top of the unmasked canvas glyphs, producing
        // a doubled "ghost" of the sentence. Keep the transient edit-mode
        // dressing; endEditMode performs this cleanup when editing finishes.
        if (!box.classList.contains('is-editing')) {
            removeAnnBoxSourceMasks(box);
            clearTransientSourceFidelity(box);
        }
    }
}

// A move is a pure translation: it must never re-typeset the paragraph. When
// the captured per-line scaffold can still describe the block, install it —
// the very markup the reload path (createPersistedOverlayBox) uses for moved
// promoted blocks — so the overlay keeps the PDF's own line breaks, leading
// indents, glyph advances and per-run typography instead of being re-wrapped
// (and letter-spacing-corrected) by the flowing paragraph editor.
function installMovedPromotedSourceLayout(box) {
    if (!promotedSourceBlockPrefersExactSourceEditLayout(box)) return false;
    const tc = selectedBoxTextElement(box);
    if (!tc) return false;
    const applied = boxHasCapturedSourceSpanScaffold(box)
        || applySourceFidelitySpanEditMarkup(box, { purpose: 'display', allowMultiline: true });
    if (!applied) return false;
    // A move started from the toolbar grip leaves the block in edit mode. Its
    // scaffold is the layout the overlay now paints, so exiting edit mode must
    // demote it to display markup rather than flatten away the paragraph gaps
    // and per-run typography the move just preserved.
    if (promotedSourceBlockEditKeepsExactLayout(box)) box.dataset.preserveExactSourceLayoutEdit = '1';
    setBoxEditorMode(box, 'rich');
    applyPromotedSourceBlockEditLayout(box, { suppressHangingIndent: true });
    return true;
}

// Glyph alignment compares live run rects against the captured coordinates in
// the page text layer, so it has to measure the block at its source position.
// Neutralize the drag translate for the measurement and restore it right after.
function alignMovedPromotedSourceLayout(box) {
    const tc = selectedBoxTextElement(box);
    if (!tc) return;
    const dragTransform = box.style.transform;
    if (dragTransform) box.style.transform = '';
    try {
        alignPromotedSourceEditGlyphsToCapturedRanges(box, tc);
    } finally {
        if (dragTransform) box.style.transform = dragTransform;
    }
}

function promoteSourceBoxToMovedOverlay(box) {
    if (!box || box.classList.contains('is-persisted-overlay')) return;
    const tc = selectedBoxTextElement(box);
    const existing = persistedAnnotationsById.get(String(box.dataset.annotationId || '')) || null;
    // Keep the exact captured layout when it still applies; only blocks the
    // scaffold can no longer describe (restyled, resized, already reflowed or
    // carrying authored rich markup) fall back to the flowing conversion that
    // double-click editing uses. Never rebuild captured source rows mid-drag.
    const keepsExactSourceLayout = installMovedPromotedSourceLayout(box);
    if (!keepsExactSourceLayout) convertPromotedParagraphForDirectManipulation(box, existing);
    if (tc && !String(tc.textContent || '').trim()) {
        tc.textContent = normalizeAnnotationTextForDisplay(baseTextForBox(box) || originalTextForBox(box) || '');
    }
    rememberSourceMaskRectForCurrentBox(box);
    box.dataset.movedTextOverlay = '1';
    if (shouldDropInheritedMovedSourceBackground(existing, box)) {
        box.dataset.backgroundColor = 'transparent';
        box.style.setProperty('--enpv-bg-color', 'transparent');
        box.classList.remove('has-custom-bg');
    }
    box.classList.remove('is-source-handle');
    box.classList.add('is-persisted-overlay');
    // Source-fidelity typography assumes a single short source run (white-space:
    // pre, fixed source-run width, horizontal scale). Applying it to a multi-line
    // rich promoted block overflows the box because the long wrapped lines no
    // longer wrap. Such blocks render as pre-wrap rich text both at creation and
    // after reload (createPersistedOverlayBox skips source-fidelity when
    // editorMode === 'rich'), so keep that rendering on live drag too.
    if (keepsExactSourceLayout) {
        // The scaffold only becomes measurable once the handle's hidden text
        // element is revealed by the persisted-overlay classes above.
        alignMovedPromotedSourceLayout(box);
    } else if (editorModeForBox(box) !== 'rich') {
        applySourceFidelityTypography(box);
        applySourceFidelitySpanEditMarkup(box, { purpose: 'display' });
        restoreSourceTypographyForBox(box, existing, Number.parseFloat(box.parentElement?.dataset?.scale || '') || Number.parseFloat(box.dataset.renderScale || '') || 1);
        refreshAttachedSourceFidelityTextFit(box);
    }
    attachSourceMaskForBox(box);
    applyMovedSourceVisibilityForBox(box);
}

function syncDirtyBoxesToPersistedAnnotations(options = {}) {
    document.querySelectorAll(
        '.enpv-annotation-box.is-editing, ' +
        '.enpv-annotation-box[data-pending-edit="1"], ' +
        '.enpv-annotation-box[data-pending-resize="1"]'
    ).forEach((box) => syncAnnotationBoxToPersistedAnnotations(box, options));
}

function syncRenderedPersistedOverlayBoxesToPersistedAnnotations() {
    document.querySelectorAll('.enpv-annotation-box.is-persisted-overlay').forEach((box) => {
        const existing = persistedAnnotationsById.get(String(box.dataset.annotationId || '')) || null;
        if (box.dataset.annotationType === 'shape'
            && existing
            && box.dataset.pendingEdit !== '1'
            && box.dataset.pendingResize !== '1'
            && !box.classList.contains('is-editing')) {
            return;
        }
        const annotation = buildAnnotationFromBox(box, existing);
        if (annotation) upsertPersistedAnnotation(annotation);
    });
    // This sweep serializes the already-rendered DOM; every mounted layer is
    // therefore current at the resulting revision and must not be rebuilt by
    // the next scroll frame.
    document.querySelectorAll('.enpv-annotation-box-layer').forEach((layer) => {
        layer.dataset.annotationRevision = String(persistedAnnotationsRevision);
    });
}

function buildBakedPdfUrl() {
    if (!BAKED_URL) return '';
    const url = new URL(BAKED_URL, window.location.origin);
    const sessionId = getSessionId();
    if (sessionId) url.searchParams.set('session_id', sessionId);
    url.searchParams.set('v', String(Date.now()));
    return url.toString();
}

function appendDocumentUnlockToken(url) {
    if (!documentPasswordProtected || !documentUnlockToken) return url;
    const parsed = new URL(url, window.location.origin);
    if (!['http:', 'https:'].includes(parsed.protocol)) return url;
    parsed.searchParams.set('pdf_unlock_token', documentUnlockToken);
    return parsed.toString();
}

async function loadInitialPdf() {
    const candidates = [];
    if (PDF_URL) candidates.push(PDF_URL);
    const bakedUrl = buildBakedPdfUrl();
    if (bakedUrl) candidates.push(bakedUrl);

    let lastError = null;
    for (const url of candidates) {
        try {
            await loadPdfFromUrl(url);
            return;
        } catch (err) {
            lastError = err;
            console.warn('Failed to load PDF candidate', url, err);
        }
    }

    if (lastError) throw lastError;
}

const eventBus = new EventBus();
const linkService = new PDFLinkService({ eventBus });
const findController = new PDFFindController({ eventBus, linkService });

const pdfViewer = new PDFViewer({
    container,
    eventBus,
    linkService,
    findController,
    maxCanvasPixels: PDFJS_MAX_CANVAS_PIXELS,
    annotationEditorMode: pdfjsLib.AnnotationEditorType?.NONE ?? 0,
    annotationMode: pdfjsLib.AnnotationMode?.ENABLE_FORMS ?? 2,
    textLayerMode: 2,
});
linkService.setViewer(pdfViewer);

// Per-page occurrence counters for identical text strings.
// Map<pageIndex, Map<text, count>>.
const pageOccurrenceCounts = new Map();
const MAX_SOURCE_SPAN_BOXES_PER_PAGE = 2500;
const sourceGroupsByPage = new Map();
const pdfjsTextLayerFontMetadataPromises = new WeakMap();
const suppressedStalePdfjsOverlayIds = new Set();

function medianNumber(values, fallback = 0) {
    const nums = values.filter((value) => Number.isFinite(value)).sort((a, b) => a - b);
    if (!nums.length) return fallback;
    const mid = Math.floor(nums.length / 2);
    return nums.length % 2 ? nums[mid] : ((nums[mid - 1] + nums[mid]) / 2);
}

function clampNumber(value, min, max) {
    return Math.max(min, Math.min(max, value));
}

function textLayerRelativeRect(el, layerRect) {
    if (!el || !layerRect) return null;
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return null;
    return {
        left: rect.left - layerRect.left,
        top: rect.top - layerRect.top,
        right: rect.right - layerRect.left,
        bottom: rect.bottom - layerRect.top,
        width: rect.width,
        height: rect.height,
        centerY: (rect.top - layerRect.top) + (rect.height / 2),
    };
}

function unionRects(rects) {
    const usable = rects.filter(Boolean);
    if (!usable.length) return null;
    const left = Math.min(...usable.map((rect) => rect.left));
    const top = Math.min(...usable.map((rect) => rect.top));
    const right = Math.max(...usable.map((rect) => rect.right ?? (rect.left + rect.width)));
    const bottom = Math.max(...usable.map((rect) => rect.bottom ?? (rect.top + rect.height)));
    return {
        left,
        top,
        right,
        bottom,
        width: right - left,
        height: bottom - top,
    };
}

function textLayerRectToPageRect(rect, layerEl, pageDiv) {
    if (!rect || !layerEl || !pageDiv) return null;
    const layerBounds = layerEl.getBoundingClientRect();
    const pageBounds = pageDiv.getBoundingClientRect();
    return {
        left: rect.left + (layerBounds.left - pageBounds.left),
        top: rect.top + (layerBounds.top - pageBounds.top),
        width: rect.width,
        height: rect.height,
    };
}

function detectVerticalCanvasRuleCuts(pageDiv, rect, options = {}) {
    if (!pageDiv || !rect || rect.width <= 0 || rect.height <= 0) return [];
    const minRectHeight = Number(options.minRectHeight ?? 8) || 8;
    if (rect.height < minRectHeight) return [];
    const minDarkRatio = Number(options.minDarkRatio ?? 0.62) || 0.62;
    const maxRuleWidth = Number(options.maxRuleWidth ?? 5) || 5;
    const canvas = pageDiv.querySelector(':scope canvas');
    if (!canvas) return [];
    let ctx = null;
    try {
        ctx = canvas.getContext('2d', { willReadFrequently: true });
    } catch (_) {
        return [];
    }
    if (!ctx) return [];
    const pageBounds = pageDiv.getBoundingClientRect();
    const canvasBounds = canvas.getBoundingClientRect();
    if (!canvasBounds.width || !canvasBounds.height || !canvas.width || !canvas.height) return [];

    const scaleX = canvas.width / canvasBounds.width;
    const scaleY = canvas.height / canvasBounds.height;
    const canvasLeft = rect.left - (canvasBounds.left - pageBounds.left);
    const canvasTop = rect.top - (canvasBounds.top - pageBounds.top);
    const sx = Math.max(0, Math.floor(canvasLeft * scaleX));
    const sy = Math.max(0, Math.floor(canvasTop * scaleY));
    const sw = Math.max(1, Math.min(canvas.width - sx, Math.ceil(rect.width * scaleX)));
    const sh = Math.max(1, Math.min(canvas.height - sy, Math.ceil(rect.height * scaleY)));
    if (sw <= 0 || sh <= 0) return [];

    let data;
    try {
        data = ctx.getImageData(sx, sy, sw, sh).data;
    } catch (_) {
        return [];
    }

    const darkColumns = [];
    for (let x = 0; x < sw; x += 1) {
        let dark = 0;
        for (let y = 0; y < sh; y += 1) {
            const offset = ((y * sw) + x) * 4;
            const r = data[offset];
            const g = data[offset + 1];
            const b = data[offset + 2];
            if (r < 150 && g < 150 && b < 150) dark += 1;
        }
        if (dark / sh >= minDarkRatio) darkColumns.push(x);
    }
    if (!darkColumns.length) return [];

    const groups = [];
    let start = darkColumns[0];
    let prev = darkColumns[0];
    for (const col of darkColumns.slice(1)) {
        if (col <= prev + 1) {
            prev = col;
            continue;
        }
        groups.push([start, prev]);
        start = col;
        prev = col;
    }
    groups.push([start, prev]);

    return groups
        .map(([a, b]) => ({
            x: rect.left + (((a + b + 1) / 2) / scaleX),
            width: Math.max(0.1, ((b - a + 1) / scaleX)),
        }))
        .filter((rule) => rule.width <= maxRuleWidth)
        .map((rule) => rule.x);
}

function detectTextLayerVerticalRuleCuts(pageDiv, layerEl, lineRect, medianHeight) {
    if (!pageDiv || !layerEl || !lineRect) return [];
    const padY = Math.max(3, medianHeight * 0.35);
    const pageRect = textLayerRectToPageRect({
        left: lineRect.left,
        top: Math.max(0, lineRect.top - padY),
        width: lineRect.width,
        height: lineRect.height + (padY * 2),
    }, layerEl, pageDiv);
    if (!pageRect) return [];
    const pageBounds = pageDiv.getBoundingClientRect();
    const layerBounds = layerEl.getBoundingClientRect();
    const layerOffsetX = layerBounds.left - pageBounds.left;
    return detectVerticalCanvasRuleCuts(pageDiv, pageRect, {
        minRectHeight: Math.max(8, medianHeight),
    }).map((x) => x - layerOffsetX);
}

function sourceGroupClientRect(group, layerEl) {
    if (!group?.rect || !layerEl) return null;
    const layerRect = layerEl.getBoundingClientRect();
    return {
        left: layerRect.left + group.rect.left,
        top: layerRect.top + group.rect.top,
        right: layerRect.left + group.rect.left + group.rect.width,
        bottom: layerRect.top + group.rect.top + group.rect.height,
        width: group.rect.width,
        height: group.rect.height,
        x: layerRect.left + group.rect.left,
        y: layerRect.top + group.rect.top,
    };
}

function sharedMarkedContentTextForSourceItems(items) {
    if (!Array.isArray(items) || !items.length) return '';
    const parent = items[0]?.span?.closest?.('.markedContent') || null;
    if (!parent) return '';
    if (!items.every((item) => item?.span?.closest?.('.markedContent') === parent)) return '';
    return String(parent.textContent || '');
}

function buildSourceGroupText(items) {
    const charWidth = medianNumber(
        items.map((item) => {
            const len = String(item.text || '').replace(/\s+/g, '').length;
            return len > 0 ? item.rect.width / len : NaN;
        }),
        6,
    );
    const spaceGapPx = Math.max(2, charWidth * 0.45);
    let text = '';
    let previous = null;
    for (const item of items) {
        let segment = String(item.text || '').replace(/\s+/g, ' ');
        if (!segment.trim()) continue;
        if (previous) {
            const gap = item.rect.left - previous.rect.right;
            const punctuationGap = sourceSegmentNeedsPunctuationSpace(previous.text, segment, gap, charWidth);
            if ((gap > spaceGapPx || punctuationGap) && text && !text.endsWith(' ') && !segment.startsWith(' ')) {
                text += ' ';
            }
        }
        if (!text) {
            segment = segment.trimStart();
        } else if (text.endsWith(' ')) {
            segment = segment.trimStart();
        }
        text += segment;
        previous = item;
    }
    return restoreExplicitSourceWhitespace(
        text.trim(),
        sharedMarkedContentTextForSourceItems(items),
    );
}

function sourceSegmentNeedsPunctuationSpace(previousText, nextText, gapPx, charWidth) {
    if (!(gapPx > Math.max(1, charWidth * 0.25))) return false;
    const previous = String(previousText || '').trimEnd();
    const next = String(nextText || '').trimStart();
    return /[:;,.!?)]$/.test(previous) && /^[A-Za-z0-9(]/.test(next);
}

function buildSourceGroupVisualText(items) {
    const charWidth = medianNumber(
        items.map((item) => {
            const len = String(item.text || '').replace(/\s+/g, '').length;
            return len > 0 ? item.rect.width / len : NaN;
        }),
        6,
    );
    const spaceWidth = Math.max(2, charWidth * 0.48);
    const visibleGapThreshold = Math.max(2, charWidth * 0.45);
    let text = '';
    let previous = null;
    for (const item of items) {
        let segment = String(item.text || '').replace(/\s+/g, ' ');
        if (!segment.trim()) continue;
        if (previous) {
            const gap = item.rect.left - previous.rect.right;
            if (gap > visibleGapThreshold && text && !segment.startsWith(' ')) {
                const spaceCount = Math.max(1, Math.round(gap / spaceWidth));
                text = text.replace(/ +$/g, '');
                text += ' '.repeat(spaceCount);
                segment = segment.trimStart();
            } else if (sourceSegmentNeedsPunctuationSpace(previous.text, segment, gap, charWidth) && text && !text.endsWith(' ') && !segment.startsWith(' ')) {
                text += ' ';
                segment = segment.trimStart();
            } else if ((/\s$/.test(String(previous.text || '')) || /^\s/.test(segment)) && text && !text.endsWith(' ') && !segment.startsWith(' ')) {
                text += ' ';
                segment = segment.trimStart();
            } else if (text.endsWith(' ')) {
                segment = segment.trimStart();
            }
        } else {
            segment = segment.trimStart();
        }
        text += segment;
        previous = item;
    }
    return restoreExplicitSourceWhitespace(
        text.trim(),
        sharedMarkedContentTextForSourceItems(items),
    );
}

function liveSourceGroupItems(group, layerEl) {
    if (!group || !layerEl) return [];
    const layerRect = layerEl.getBoundingClientRect?.();
    if (!layerRect) return [];
    return Array.from(group.spans || [])
        .map((span, order) => {
            const text = String(span?.textContent || '');
            const rect = span ? textLayerRelativeRect(span, layerRect) : null;
            if (!text.trim() || !rect) return null;
            return { span, text, rect, order };
        })
        .filter(Boolean)
        .sort((a, b) => a.rect.left - b.rect.left || a.order - b.order);
}

function refreshSourceGroupTextFromDom(group, layerEl) {
    if (group?.syntheticSourceText) return group;
    const items = liveSourceGroupItems(group, layerEl);
    if (!items.length) return group;
    const text = buildSourceGroupText(items);
    if (!text) return group;
    const visualText = buildSourceGroupVisualText(items) || text;
    const rect = unionRects(items.map((item) => item.rect));
    group.text = text;
    group.visualText = visualText;
    if (rect?.width > 0 && rect?.height > 0) group.rect = rect;
    group.spans = items.map((item) => item.span);
    group.anchor = group.anchor || group.spans[0];
    return group;
}

function rectOverlapRatioOfSmaller(left, right) {
    if (!left || !right) return 0;
    const leftRight = left.right ?? (left.left + left.width);
    const leftBottom = left.bottom ?? (left.top + left.height);
    const rightRight = right.right ?? (right.left + right.width);
    const rightBottom = right.bottom ?? (right.top + right.height);
    const overlapWidth = Math.max(0, Math.min(leftRight, rightRight) - Math.max(left.left, right.left));
    const overlapHeight = Math.max(0, Math.min(leftBottom, rightBottom) - Math.max(left.top, right.top));
    if (overlapWidth <= 0 || overlapHeight <= 0) return 0;
    const leftArea = Math.max(0.0001, left.width * left.height);
    const rightArea = Math.max(0.0001, right.width * right.height);
    return (overlapWidth * overlapHeight) / Math.min(leftArea, rightArea);
}

function chooseVisibleOverlappingLineItem(left, right) {
    const leftTop = Number(left?.rect?.top);
    const rightTop = Number(right?.rect?.top);
    if (Number.isFinite(leftTop) && Number.isFinite(rightTop)) {
        const topDelta = rightTop - leftTop;
        if (Math.abs(topDelta) > 0.2) return topDelta > 0 ? right : left;
    }
    const leftOrder = Number(left?.order) || 0;
    const rightOrder = Number(right?.order) || 0;
    return rightOrder >= leftOrder ? right : left;
}

function relatedSpansForSourceItem(item) {
    const spans = [];
    if (item?.span) spans.push(item.span);
    if (Array.isArray(item?.relatedSpans)) {
        item.relatedSpans.forEach((span) => {
            if (span && !spans.includes(span)) spans.push(span);
        });
    }
    return spans;
}

function shouldSuppressContainedSingleCharacterDuplicate(left, right) {
    const leftText = String(left?.text || '').trim();
    const rightText = String(right?.text || '').trim();
    if (!leftText || !rightText) return false;
    const leftSingle = leftText.length === 1;
    const rightSingle = rightText.length === 1;
    if (leftSingle === rightSingle) return false;
    const shortText = leftSingle ? leftText : rightText;
    const longText = leftSingle ? rightText : leftText;
    if (isStandaloneControlGlyphItem({ text: shortText })) return false;
    if (!longText.includes(shortText)) return false;
    const shortItem = leftSingle ? left : right;
    const longItem = leftSingle ? right : left;
    const shortHeight = Number(shortItem?.rect?.height) || 0;
    const longHeight = Number(longItem?.rect?.height) || 0;
    const minHeight = Math.max(0.0001, Math.min(shortHeight || longHeight || 0.0001, longHeight || shortHeight || 0.0001));
    const centerDelta = Math.abs((Number(shortItem?.rect?.centerY) || 0) - (Number(longItem?.rect?.centerY) || 0));
    if (centerDelta > minHeight * 0.2) return false;
    return rectOverlapRatioOfSmaller(shortItem?.rect, longItem?.rect) >= 0.86;
}

function suppressOverlappingSameLineItems(items) {
    const kept = [];
    for (const item of items) {
        const text = String(item.text || '').trim();
        let replaced = false;
        for (let i = 0; i < kept.length; i += 1) {
            const existing = kept[i];
            const existingText = String(existing.text || '').trim();
            const suppressContainedSingle = shouldSuppressContainedSingleCharacterDuplicate(existing, item);
            if ((text.length <= 1 || existingText.length <= 1) && !suppressContainedSingle) continue;
            if (rectOverlapRatioOfSmaller(item.rect, existing.rect) < 0.72) continue;
            const chosen = suppressContainedSingle
                ? (text.length === 1 ? existing : item)
                : chooseVisibleOverlappingLineItem(existing, item);
            const related = new Set([
                ...relatedSpansForSourceItem(existing),
                ...relatedSpansForSourceItem(item),
            ]);
            related.delete(chosen.span);
            kept[i] = {
                ...chosen,
                relatedSpans: Array.from(related),
            };
            replaced = true;
            break;
        }
        if (!replaced) kept.push(item);
    }
    return kept;
}

function isStandaloneControlGlyphItem(item) {
    const text = String(item?.text || '').trim();
    if (!text || text.length > 2) return false;
    return /^[\u2022\u25A0-\u25A3\u25AA-\u25AC\u25CF\u25E6\u2610-\u2612\u2713-\u2718\uF0A3\uF0B7\uF0FC\uF0FE]+$/.test(text);
}

function isSourceUnderlineRuleText(text) {
    const normalized = String(text || '').replace(/\s+/g, '');
    return normalized.length >= 1 && /^_+$/.test(normalized);
}

// Underscore runs that act as fill-in-the-blank leaders, as opposed to a lone
// underscore that is part of a word (`ap_bookmark.IFD`) and must stay in the
// span so the source box keeps covering its glyph.
function sourceUnderlineRuleRanges(raw) {
    const ranges = [];
    const pattern = /_+/g;
    let match = pattern.exec(raw);
    while (match) {
        const start = match.index;
        const end = start + match[0].length;
        const isWordInternal = match[0].length < 2
            && /\S/.test(raw[start - 1] || '')
            && /\S/.test(raw[end] || '');
        if (!isWordInternal) ranges.push([start, end]);
        match = pattern.exec(raw);
    }
    return ranges;
}

function sourceTextSegmentsWithoutUnderlineRules(text, rect) {
    const raw = String(text || '');
    if (!rect || raw.indexOf('_') < 0) return null;
    const ruleRanges = sourceUnderlineRuleRanges(raw);
    if (!ruleRanges.length) return null;
    const ranges = [];
    const pushRange = (start, end) => {
        let trimStart = start;
        let trimEnd = end;
        while (trimStart < trimEnd && /\s/.test(raw[trimStart])) trimStart += 1;
        while (trimEnd > trimStart && /\s/.test(raw[trimEnd - 1])) trimEnd -= 1;
        if (trimEnd > trimStart) ranges.push([trimStart, trimEnd]);
    };
    let cursor = 0;
    for (const [ruleStart, ruleEnd] of ruleRanges) {
        pushRange(cursor, ruleStart);
        cursor = ruleEnd;
    }
    pushRange(cursor, raw.length);
    if (!ranges.length) return [];
    if (ranges.length === 1 && ranges[0][0] === 0 && ranges[0][1] === raw.length) return null;
    const total = Math.max(1, raw.length);
    return ranges.map(([rangeStart, rangeEnd]) => {
        const left = rect.left + (rect.width * (rangeStart / total));
        const right = rect.left + (rect.width * (rangeEnd / total));
        return {
            text: raw.slice(rangeStart, rangeEnd),
            rect: {
                ...rect,
                left,
                right,
                width: Math.max(1, right - left),
            },
        };
    });
}

function isStandaloneLowercaseLineLabelItem(item) {
    return /^[a-z]$/.test(String(item?.text || '').trim());
}

function isStandaloneNumberedLineLabelItem(item) {
    return /^\d{1,3}[.)]$/.test(String(item?.text || '').trim());
}

function isNumericColumnValueItem(item) {
    const text = String(item?.text || '').trim();
    if (!text || text.length > 24) return false;
    return /^\(?[-+$]?\d[\d,\s]*(?:\.\d+)?%?\)?$/.test(text);
}

function isTextColumnLabelItem(item) {
    const text = String(item?.text || '').trim();
    return /[A-Za-z]/.test(text);
}

function shouldSplitLabelValueColumnGap(previous, item, gapPx, line, charWidth) {
    if (!previous || !item || !(gapPx > 0)) return false;
    const labelThenValue = isTextColumnLabelItem(previous) && isNumericColumnValueItem(item);
    const valueThenLabel = isNumericColumnValueItem(previous) && isTextColumnLabelItem(item);
    if (!labelThenValue && !valueThenLabel) return false;
    const splitThreshold = Math.max(18, line.medianHeight * 1.05, charWidth * 4.25);
    return gapPx > splitThreshold;
}

function shouldSplitSameLineProseColumnGap(currentItems, previous, item, gapPx, line, charWidth) {
    if (!previous || !item || !(gapPx > 0)) return false;
    const previousText = String(previous.text || '').trim();
    const itemText = String(item.text || '').trim();
    if (!/[A-Za-z]{2,}/.test(previousText) || !/[A-Za-z]{2,}/.test(itemText)) return false;
    const previousHeight = Number(previous.rect?.height) || Number(line?.medianHeight) || 0;
    const itemHeight = Number(item.rect?.height) || Number(line?.medianHeight) || 0;
    const minHeight = Math.max(0.0001, Math.min(previousHeight || itemHeight || 0.0001, itemHeight || previousHeight || 0.0001));
    const centerDelta = Math.abs((Number(previous.rect?.centerY) || 0) - (Number(item.rect?.centerY) || 0));
    if (centerDelta > minHeight * 0.35) return false;
    const currentText = buildSourceGroupText(currentItems || []);
    const currentLetters = currentText.replace(/[^A-Za-z]/g, '').length;
    const previousLetters = previousText.replace(/[^A-Za-z]/g, '').length;
    const itemLetters = itemText.replace(/[^A-Za-z]/g, '').length;
    if (currentLetters < 8 && previousLetters < 4) return false;
    const longProseRuns = currentLetters >= 18 && itemLetters >= 6;
    const heightMultiplier = longProseRuns ? 0.55 : 0.65;
    const charMultiplier = longProseRuns ? 1.8 : 2.2;
    const splitThreshold = Math.max(14, (Number(line?.medianHeight) || minHeight) * heightMultiplier, charWidth * charMultiplier);
    return gapPx >= splitThreshold;
}

function shouldSplitShortLeadingColumnGap(currentItems, previous, item, gapPx, line) {
    if (!previous || !item || currentItems?.length !== 1 || !(gapPx > 0)) return false;
    const previousText = String(previous.text || '').replace(/\s+/g, ' ').trim();
    const itemText = String(item.text || '').replace(/\s+/g, ' ').trim();
    if (!previousText || !itemText) return false;
    const previousLetters = previousText.replace(/[^A-Za-z0-9]/g, '').length;
    const itemLetters = itemText.replace(/[^A-Za-z0-9]/g, '').length;
    if (previousText.length > 18 || previousLetters > 10 || itemLetters < 8) return false;
    if (!/[A-Za-z]/.test(previousText) || !/[A-Za-z]/.test(itemText)) return false;

    const previousHeight = Number(previous.rect?.height) || Number(line?.medianHeight) || 0;
    const itemHeight = Number(item.rect?.height) || Number(line?.medianHeight) || 0;
    const minHeight = Math.max(0.0001, Math.min(previousHeight || itemHeight || 0.0001, itemHeight || previousHeight || 0.0001));
    const centerDelta = Math.abs((Number(previous.rect?.centerY) || 0) - (Number(item.rect?.centerY) || 0));
    const previousFont = Number(previous.fontSizePx) || previousHeight;
    const itemFont = Number(item.fontSizePx) || itemHeight;
    const fontRatio = Math.max(previousFont, itemFont) / Math.max(0.0001, Math.min(previousFont, itemFont));
    const strongVisualSeparation = centerDelta > minHeight * 0.18 || fontRatio >= 1.10;
    const splitThreshold = Math.max(14, minHeight * (strongVisualSeparation ? 0.75 : 1.25));
    return gapPx >= splitThreshold;
}

function shouldSplitOffsetBaselineColumnGap(previous, item, gapPx, line, charWidth) {
    // Line buckets group spans by vertical center, so in a multi-column layout
    // the first line of a neighbouring column can land in the same bucket as
    // the tail of this column's line (doc 5201 page 2: "We've extended our" +
    // "the business landscape. The most exciting"). Text that truly flows
    // inline shares a baseline, so a visible baseline offset combined with a
    // gap wider than a word space means the bucket bridged a column gutter and
    // the two runs must stay in separate source groups.
    if (!previous || !item || !(gapPx > 0)) return false;
    const previousHeight = Number(previous.rect?.height) || Number(line?.medianHeight) || 0;
    const itemHeight = Number(item.rect?.height) || Number(line?.medianHeight) || 0;
    const minHeight = Math.min(previousHeight || itemHeight, itemHeight || previousHeight);
    if (!(minHeight > 0)) return false;
    const centerDelta = Math.abs((Number(previous.rect?.centerY) || 0) - (Number(item.rect?.centerY) || 0));
    if (centerDelta < Math.max(2, minHeight * 0.18)) return false;
    const gutterThreshold = Math.max(12, minHeight * 0.55, (Number(charWidth) || 0) * 1.5);
    return gapPx >= gutterThreshold;
}

function sourceItemTransformIsVertical(transform) {
    if (!transform || transform === 'none') return false;
    try {
        const matrix = new DOMMatrixReadOnly(transform);
        return Math.abs(matrix.b) > 0.35 || Math.abs(matrix.c) > 0.35;
    } catch (_) {
        return /matrix\(\s*0\s*,\s*[-\d.]+\s*,\s*[-\d.]+/i.test(String(transform));
    }
}

function normalizedSourceFontFamily(value) {
    return String(value || '')
        .split(',')[0]
        .replace(/^["']|["']$/g, '')
        .trim()
        .toLowerCase();
}

function normalizedSourceFontStyle(value) {
    return String(value || 'normal').trim().toLowerCase() || 'normal';
}

function normalizedSourceFontWeight(value) {
    const raw = String(value || '400').trim().toLowerCase();
    if (raw === 'normal') return 400;
    if (raw === 'bold') return 700;
    const parsed = Number.parseInt(raw, 10);
    return Number.isFinite(parsed) ? parsed : 400;
}

function sourceItemsAreInlineTextFlow(previous, item, gapPx, minHeight, centerDelta) {
    const previousText = String(previous?.text || '').trim();
    const itemText = String(item?.text || '').trim();
    if (!/[A-Za-z0-9)]$/.test(previousText) || !/^[A-Za-z0-9([]/.test(itemText)) return false;
    const lowerGapLimit = -Math.max(3, minHeight * 0.35);
    const upperGapLimit = Math.max(4, minHeight * 0.6);
    return gapPx >= lowerGapLimit && gapPx <= upperGapLimit && centerDelta <= minHeight * 0.25;
}

function shouldSplitMixedTypography(previous, item, gapPx) {
    if (!previous || !item) return false;
    if (previous.isVertical !== item.isVertical) return true;
    const previousHeight = Number(previous.rect?.height) || 0;
    const itemHeight = Number(item.rect?.height) || 0;
    const minHeight = Math.max(0.0001, Math.min(previousHeight, itemHeight));
    const centerDelta = Math.abs((Number(previous.rect?.centerY) || 0) - (Number(item.rect?.centerY) || 0));
    const isInlineTextFlow = sourceItemsAreInlineTextFlow(previous, item, gapPx, minHeight, centerDelta);
    if (!isInlineTextFlow) {
        if (previous.fontStyle !== item.fontStyle) return true;
        if (Math.abs(previous.fontWeight - item.fontWeight) >= 200) return true;
        if (previous.fontFamily && item.fontFamily && previous.fontFamily !== item.fontFamily) return true;
    }
    const previousScaleX = Number(previous.transformScaleX) || 1;
    const itemScaleX = Number(item.transformScaleX) || 1;
    const transformRatio = Math.max(previousScaleX, itemScaleX) / Math.max(0.0001, Math.min(previousScaleX, itemScaleX));
    if (transformRatio >= 1.18 && !isInlineTextFlow) return true;
    const maxHeight = Math.max(previousHeight, itemHeight);
    const heightRatio = maxHeight / minHeight;
    const previousFont = Number(previous.fontSizePx) || previousHeight;
    const itemFont = Number(item.fontSizePx) || itemHeight;
    const fontRatio = Math.max(previousFont, itemFont) / Math.max(0.0001, Math.min(previousFont, itemFont));
    if (heightRatio >= 1.45 || fontRatio >= 1.45) return true;
    return gapPx > 2 && centerDelta > minHeight * 0.38;
}

function collectSourceTextGroups(layerEl, pageIndex, pageDiv = null) {
    if (!layerEl) return [];
    const layerRect = layerEl.getBoundingClientRect();
    const rawItems = Array.from(layerEl.querySelectorAll('span'))
        .filter((span) => !span.classList.contains('markedContent'))
        .flatMap((span, order) => {
            const text = String(span.textContent || '');
            if (isSourceUnderlineRuleText(text)) return null;
            const rect = textLayerRelativeRect(span, layerRect);
            if (!text || !rect) return null;
            const hasText = text.trim() !== '';
            const visibleInk = hasText && spanHasVisibleCanvasInk(span, pageDiv);
            if (!visibleInk) return null;
            const cs = window.getComputedStyle(span);
            const transform = cs.transform && cs.transform !== 'none' ? cs.transform : '';
            const baseItem = {
                span,
                text,
                rect,
                order,
                fontSizePx: Number.parseFloat(cs.fontSize || '') || rect.height,
                fontFamily: normalizedSourceFontFamily(cs.fontFamily),
                fontStyle: normalizedSourceFontStyle(cs.fontStyle),
                fontWeight: normalizedSourceFontWeight(cs.fontWeight),
                transform,
                transformScaleX: sourceTransformScaleX(transform),
                isVertical: sourceItemTransformIsVertical(transform),
            };
            const segments = sourceTextSegmentsWithoutUnderlineRules(text, rect);
            if (!segments) return [baseItem];
            return segments.map((segment, segmentIndex) => ({
                ...baseItem,
                text: segment.text,
                rect: segment.rect,
                order: order + (segmentIndex / 100),
                syntheticSourceText: true,
            }));
        })
        .filter(Boolean);

    if (!rawItems.length) return [];

    const medianHeight = medianNumber(rawItems.map((item) => item.rect.height), 12);
    const lineTolerance = clampNumber(medianHeight * 0.45, 2.5, 8);
    const lineBuckets = [];
    const sortedByY = [...rawItems].sort((a, b) => {
        const dy = a.rect.centerY - b.rect.centerY;
        return Math.abs(dy) > lineTolerance ? dy : (a.rect.left - b.rect.left);
    });

    for (const item of sortedByY) {
        let bucket = null;
        for (const candidate of lineBuckets) {
            const tolerance = Math.max(lineTolerance, Math.min(candidate.medianHeight, item.rect.height) * 0.55);
            if (Math.abs(item.rect.centerY - candidate.centerY) <= tolerance) {
                bucket = candidate;
                break;
            }
        }
        if (!bucket) {
            lineBuckets.push({
                centerY: item.rect.centerY,
                medianHeight: item.rect.height,
                items: [item],
            });
            continue;
        }
        bucket.items.push(item);
        bucket.centerY = medianNumber(bucket.items.map((entry) => entry.rect.centerY), bucket.centerY);
        bucket.medianHeight = medianNumber(bucket.items.map((entry) => entry.rect.height), bucket.medianHeight);
    }

    const groups = [];
    for (const line of lineBuckets.sort((a, b) => a.centerY - b.centerY)) {
        const lineItems = suppressOverlappingSameLineItems(line.items)
            .sort((a, b) => a.rect.left - b.rect.left || a.order - b.order);
        const lineRect = unionRects(lineItems.map((item) => item.rect));
        const verticalRuleCuts = detectTextLayerVerticalRuleCuts(pageDiv, layerEl, lineRect, line.medianHeight);
        const charWidth = medianNumber(
            lineItems.map((item) => {
                const len = String(item.text || '').replace(/\s+/g, '').length;
                return len > 0 ? item.rect.width / len : NaN;
            }),
            6,
        );
        const splitGapPx = Math.max(24, line.medianHeight * 1.7, charWidth * 7);
        let current = [];
        let previous = null;
        const flush = () => {
            if (!current.length) return;
            const text = buildSourceGroupText(current);
            const visualText = buildSourceGroupVisualText(current);
            const rect = unionRects(current.map((item) => item.rect));
            if (text && rect?.width > 0 && rect?.height > 0) {
                const relatedSpans = Array.from(new Set(current.flatMap((item) => item.relatedSpans || [])))
                    .filter((span) => span && !current.some((item) => item.span === span));
                groups.push({
                    pageIndex,
                    text,
                    visualText,
                    rect,
                    spans: current.map((item) => item.span),
                    relatedSpans,
                    anchor: current[0].span,
                    syntheticSourceText: current.some((item) => item.syntheticSourceText),
                });
            }
            current = [];
        };

        for (const item of lineItems) {
            const gapFromPrevious = previous ? item.rect.left - previous.rect.right : 0;
            const isSeparatedByGap = previous && gapFromPrevious > splitGapPx;
            const isSeparatedByVerticalRule = previous && verticalRuleCuts.some((cutX) => (
                cutX >= Math.min(previous.rect.right, item.rect.left) - 2
                && cutX <= Math.max(previous.rect.right, item.rect.left) + 2
            ));
            const splitAroundControlGlyph = (
                (current.length > 0 && isStandaloneControlGlyphItem(item))
                || (current.length === 1 && isStandaloneControlGlyphItem(current[0]))
            );
            const splitAfterLowercaseLineLabel = (
                current.length === 1
                && isStandaloneLowercaseLineLabelItem(current[0])
                && gapFromPrevious > Math.max(6, line.medianHeight * 0.55)
            );
            const splitAfterNumberedLineLabel = (
                current.length === 1
                && isStandaloneNumberedLineLabelItem(current[0])
                && isTextColumnLabelItem(item)
                && gapFromPrevious > Math.max(6, line.medianHeight * 0.45)
            );
            const splitBetweenLabelAndNumericColumn = shouldSplitLabelValueColumnGap(
                previous,
                item,
                gapFromPrevious,
                line,
                charWidth,
            );
            const splitBetweenProseColumns = shouldSplitSameLineProseColumnGap(
                current,
                previous,
                item,
                gapFromPrevious,
                line,
                charWidth,
            );
            const splitShortLeadingColumn = shouldSplitShortLeadingColumnGap(
                current,
                previous,
                item,
                gapFromPrevious,
                line,
            );
            const splitMixedTypography = shouldSplitMixedTypography(previous, item, gapFromPrevious);
            const splitOffsetBaselineColumn = shouldSplitOffsetBaselineColumnGap(
                previous,
                item,
                gapFromPrevious,
                line,
                charWidth,
            );
            const splitAfterSyntheticUnderline = Boolean(previous?.syntheticSourceText);
            if (isSeparatedByGap || isSeparatedByVerticalRule || splitAroundControlGlyph || splitAfterLowercaseLineLabel || splitAfterNumberedLineLabel || splitBetweenLabelAndNumericColumn || splitBetweenProseColumns || splitShortLeadingColumn || splitMixedTypography || splitOffsetBaselineColumn || splitAfterSyntheticUnderline) {
                flush();
            }
            current.push(item);
            previous = item;
        }
        flush();
    }

    return groups.map((group, index) => ({ ...group, index }));
}

function getSourceGroupsForPage(pageIndex, layerEl, pageDiv = null) {
    const cached = sourceGroupsByPage.get(pageIndex);
    if (cached?.layerEl === layerEl) return cached.groups || [];
    const groups = collectSourceTextGroups(layerEl, pageIndex, pageDiv);
    sourceGroupsByPage.set(pageIndex, { layerEl, groups });
    return groups;
}

function sourceGroupForSpan(spanEl) {
    if (!spanEl) return null;
    const pageIndex = Number.parseInt(spanEl.dataset.enpvPage || '-1', 10);
    const groupIndex = Number.parseInt(spanEl.dataset.enpvGroupIndex || spanEl.dataset.enpvIndex || '-1', 10);
    if (!Number.isFinite(pageIndex) || pageIndex < 0 || !Number.isFinite(groupIndex) || groupIndex < 0) return null;
    const cached = sourceGroupsByPage.get(pageIndex);
    return cached?.groups?.find((group) => group.index === groupIndex) || null;
}

function clearMovedSourceVisibilityMarks(layerEl) {
    if (!layerEl) return;
    layerEl.querySelectorAll('[data-enpv-moved-source-hidden="1"]').forEach((el) => {
        delete el.dataset.enpvMovedSourceHidden;
    });
}

function sourceGroupForAnnotation(annotation, pageIndex, layerEl = null) {
    if (!annotation || !Number.isFinite(pageIndex) || pageIndex < 0) return null;
    const pageView = pdfViewer.getPageView(pageIndex);
    const sourceLayer = layerEl || pageView?.textLayer?.div || pageView?.textLayer?.textLayerDiv;
    if (!sourceLayer) return null;
    const groups = getSourceGroupsForPage(pageIndex, sourceLayer, pageView?.div || null);
    const targetText = normalizeComparableText(annotation.pdfjsSourceText || annotation.originalText || annotation.text || '');
    const targetOccurrence = String(annotation.pdfjsSourceOccurrence ?? annotation.occurrence ?? '').trim();
    const targetRect = annotationBaselinePdfBox(annotation) || annotationCurrentPdfBox(annotation);
    const anchorUid = String(annotation.pdfjsAnchorUid || '').trim();
    const anchorMatch = anchorUid.match(/^(\d+):(\d+)$/);
    if (anchorMatch && Number.parseInt(anchorMatch[1], 10) === pageIndex) {
        const groupIndex = Number.parseInt(anchorMatch[2], 10);
        const direct = groups.find((group) => Number(group.index) === groupIndex);
        if (direct) {
            const directText = normalizeComparableText(direct.text || direct.visualText || '');
            const directOccurrence = String(direct.occurrence ?? direct.anchor?.dataset?.enpvOccurrence ?? '').trim();
            const textMatches = !targetText || !directText || targetText === directText;
            const occurrenceMatches = !targetOccurrence || !directOccurrence || targetOccurrence === directOccurrence;
            let geometryMatches = true;
            if (targetRect && direct.rect) {
                const scale = Number(pageView?.viewport?.scale) || Number(pdfViewer.currentScale) || 1;
                const directRect = {
                    x: direct.rect.left / scale,
                    y: (Number(pageView?.viewport?.height) - (direct.rect.top + direct.rect.height)) / scale,
                    w: direct.rect.width / scale,
                    h: direct.rect.height / scale,
                };
                geometryMatches = scorePdfRectDistance(targetRect, directRect) <= 24;
            }
            if (textMatches && occurrenceMatches && geometryMatches) return direct;
        }
    }
    let best = null;
    let bestScore = Number.POSITIVE_INFINITY;
    for (const group of groups) {
        const groupText = normalizeComparableText(group.text || group.visualText || '');
        if (targetText && groupText && targetText !== groupText) continue;
        const occurrence = String(group.occurrence ?? group.anchor?.dataset?.enpvOccurrence ?? '').trim();
        if (targetOccurrence && occurrence && targetOccurrence !== occurrence) continue;
        let score = 0;
        if (targetRect && group.rect) {
            const scale = Number(pageView?.viewport?.scale) || Number(pdfViewer.currentScale) || 1;
            const groupRect = {
                x: group.rect.left / scale,
                y: (Number(pageView?.viewport?.height) - (group.rect.top + group.rect.height)) / scale,
                w: group.rect.width / scale,
                h: group.rect.height / scale,
            };
            score = scorePdfRectDistance(targetRect, groupRect);
        }
        if (score < bestScore) {
            best = group;
            bestScore = score;
        }
    }
    return best;
}

function clampSourceMaskCanvasRectToSourceCell(rect, options = {}) {
    if (!rect) return rect;
    const box = options.box || null;
    const annotation = options.annotation || null;
    const parsedPageIndex = Number.parseInt(
        options.pageIndex ?? box?.dataset?.pageIndex ?? annotation?.pageIndex ?? '-1',
        10,
    );
    if (!Number.isFinite(parsedPageIndex) || parsedPageIndex < 0) return rect;
    const pageView = pdfViewer.getPageView(parsedPageIndex);
    const pageDiv = pageView?.div || null;
    const layerEl = pageView?.textLayer?.div || pageView?.textLayer?.textLayerDiv || null;
    if (!pageDiv || !layerEl) return rect;
    const groups = getSourceGroupsForPage(parsedPageIndex, layerEl, pageDiv);
    if (!groups.length) return rect;

    const targetGroup = box
        ? sourceGroupForBox(box)?.group
        : sourceGroupForAnnotation(annotation, parsedPageIndex, layerEl);
    if (!targetGroup?.rect) return rect;
    const targetRect = textLayerRectToPageRect(targetGroup.rect, layerEl, pageDiv);
    if (!targetRect) return rect;
    const targetIndex = String(targetGroup.index ?? '');
    const neighbourRects = groups
        .filter((group) => (
            group?.rect
            && group !== targetGroup
            && (!targetIndex || String(group.index ?? '') !== targetIndex)
        ))
        .map((group) => textLayerRectToPageRect(group.rect, layerEl, pageDiv))
        .filter(Boolean);
    return clampSourceMaskRectToCell(rect, targetRect, neighbourRects);
}

function movedSourceSiblingBelongsToAnotherGroup(span, groupIndex) {
    const siblingGroupIndex = String(span?.dataset?.enpvGroupIndex || span?.dataset?.enpvIndex || '').trim();
    return siblingGroupIndex && String(groupIndex ?? '').trim() && siblingGroupIndex !== String(groupIndex).trim();
}

function movedSourceSiblingIsSafeToHide(span, groupSet, groupIndex) {
    if (!span || span.tagName !== 'SPAN') return false;
    if (groupSet?.has(span)) return true;
    if (movedSourceSiblingBelongsToAnotherGroup(span, groupIndex)) return false;
    const siblingGroupIndex = String(span.dataset.enpvGroupIndex || span.dataset.enpvIndex || '').trim();
    if (siblingGroupIndex && siblingGroupIndex === String(groupIndex ?? '').trim()) return true;
    return !normalizeComparableText(span.textContent || '');
}

function markSourceGroupHiddenForMovedOverlay(group, annotationId = '') {
    if (!group?.spans?.length) return;
    const hiddenSpans = new Set([
        ...(group.spans || []),
        ...(group.relatedSpans || []),
    ]);
    const first = group.spans[0];
    const parent = first?.parentElement;
    const groupText = normalizeComparableText(group.text || group.visualText || '');
    if (parent?.classList?.contains('markedContent')) {
        const parentText = normalizeComparableText(parent.textContent || '');
        if (parentText && groupText && parentText === groupText) {
            parent.dataset.enpvMovedSourceHidden = '1';
            parent.querySelectorAll('span').forEach((span) => hiddenSpans.add(span));
        }
    }
    const groupSet = new Set(group.spans);
    const groupIndex = String(group.index ?? '');
    const siblings = Array.from(parent?.children || []);
    if (siblings.length && group.spans.every((span) => span.parentElement === parent)) {
        const indexes = group.spans.map((span) => siblings.indexOf(span)).filter((index) => index >= 0);
        if (indexes.length) {
            const minIndex = Math.min(...indexes);
            const maxIndex = Math.max(...indexes);
            siblings.slice(minIndex, maxIndex + 1).forEach((el) => {
                if (movedSourceSiblingIsSafeToHide(el, groupSet, groupIndex)) hiddenSpans.add(el);
            });
        }
    }
    hiddenSpans.forEach((span) => {
        span.dataset.enpvMovedSourceHidden = '1';
        if (annotationId && groupSet.has(span)) span.dataset.enpvPersistentId = annotationId;
    });
}

function markPersistentSourceSpansHiddenForMovedOverlay(annotationId, pageIndex) {
    const id = String(annotationId || '').trim();
    if (!id || !Number.isFinite(pageIndex) || pageIndex < 0) return false;
    const pageView = pdfViewer.getPageView(pageIndex);
    const layerEl = pageView?.textLayer?.div || pageView?.textLayer?.textLayerDiv;
    if (!layerEl) return false;
    const spans = Array.from(layerEl.querySelectorAll('span[data-enpv-persistent-id]'))
        .filter((span) => String(span.dataset.enpvPersistentId || '') === id);
    if (!spans.length) return false;
    const hidden = new Set(spans);
    const parent = spans[0].parentElement;
    const siblings = Array.from(parent?.children || []);
    const groupIndexes = new Set(spans.map((span) => String(span.dataset.enpvGroupIndex || span.dataset.enpvIndex || '').trim()).filter(Boolean));
    if (siblings.length && spans.every((span) => span.parentElement === parent)) {
        const indexes = spans.map((span) => siblings.indexOf(span)).filter((index) => index >= 0);
        if (indexes.length) {
            const minIndex = Math.min(...indexes);
            const maxIndex = Math.max(...indexes);
            siblings.slice(minIndex, maxIndex + 1).forEach((el) => {
                if (el.tagName !== 'SPAN') return;
                const siblingGroupIndex = String(el.dataset.enpvGroupIndex || el.dataset.enpvIndex || '').trim();
                const siblingId = String(el.dataset.enpvPersistentId || '').trim();
                const sameGroup = siblingGroupIndex && groupIndexes.has(siblingGroupIndex);
                const unassignedBlank = !siblingGroupIndex && !normalizeComparableText(el.textContent || '');
                if (siblingId === id || sameGroup || unassignedBlank) hidden.add(el);
            });
        }
    }
    hidden.forEach((span) => {
        span.dataset.enpvMovedSourceHidden = '1';
        if (spans.includes(span)) span.dataset.enpvPersistentId = id;
    });
    return true;
}

function applyMovedSourceVisibilityForPage(pageIndex, layerEl = null) {
    const pageView = pdfViewer.getPageView(pageIndex);
    const sourceLayer = layerEl || pageView?.textLayer?.div || pageView?.textLayer?.textLayerDiv;
    if (!sourceLayer) return;
    clearMovedSourceVisibilityMarks(sourceLayer);
    const annotations = annotationBoxesByPage.get(pageIndex) || [];
    for (const annotation of annotations) {
        if (!annotation || String(annotation.type || '').toLowerCase() !== 'text') continue;
        if (!boolish(annotation.savedTextOverlay) || !boolish(annotation.movedTextOverlay) || boolish(annotation.pdfjsDeleted)) continue;
        const group = sourceGroupForAnnotation(annotation, pageIndex, sourceLayer);
        if (group) markSourceGroupHiddenForMovedOverlay(group, String(annotation.id || ''));
        markPersistentSourceSpansHiddenForMovedOverlay(annotation.id || '', pageIndex);
    }
}

function applyMovedSourceVisibilityForBox(box) {
    if (!box || box.dataset.movedTextOverlay !== '1') return;
    const pageIndex = Number.parseInt(box.dataset.pageIndex || '-1', 10);
    if (!Number.isFinite(pageIndex) || pageIndex < 0) return;
    const lookup = sourceGroupForBox(box);
    const group = lookup?.group
        || sourceGroupForAnnotation(persistedAnnotationsById.get(String(box.dataset.annotationId || '')) || {
            id: box.dataset.annotationId,
            pdfjsAnchorUid: box.dataset.uid,
            pdfjsSourceText: baseTextForBox(box) || originalTextForBox(box) || '',
            pdfjsSourceOccurrence: box.dataset.occurrence || '',
            pdfjsSourceX: Number.parseFloat(box.dataset.sourceBboxX || box.dataset.baseBboxX || ''),
            pdfjsSourceY: Number.parseFloat(box.dataset.sourceBboxY || box.dataset.baseBboxY || ''),
            pdfjsSourceW: Number.parseFloat(box.dataset.sourceBboxW || box.dataset.baseBboxW || ''),
            pdfjsSourceH: Number.parseFloat(box.dataset.sourceBboxH || box.dataset.baseBboxH || ''),
        }, pageIndex);
    if (group) markSourceGroupHiddenForMovedOverlay(group, String(box.dataset.annotationId || ''));
    markPersistentSourceSpansHiddenForMovedOverlay(box.dataset.annotationId || '', pageIndex);
}

function sourceInfoForSpan(spanEl) {
    if (!spanEl) return null;
    const pageIndex = Number.parseInt(spanEl.dataset.enpvPage || '-1', 10);
    if (!Number.isFinite(pageIndex) || pageIndex < 0) return null;
    const pageView = pdfViewer.getPageView(pageIndex);
    const layerEl = pageView?.textLayer?.div || pageView?.textLayer?.textLayerDiv;
    const layerRect = layerEl?.getBoundingClientRect?.();
    if (!layerEl || !layerRect) return null;
    const group = sourceGroupForSpan(spanEl);
    if (group) {
        refreshSourceGroupTextFromDom(group, layerEl);
        return {
            pageIndex,
            anchor: group.anchor || spanEl,
            text: group.text,
            visualText: group.visualText || group.text,
            rect: group.rect,
            clientRect: sourceGroupClientRect(group, layerEl),
            index: group.index,
            occurrence: Number.parseInt(group.anchor?.dataset?.enpvOccurrence || spanEl.dataset.enpvOccurrence || '0', 10) || 0,
            uid: `${pageIndex}:${group.index}`,
        };
    }
    const rect = textLayerRelativeRect(spanEl, layerRect);
    if (!rect) return null;
    const index = Number.parseInt(spanEl.dataset.enpvIndex || spanEl.dataset.enpvOccurrence || '0', 10) || 0;
    return {
        pageIndex,
        anchor: spanEl,
        text: String(sourceSpanOriginalText(spanEl) || spanEl.textContent || ''),
        visualText: String(sourceSpanOriginalText(spanEl) || spanEl.textContent || ''),
        rect,
        clientRect: spanEl.getBoundingClientRect(),
        index,
        occurrence: Number.parseInt(spanEl.dataset.enpvOccurrence || '0', 10) || 0,
        uid: `${pageIndex}:${index}`,
    };
}

function pdfjsFontStyleFromFaceName(faceName, fontObject = null) {
    if (fontObject?.italic) return 'italic';
    return /italic|oblique/.test(String(faceName || '').toLowerCase()) ? 'italic' : 'normal';
}

function resolvePdfjsCommonObject(commonObjects, objectId, timeoutMs = 500) {
    if (!commonObjects?.get || !objectId) return Promise.resolve(null);
    try {
        return Promise.resolve(commonObjects.get(objectId));
    } catch (_) {
        // PDFObjects.get(id, callback) resolves the same face once the page's
        // canvas operator list has supplied it.
    }
    return new Promise((resolve) => {
        let settled = false;
        const finish = (value) => {
            if (settled) return;
            settled = true;
            window.clearTimeout(timer);
            resolve(value || null);
        };
        const timer = window.setTimeout(() => finish(null), timeoutMs);
        try {
            commonObjects.get(objectId, finish);
        } catch (_) {
            finish(null);
        }
    });
}

function refreshTransientSourceRunTypographyForPage(pageIndex) {
    const pageView = pdfViewer.getPageView(pageIndex);
    const layerEl = pageView?.textLayer?.div || pageView?.textLayer?.textLayerDiv;
    const annotationLayer = pageView?.div?.querySelector?.(':scope > .enpv-annotation-box-layer');
    if (!layerEl || !annotationLayer) return;
    annotationLayer.querySelectorAll(
        '.enpv-annotation-box.is-source-handle:not(.is-persisted-overlay), '
        + '.enpv-annotation-box.is-on-demand:not(.is-persisted-overlay)',
    ).forEach((box) => {
        const lookup = sourceGroupForBox(box);
        if (!lookup?.group) return;
        captureSourceSpanRunsForBox(box, lookup.group, lookup.layerEl || layerEl);
        const anchor = lookup.group.anchor;
        if (anchor?.dataset?.enpvPdfjsFontMetadataResolved === '1') {
            const runtimeFamily = String(anchor.dataset.enpvPdfjsLoadedFontFamily || '').trim();
            const pdfFontName = String(anchor.dataset.enpvPdfjsFontName || '').trim();
            if (runtimeFamily) {
                box.dataset.sourceRuntimeFontFamily = runtimeFamily;
                box.dataset.sourceFontFamily = pdfFontName || runtimeFamily;
                box.dataset.fontFamilyValue = pdfFontName || runtimeFamily;
                box.style.setProperty('--enpv-font-family', cssFontFamilyWithGenericFallback(runtimeFamily));
                box.dataset.sourceFontWeight = anchor.dataset.enpvPdfjsFontWeight || '400';
                box.dataset.sourceFontStyle = anchor.dataset.enpvPdfjsFontStyle || 'normal';
                box.dataset.sourceRenderFontWeight = '400';
                box.dataset.sourceRenderFontStyle = 'normal';
            } else {
                box.dataset.sourceFontWeight = anchor.dataset.enpvPdfjsFontWeight || '400';
                box.dataset.sourceFontStyle = anchor.dataset.enpvPdfjsFontStyle || 'normal';
            }
            box.dataset.sourceSemanticFontWeight = anchor.dataset.enpvPdfjsFontWeight || '400';
            box.dataset.sourceSemanticFontStyle = anchor.dataset.enpvPdfjsFontStyle || 'normal';
        }
    });
}

function hydratePdfjsTextLayerFontMetadata(pageIndex, pageView, layerEl) {
    if (!pageView?.pdfPage || !layerEl) return Promise.resolve(false);
    const cached = pdfjsTextLayerFontMetadataPromises.get(layerEl);
    if (cached) return cached;
    const promise = (async () => {
        const textContent = await pageView.pdfPage.getTextContent({
            includeMarkedContent: true,
            disableNormalization: true,
        });
        const textItems = Array.from(textContent?.items || [])
            .filter((item) => item && typeof item.str === 'string');
        const textDivs = Array.from(
            pageView?._textHighlighter?.textDivs
            || pageView?.textLayer?.highlighter?.textDivs
            || [],
        );
        if (!textItems.length || !textDivs.length) return false;

        const fontObjects = new Map(await Promise.all(
            Array.from(new Set(textItems.map((item) => item.fontName).filter(Boolean)))
                .map(async (fontName) => [
                    fontName,
                    await resolvePdfjsCommonObject(pageView.pdfPage.commonObjs, fontName),
                ]),
        ));
        let hydrated = 0;
        const itemCount = Math.min(textItems.length, textDivs.length);
        for (let index = 0; index < itemCount; index += 1) {
            const item = textItems[index];
            const textDiv = textDivs[index] || null;
            if (!(textDiv instanceof HTMLElement)) continue;

            const fontObject = fontObjects.get(item.fontName) || null;
            const faceName = String(
                fontObject?.name
                || fontObject?.fontFamily
                || '',
            ).trim();
            if (!faceName) continue;
            const runtimeFont = registerPdfjsRuntimeFontMetadata(fontObject, faceName);
            textDiv.dataset.enpvPdfjsFontName = faceName;
            textDiv.dataset.enpvPdfjsFontWeight = pdfjsFontWeightFromFaceName(faceName, fontObject);
            textDiv.dataset.enpvPdfjsFontStyle = pdfjsFontStyleFromFaceName(faceName, fontObject);
            if (runtimeFont?.cssFamily) {
                textDiv.dataset.enpvPdfjsLoadedFontFamily = runtimeFont.cssFamily;
            }
            textDiv.dataset.enpvPdfjsFontMetadataResolved = '1';
            hydrated += 1;
        }
        if (hydrated > 0) renderDocumentFontsInPicker();
        if (hydrated > 0 && layerEl.isConnected) {
            refreshTransientSourceRunTypographyForPage(pageIndex);
        }
        // A partial result is useful, but must remain retryable: commonObjs
        // can still be resolving individual faces when textlayerrendered
        // first fires.
        return hydrated > 0 && hydrated === itemCount;
    })().catch((error) => {
        console.warn('Failed to hydrate PDF.js text-layer font metadata', error);
        return false;
    });
    pdfjsTextLayerFontMetadataPromises.set(layerEl, promise);
    promise.then((complete) => {
        if (!complete && pdfjsTextLayerFontMetadataPromises.get(layerEl) === promise) {
            pdfjsTextLayerFontMetadataPromises.delete(layerEl);
        }
    });
    return promise;
}

async function ensurePdfjsTextLayerFontMetadata(pageIndex, pageView, layerEl) {
    for (let attempt = 0; attempt < 2; attempt += 1) {
        if (await hydratePdfjsTextLayerFontMetadata(pageIndex, pageView, layerEl)) return true;
        if (!layerEl?.isConnected) return false;
        await nextAnimationFrame();
    }
    return false;
}

async function hydrateRenderedPdfjsTextLayerFontMetadata() {
    const pageCount = Number(pdfViewer?.pagesCount || currentPdfDoc?.numPages || 0);
    const pending = [];
    for (let pageIndex = 0; pageIndex < pageCount; pageIndex += 1) {
        const pageView = pdfViewer?.getPageView?.(pageIndex);
        const layerEl = pageView?.textLayer?.div || pageView?.textLayer?.textLayerDiv;
        if (pageView?.pdfPage && layerEl) {
            pending.push(ensurePdfjsTextLayerFontMetadata(pageIndex, pageView, layerEl));
        }
    }
    await Promise.all(pending);
}

eventBus.on('textlayerrendered', (evt) => {
    const pageIndex = evt.pageNumber - 1;
    const pageView = pdfViewer.getPageView(pageIndex);
    if (!pageView || !pageView.textLayer) return;
    const layerEl = pageView.textLayer.div || pageView.textLayer.textLayerDiv;
    if (!layerEl) return;
    // Do not expose source edit handles until their PDF.js face metadata has
    // had a chance to resolve. Otherwise a fast first edit can scaffold a
    // mixed bold/regular row as generic 400/400 and permanently flatten it.
    pdfjsTextLayerFontMetadataPromises.delete(layerEl);
    ensurePdfjsTextLayerFontMetadata(pageIndex, pageView, layerEl).finally(() => {
        const currentLayer = pageView.textLayer?.div || pageView.textLayer?.textLayerDiv;
        if (!layerEl.isConnected || currentLayer !== layerEl) return;
        wireTextLayerClicks(layerEl, pageIndex);
        renderAnnotationBoxLayer(pageIndex);
    });
});

// AcroForm widgets render in pdf.js's annotationLayer, which can finish
// after textlayerrendered. Re-render our overlay so widget rects are
// available for the suppress-overlap pass below.
eventBus.on('annotationlayerrendered', (evt) => {
    const pageIndex = evt.pageNumber - 1;
    applyAcroFormEntriesToDom(pageIndex);
    enhanceGuidedDateFields(pageIndex);
    const pageView = pdfViewer.getPageView(pageIndex);
    const layerEl = pageView?.textLayer?.div || pageView?.textLayer?.textLayerDiv;
    const ready = layerEl
        ? ensurePdfjsTextLayerFontMetadata(pageIndex, pageView, layerEl)
        : Promise.resolve(false);
    ready.finally(() => renderAnnotationBoxLayer(pageIndex));
});

function wireTextLayerClicks(layerEl, pageIndex) {
    const counters = new Map();
    pageOccurrenceCounts.set(pageIndex, counters);
    const pageDiv = pdfViewer.getPageView(pageIndex)?.div || null;
    const spans = Array.from(layerEl.querySelectorAll('span'));
    for (const span of spans) {
        delete span.dataset.enpvIndex;
        delete span.dataset.enpvGroupIndex;
        delete span.dataset.enpvGroupAnchor;
        delete span.dataset.enpvPage;
        delete span.dataset.enpvOccurrence;
        clearSourceSpanOriginalText(span);
    }
    const groups = collectSourceTextGroups(layerEl, pageIndex, pageDiv);
    sourceGroupsByPage.set(pageIndex, { layerEl, groups });
    const applyGroups = (sourceGroups) => {
        counters.clear();
        for (const group of sourceGroups) {
            refreshSourceGroupTextFromDom(group, layerEl);
            const text = group.text;
            if (!text || !text.trim()) continue;
            const occ = counters.get(text) || 0;
            counters.set(text, occ + 1);
            group.occurrence = occ;
            for (const span of [...(group.spans || []), ...(group.relatedSpans || [])]) {
                span.dataset.enpvIndex = String(group.index);
                span.dataset.enpvGroupIndex = String(group.index);
                span.dataset.enpvPage = String(pageIndex);
                span.dataset.enpvOccurrence = String(occ);
                setSourceSpanOriginalText(span, text);
                if (span === group.anchor) span.dataset.enpvGroupAnchor = '1';
                if (span.dataset.enpvClickWired !== '1') {
                    span.addEventListener('click', onSpanClick);
                    span.addEventListener('dblclick', onSpanDblClick);
                    span.dataset.enpvClickWired = '1';
                }
            }
        }
        applyMovedSourceVisibilityForPage(pageIndex, layerEl);
    };
    applyGroups(groups);
    window.setTimeout(() => {
        if (!layerEl.isConnected) return;
        const latestPageDiv = pdfViewer.getPageView(pageIndex)?.div || null;
        const refreshedGroups = collectSourceTextGroups(layerEl, pageIndex, latestPageDiv);
        sourceGroupsByPage.set(pageIndex, { layerEl, groups: refreshedGroups });
        for (const span of spans) {
            delete span.dataset.enpvIndex;
            delete span.dataset.enpvGroupIndex;
            delete span.dataset.enpvGroupAnchor;
            delete span.dataset.enpvPage;
            delete span.dataset.enpvOccurrence;
            clearSourceSpanOriginalText(span);
        }
        applyGroups(refreshedGroups);
        renderAnnotationBoxLayer(pageIndex);
    }, 60);
}

function safeLocalStorageGet(key) {
    try { return window.localStorage.getItem(key); } catch (_) { return null; }
}

function safeLocalStorageSet(key, value) {
    try { window.localStorage.setItem(key, value); } catch (_) {}
}

function getSessionId() {
    const key = `edit_new_session_${DOC_ID}`;
    let id = safeLocalStorageGet(key);
    if (!id) {
        id = generateUuidV4();
        safeLocalStorageSet(key, id);
    }
    return id;
}

function annotationPageIndex(ann) {
    const candidates = [
        ann?.pageIndex,
        ann?.page_index,
        Number.isFinite(Number(ann?.db_page_number)) ? Number(ann.db_page_number) - 1 : null,
        Number.isFinite(Number(ann?.pageNumber)) ? Number(ann.pageNumber) - 1 : null,
        Number.isFinite(Number(ann?.page)) ? Number(ann.page) : null,
    ];
    for (const candidate of candidates) {
        const n = Number(candidate);
        if (Number.isFinite(n) && n >= 0) return Math.floor(n);
    }
    return 0;
}

function hydrateAnnotationForBoxes(ann, index) {
    const hydrated = normalizePromotedSourceGlyphBoxes({ ...ann });
    hydrated._uid = String(hydrated.id || hydrated.db_id || `ann_${index}`);
    const sL = Number(hydrated.sourceBlockLeft);
    const sT = Number(hydrated.sourceBlockTop);
    const sW = Number(hydrated.sourceBlockWidth);
    const sH = Number(hydrated.sourceBlockHeight);
    const pageH = Number(hydrated.sourcePageHeight);
    if ([sL, sT, sW, sH, pageH].every(Number.isFinite) && sW > 0 && sH > 0) {
        hydrated._originalBox = { x: sL, y: pageH - (sT + sH), w: sW, h: sH };
    }
    const pX = Number(hydrated.pdfX);
    const pY = Number(hydrated.pdfY);
    const pW = Number(hydrated.pdfWidth);
    const pH = Number(hydrated.pdfHeight);
    if ([pX, pY, pW, pH].every(Number.isFinite) && pW > 0 && pH > 0) {
        hydrated._originalPdfBox = { x: pX, y: pY, w: pW, h: pH };
        hydrated._currentPdfBox = { x: pX, y: pY, w: pW, h: pH };
    }
    const bX = Number(hydrated.pdfjsSourceX);
    const bY = Number(hydrated.pdfjsSourceY);
    const bW = Number(hydrated.pdfjsSourceW);
    const bH = Number(hydrated.pdfjsSourceH);
    if ([bX, bY, bW, bH].every(Number.isFinite) && bW > 0 && bH > 0) {
        hydrated._baselinePdfBox = { x: bX, y: bY, w: bW, h: bH };
    }
    return hydrated;
}

async function loadAnnotationBoxes(loadGeneration = viewerLoadGeneration) {
    if (!isCurrentViewerLoad(loadGeneration)) return false;
    if (annotationBoxesLoadPromise) return annotationBoxesLoadPromise;
    const payloadPromise = preloadInitialAnnotationBoxes();
    annotationBoxesLoadPromise = loadAnnotationBoxesOnce(loadGeneration, payloadPromise);
    return annotationBoxesLoadPromise;
}

function annotationBoxesUrl(options = {}) {
    const url = new URL(INFO_URL, window.location.origin);
    url.searchParams.set('session_id', getSessionId());
    if (Number.isFinite(Number(options.page)) && Number(options.page) >= 1) {
        url.searchParams.set('page', String(Math.trunc(Number(options.page))));
    }
    if (Array.isArray(options.pagesExclude) && options.pagesExclude.length) {
        const excluded = options.pagesExclude
            .map((pageNumber) => Math.trunc(Number(pageNumber)))
            .filter((pageNumber) => Number.isFinite(pageNumber) && pageNumber >= 1);
        if (excluded.length) url.searchParams.set('pages_exclude', excluded.join(','));
    }
    if (options.skipMeta === true) url.searchParams.set('skip_meta', '1');
    // Font metadata/faces come from the dedicated /fonts request. Avoid the
    // document-info endpoint synchronously extracting the same PDF fonts (and
    // the clean-file font set) before it can return annotations.
    url.searchParams.set('skip_embedded_fonts', '1');
    return url;
}

async function fetchAnnotationBoxesPayload(options = {}) {
    const response = await fetch(annotationBoxesUrl(options).toString(), {
        headers: { Accept: 'application/json' },
        credentials: 'same-origin',
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    if (!data?.success) throw new Error(data?.message || 'Failed to load annotation boxes.');
    return data;
}

const INITIAL_EXTRACTION_POLL_ATTEMPTS = 40;
const INITIAL_EXTRACTION_POLL_INTERVAL_MS = 350;

function waitForInitialExtractionPoll() {
    return new Promise((resolve) => {
        window.setTimeout(resolve, INITIAL_EXTRACTION_POLL_INTERVAL_MS);
    });
}

async function fetchInitialAnnotationBoxesPayload() {
    let data = null;
    for (let attempt = 0; attempt < INITIAL_EXTRACTION_POLL_ATTEMPTS; attempt += 1) {
        data = await fetchAnnotationBoxesPayload();
        if (data?.extraction_pending !== true) return data;
        setLoadingScreenMessage('Grouping PDF text into paragraphs...');
        await waitForInitialExtractionPoll();
    }
    return data;
}

function preloadInitialAnnotationBoxes() {
    if (!INFO_URL) return Promise.resolve(null);
    if (!annotationBoxesFetchPromise) {
        // Fetch the complete save snapshot concurrently with PDF rendering.
        // A partial page-only map must never be exposed to save/download,
        // because those operations replace the persisted annotation snapshot.
        // A newly uploaded PDF can reach this request before its queued Fitz
        // extraction has materialized promoted paragraph annotations. Wait for
        // that short-lived state instead of committing PDF.js's row handles;
        // otherwise the first open is row-grouped while a refresh is correctly
        // paragraph-grouped.
        annotationBoxesFetchPromise = fetchInitialAnnotationBoxesPayload();
    }
    return annotationBoxesFetchPromise;
}

async function loadAnnotationBoxesOnce(loadGeneration, payloadPromise) {
    if (!INFO_URL) return true;
    hydratingPersistedAnnotations = true;
    hydratingPersistedAnnotationsGeneration = loadGeneration;
    try {
        const data = await payloadPromise;
        if (!isCurrentViewerLoad(loadGeneration)) return false;

        if (typeof data.has_acro_form_widgets === 'boolean') {
            documentHasAcroFormWidgets = data.has_acro_form_widgets;
        }

        const raw = Array.isArray(data.annotations) ? data.annotations : [];
        const serverAnnotations = raw.filter((ann) => ann && ann.db_state !== 'deleted');
        const reloadOverride = pendingAnnotationStateOverride?.generation === loadGeneration
            ? pendingAnnotationStateOverride
            : null;
        if (reloadOverride) {
            const excluded = new Set(reloadOverride.excludedAnnotationIds || []);
            const merged = new Map();
            // Byte-based PDF rewrites do not persist the annotation table.
            // This override is a complete live snapshot, so it must be
            // authoritative: seeding with server-only rows can resurrect an
            // annotation that was removed locally just before the reload.
            (reloadOverride.records || []).forEach((annotation, index) => {
                const id = String(annotation?.id || annotation?.db_id || `override_${index}`);
                if (!excluded.has(id)) merged.set(id, annotation);
            });
            pendingAnnotationStateOverride = null;
            replacePersistedAnnotations(Array.from(merged.values()));
        } else {
            replacePersistedAnnotations(serverAnnotations);
        }
        // Capture echoed AcroForm entries so a) we can re-populate the
        // pdf.js form fields with previously-saved values, and b) the
        // Save round-trip preserves entries the user didn't touch this
        // session (server normalizes by `key`).
        const acroOverride = pendingAcroFormEntriesOverride?.generation === loadGeneration
            && Array.isArray(pendingAcroFormEntriesOverride.entries)
            ? pendingAcroFormEntriesOverride
            : null;
        if (acroOverride) {
            acroFormEntries = acroOverride.entries;
            pendingAcroFormEntriesOverride = null;
        } else {
            acroFormEntries = Array.isArray(data.acro_form_entries) ? data.acro_form_entries : [];
        }
        latestAcroFormEntriesSnapshot = acroFormEntries;
        applyAcroFormEntriesToStorage(loadGeneration).catch((err) => {
            console.warn('Failed to apply persisted AcroForm values to pdf.js storage', err);
        });
        // Rendering is deliberately owned by revealWhenEditedDocumentReady().
        // Keeping hydration data-only avoids four full overlay passes during
        // startup (two here and two in the reveal path).
        return true;
    } catch (err) {
        if (!isCurrentViewerLoad(loadGeneration)) return false;
        console.warn('Failed to load edit-new annotation boxes for pdf.js edit mode', err);
        setStatus('Failed to load saved edits; raw PDF hidden.', true);
        showError('Failed to load saved edits, so the raw PDF was not shown.');
        return false;
    } finally {
        if (hydratingPersistedAnnotationsGeneration === loadGeneration) {
            hydratingPersistedAnnotations = false;
            hydratingPersistedAnnotationsGeneration = 0;
        }
    }
}

// ---- AcroForm persistence (parity with /edit-new) -----------------------
//
// pdf.js renders AcroForm widgets natively when annotationMode is set to
// ENABLE_FORMS, and accumulates user input in `pdfDoc.annotationStorage`.
// We bridge that storage to the same `acro_form_entries` payload shape
// /edit-new posts, so saved values:
//   1. round-trip through the existing /save-annotation-state endpoint, and
//   2. re-populate the form fields when the document is re-opened.

// Walk every page's widget annotations once and run `cb(widget, pageIndex)`
// for each. Keeps annotationLookup logic in one place.
async function forEachWidget(cb, options = {}) {
    const pdfDocument = options.pdfDocument || currentPdfDoc;
    const shouldContinue = typeof options.shouldContinue === 'function'
        ? options.shouldContinue
        : () => true;
    if (!pdfDocument || !shouldContinue()) return false;
    const numPages = pdfDocument.numPages || 0;
    for (let pi = 0; pi < numPages; pi += 1) {
        if (!shouldContinue()) return false;
        let page;
        try { page = await pdfDocument.getPage(pi + 1); } catch (_) { continue; }
        if (!shouldContinue()) return false;
        let widgets;
        try { widgets = await page.getAnnotations({ intent: 'display' }); }
        catch (_) { continue; }
        if (!shouldContinue()) return false;
        for (const w of (Array.isArray(widgets) ? widgets : [])) {
            if (!w || w.subtype !== 'Widget' || w.hidden) continue;
            cb(w, pi);
        }
    }
    return shouldContinue();
}

function acroFieldKeyFromWidget(w) {
    return String(w?.fieldName || w?.id || w?.fullName || '').trim();
}

// Apply previously-saved values from `acroFormEntries` into pdf.js's
// annotationStorage so the rendered form widgets show the persisted
// state. Looks up by fieldName; falls back to widget.id if needed.
async function applyAcroFormEntriesToStorage(loadGeneration = viewerLoadGeneration) {
    const pdfDocument = currentPdfDoc;
    const entries = Array.isArray(acroFormEntries) ? acroFormEntries.slice() : [];
    const shouldContinue = () => (
        isCurrentViewerLoad(loadGeneration) && currentPdfDoc === pdfDocument
    );
    if (!pdfDocument || entries.length === 0 || !shouldContinue()) return false;
    const storage = pdfDocument.annotationStorage;
    if (!storage || typeof storage.setValue !== 'function') return;
    const byFieldName = new Map();
    const byKey = new Map();
    for (const entry of entries) {
        if (!entry) continue;
        const k = String(entry.key || '').trim();
        const fn = String(entry.fieldName || '').trim();
        if (k) byKey.set(k, entry);
        if (fn) byFieldName.set(fn, entry);
    }
    const completed = await forEachWidget((w) => {
        const fn = String(w.fieldName || '').trim();
        const entry = (fn && byFieldName.get(fn)) || (w.id && byKey.get(String(w.id))) || null;
        if (!entry) return;
        const isCheck = w.checkBox === true || entry.checkBox === true;
        const isRadio = w.radioButton === true || entry.radioButton === true;
        let storageValue;
        if (isCheck || isRadio) {
            // pdf.js storage for buttons expects { value: true/false } or
            // (radio) the export value of the selected button.
            const v = entry.value;
            if (isRadio) {
                storageValue = { value: typeof v === 'string' ? v : (v ? String(w.exportValue || v) : '') };
            } else {
                const truthy = (v === true) || v === '1' || v === 'true' || v === w.exportValue;
                storageValue = { value: !!truthy };
            }
        } else {
            const v = entry.value;
            storageValue = { value: v == null ? '' : (Array.isArray(v) ? v : String(v)) };
        }
        try { storage.setValue(w.id, storageValue); } catch (_) { /* noop */ }
    }, { pdfDocument, shouldContinue });
    if (!completed || !shouldContinue()) return false;
    applyAcroFormEntriesToDom();
    return true;
}

function acroEntryTruthyValue(value, exportValue = '') {
    return value === true
        || value === 1
        || value === '1'
        || value === 'true'
        || (exportValue && String(value) === String(exportValue));
}

function applyAcroFormEntriesToDom(pageIndex = null) {
    if (!Array.isArray(acroFormEntries) || acroFormEntries.length === 0) return;
    const byFieldName = new Map();
    const byKey = new Map();
    for (const entry of acroFormEntries) {
        if (!entry) continue;
        const key = String(entry.key || '').trim();
        const fieldName = String(entry.fieldName || '').trim();
        if (key) byKey.set(key, entry);
        if (fieldName) byFieldName.set(fieldName, entry);
    }
    const selector = pageIndex == null
        ? '.annotationLayer input, .annotationLayer textarea, .annotationLayer select'
        : `.page[data-page-number="${Number(pageIndex) + 1}"] .annotationLayer input, `
            + `.page[data-page-number="${Number(pageIndex) + 1}"] .annotationLayer textarea, `
            + `.page[data-page-number="${Number(pageIndex) + 1}"] .annotationLayer select`;
    document.querySelectorAll(selector).forEach((el) => {
        const host = el.closest('[data-annotation-id]');
        const annotationId = String(host?.dataset?.annotationId || '').trim();
        const fieldName = String(el.getAttribute('name') || '').trim();
        const entry = (fieldName && byFieldName.get(fieldName))
            || (annotationId && byKey.get(annotationId))
            || null;
        if (!entry) return;
        const rawValue = entry.value;
        const type = String(el.getAttribute('type') || '').toLowerCase();
        if (type === 'checkbox') {
            el.checked = acroEntryTruthyValue(rawValue, el.value || entry.exportValue || '');
        } else if (type === 'radio') {
            const value = String(rawValue ?? '');
            el.checked = value !== '' && (value === String(el.value || '') || value === String(entry.exportValue || ''));
        } else if (el instanceof HTMLSelectElement && el.multiple && Array.isArray(rawValue)) {
            const values = new Set(rawValue.map((value) => String(value ?? '')));
            Array.from(el.options).forEach((option) => { option.selected = values.has(String(option.value)); });
        } else {
            el.value = rawValue == null ? '' : (Array.isArray(rawValue) ? rawValue.join('\n') : String(rawValue));
        }
    });
    enhanceGuidedDateFields(pageIndex);
}

const GUIDED_DATE_FIELD_NAMES = new Set([
    'sdr_tenancy_began',
    'sdr_keys_turned_in',
]);
const GUIDED_DATE_MONTHS = [
    'January',
    'February',
    'March',
    'April',
    'May',
    'June',
    'July',
    'August',
    'September',
    'October',
    'November',
    'December',
];
const GUIDED_DATE_MONTHS_SHORT = [
    'Jan',
    'Feb',
    'Mar',
    'Apr',
    'May',
    'Jun',
    'Jul',
    'Aug',
    'Sep',
    'Oct',
    'Nov',
    'Dec',
];
let guidedDatePickerEl = null;
let guidedDatePickerState = null;

function textIndicatesGuidedDateField(value) {
    const text = String(value || '').trim().toLowerCase();
    if (!text) return false;
    return /(^|[_\-\s])date($|[_\-\s])/.test(text)
        || /\b(began|commenc(?:e|ing)|terminat(?:e|ing))\b/.test(text);
}

function isGuidedDateField(el) {
    if (!IS_GUIDED_MODE || !el || el instanceof HTMLSelectElement) return false;
    if (!el.matches?.('.annotationLayer input, .annotationLayer textarea')) return false;
    const type = String(el.getAttribute('type') || 'text').toLowerCase();
    if (type && !['text', ''].includes(type)) return false;
    if (el.disabled || el.readOnly) return false;

    const fieldName = String(el.getAttribute('name') || '').trim();
    if (GUIDED_DATE_FIELD_NAMES.has(fieldName)) return true;
    const host = el.closest('[data-annotation-id]');
    const labelText = [
        fieldName,
        el.id,
        el.getAttribute('aria-label'),
        el.getAttribute('title'),
        el.getAttribute('placeholder'),
        host?.getAttribute?.('aria-label'),
        host?.getAttribute?.('title'),
    ].filter(Boolean).join(' ');
    if (textIndicatesGuidedDateField(labelText)) return true;

    const value = String(el.value || '').trim().toLowerCase();
    return value === '[date]' || value === 'date';
}

function enhanceGuidedDateFields(pageIndex = null) {
    if (!IS_GUIDED_MODE) return;
    const selector = pageIndex == null
        ? '.annotationLayer input, .annotationLayer textarea'
        : `.page[data-page-number="${Number(pageIndex) + 1}"] .annotationLayer input, `
            + `.page[data-page-number="${Number(pageIndex) + 1}"] .annotationLayer textarea`;
    document.querySelectorAll(selector).forEach((el) => {
        if (!isGuidedDateField(el)) return;
        el.classList.add('enpv-guided-date-field');
        el.setAttribute('autocomplete', 'off');
        el.setAttribute('aria-haspopup', 'dialog');
    });
}

function guidedDateAtLocalNoon(year, month, day) {
    return new Date(Number(year), Number(month), Number(day), 12, 0, 0, 0);
}

function parseGuidedDateValue(value) {
    const raw = String(value || '').trim();
    if (!raw || raw === '[DATE]') return null;
    const iso = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
    if (iso) {
        const date = guidedDateAtLocalNoon(iso[1], Number(iso[2]) - 1, iso[3]);
        return Number.isNaN(date.getTime()) ? null : date;
    }
    const slash = raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);
    if (slash) {
        const year = Number(slash[3]) < 100 ? Number(slash[3]) + 2000 : Number(slash[3]);
        const date = guidedDateAtLocalNoon(year, Number(slash[1]) - 1, slash[2]);
        return Number.isNaN(date.getTime()) ? null : date;
    }
    const parsed = new Date(raw);
    if (Number.isNaN(parsed.getTime())) return null;
    return guidedDateAtLocalNoon(parsed.getFullYear(), parsed.getMonth(), parsed.getDate());
}

function formatGuidedDate(date) {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return '';
    return `${GUIDED_DATE_MONTHS_SHORT[date.getMonth()]} ${date.getDate()}, ${date.getFullYear()}`;
}

function sameGuidedCalendarDay(left, right) {
    return left instanceof Date
        && right instanceof Date
        && left.getFullYear() === right.getFullYear()
        && left.getMonth() === right.getMonth()
        && left.getDate() === right.getDate();
}

function ensureGuidedDatePicker() {
    if (guidedDatePickerEl) return guidedDatePickerEl;
    const picker = document.createElement('div');
    picker.id = 'enpv-guided-date-picker';
    picker.className = 'enpv-guided-date-picker';
    picker.setAttribute('role', 'dialog');
    picker.setAttribute('aria-label', 'Choose date');
    picker.hidden = true;
    document.body.appendChild(picker);
    guidedDatePickerEl = picker;
    return picker;
}

function positionGuidedDatePicker() {
    const picker = guidedDatePickerEl;
    const input = guidedDatePickerState?.input;
    if (!picker || picker.hidden || !input) return;
    const rect = input.getBoundingClientRect();
    const pickerWidth = Math.max(286, Math.min(340, Math.max(rect.width, 286)));
    picker.style.width = `${pickerWidth}px`;

    const pickerHeight = picker.offsetHeight || 336;
    const gap = 8;
    const fitsBelow = rect.bottom + gap + pickerHeight <= window.innerHeight - 10;
    const top = fitsBelow
        ? rect.bottom + gap
        : Math.max(10, rect.top - gap - pickerHeight);
    const left = Math.max(10, Math.min(window.innerWidth - pickerWidth - 10, rect.left));
    picker.style.left = `${left}px`;
    picker.style.top = `${top}px`;
}

function renderGuidedDatePicker() {
    const picker = ensureGuidedDatePicker();
    const state = guidedDatePickerState;
    if (!state?.input) return;

    const firstOfMonth = guidedDateAtLocalNoon(state.viewYear, state.viewMonth, 1);
    const firstWeekday = firstOfMonth.getDay();
    const daysInMonth = new Date(state.viewYear, state.viewMonth + 1, 0).getDate();
    const selected = state.selectedDate;
    const today = guidedDateAtLocalNoon(
        new Date().getFullYear(),
        new Date().getMonth(),
        new Date().getDate(),
    );

    const monthOptions = GUIDED_DATE_MONTHS.map((month, index) => (
        `<option value="${index}"${index === state.viewMonth ? ' selected' : ''}>${month}</option>`
    )).join('');

    let dayButtons = '';
    for (let i = 0; i < firstWeekday; i += 1) {
        dayButtons += '<span class="enpv-guided-date-empty" aria-hidden="true"></span>';
    }
    for (let day = 1; day <= daysInMonth; day += 1) {
        const date = guidedDateAtLocalNoon(state.viewYear, state.viewMonth, day);
        const classes = [
            'enpv-guided-date-day',
            sameGuidedCalendarDay(date, selected) ? 'is-selected' : '',
            sameGuidedCalendarDay(date, today) ? 'is-today' : '',
        ].filter(Boolean).join(' ');
        dayButtons += `<button type="button" class="${classes}" data-day="${day}" aria-label="${formatGuidedDate(date)}">${day}</button>`;
    }

    picker.innerHTML = `
        <div class="enpv-guided-date-header">
            <button type="button" class="enpv-guided-date-nav" data-action="prev" aria-label="Previous month">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m15 18-6-6 6-6"></path></svg>
            </button>
            <label class="enpv-guided-date-month">
                <span class="sr-only">Month</span>
                <select>${monthOptions}</select>
            </label>
            <label class="enpv-guided-date-year">
                <span class="sr-only">Year</span>
                <input type="number" min="1900" max="2100" step="1" value="${state.viewYear}">
            </label>
            <button type="button" class="enpv-guided-date-nav" data-action="next" aria-label="Next month">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg>
            </button>
        </div>
        <div class="enpv-guided-date-weekdays" aria-hidden="true">
            <span>Sun</span><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span>
        </div>
        <div class="enpv-guided-date-grid">${dayButtons}</div>
    `;

    picker.querySelector('[data-action="prev"]')?.addEventListener('click', () => {
        const next = guidedDateAtLocalNoon(state.viewYear, state.viewMonth - 1, 1);
        state.viewYear = next.getFullYear();
        state.viewMonth = next.getMonth();
        renderGuidedDatePicker();
    });
    picker.querySelector('[data-action="next"]')?.addEventListener('click', () => {
        const next = guidedDateAtLocalNoon(state.viewYear, state.viewMonth + 1, 1);
        state.viewYear = next.getFullYear();
        state.viewMonth = next.getMonth();
        renderGuidedDatePicker();
    });
    picker.querySelector('.enpv-guided-date-month select')?.addEventListener('change', (event) => {
        state.viewMonth = Number.parseInt(event.target.value || '0', 10) || 0;
        renderGuidedDatePicker();
    });
    picker.querySelector('.enpv-guided-date-year input')?.addEventListener('change', (event) => {
        const year = Number.parseInt(event.target.value || '', 10);
        state.viewYear = Number.isFinite(year) ? Math.max(1900, Math.min(2100, year)) : new Date().getFullYear();
        renderGuidedDatePicker();
    });
    picker.querySelectorAll('.enpv-guided-date-day').forEach((button) => {
        button.addEventListener('click', () => {
            const day = Number.parseInt(button.dataset.day || '', 10);
            if (!Number.isFinite(day)) return;
            commitGuidedDateSelection(guidedDateAtLocalNoon(state.viewYear, state.viewMonth, day));
        });
    });

    positionGuidedDatePicker();
}

function openGuidedDatePicker(input) {
    if (!isGuidedDateField(input)) return;
    const parsed = parseGuidedDateValue(input.value);
    const base = parsed || new Date();
    guidedDatePickerState = {
        input,
        selectedDate: parsed,
        viewYear: base.getFullYear(),
        viewMonth: base.getMonth(),
    };
    const picker = ensureGuidedDatePicker();
    picker.hidden = false;
    input.classList.add('is-guided-date-open');
    renderGuidedDatePicker();
}

function closeGuidedDatePicker() {
    guidedDatePickerState?.input?.classList?.remove('is-guided-date-open');
    guidedDatePickerState = null;
    if (guidedDatePickerEl) guidedDatePickerEl.hidden = true;
}

function commitGuidedDateSelection(date) {
    const input = guidedDatePickerState?.input;
    if (!input) return;
    input.value = formatGuidedDate(date);
    const host = input.closest('[data-annotation-id]');
    const annotationId = String(host?.dataset?.annotationId || '').trim();
    if (annotationId && currentPdfDoc?.annotationStorage?.setValue) {
        try { currentPdfDoc.annotationStorage.setValue(annotationId, { value: input.value }); } catch (_) { /* noop */ }
    }
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
    latestAcroFormEntriesSnapshot = collectRenderedAcroFormEntriesSnapshot();
    scheduleAcroFormStateSave(250);
    closeGuidedDatePicker();
    input.focus();
}

function installGuidedDatePickerControls() {
    if (!IS_GUIDED_MODE) return;
    document.addEventListener('focusin', (event) => {
        if (isGuidedDateField(event.target)) openGuidedDatePicker(event.target);
    }, true);
    document.addEventListener('click', (event) => {
        if (isGuidedDateField(event.target)) openGuidedDatePicker(event.target);
    }, true);
    document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape' && guidedDatePickerState) closeGuidedDatePicker();
    }, true);
    document.addEventListener('pointerdown', (event) => {
        if (!guidedDatePickerState || !guidedDatePickerEl) return;
        const path = event.composedPath?.() || [];
        if (path.includes(guidedDatePickerEl) || path.includes(guidedDatePickerState.input)) return;
        closeGuidedDatePicker();
    }, true);
    container?.addEventListener?.('scroll', positionGuidedDatePicker, { passive: true });
    window.addEventListener('scroll', positionGuidedDatePicker, { passive: true });
    window.addEventListener('resize', positionGuidedDatePicker);
    enhanceGuidedDateFields();
}

installGuidedDatePickerControls();

function collectAcroFormDomValues() {
    const byAnnotationId = new Map();
    const byFieldName = new Map();
    document.querySelectorAll('.annotationLayer input, .annotationLayer textarea, .annotationLayer select').forEach((el) => {
        const host = el.closest('[data-annotation-id]');
        const annotationId = String(host?.dataset?.annotationId || '').trim();
        const fieldName = String(el.getAttribute('name') || '').trim();
        const type = String(el.getAttribute('type') || '').toLowerCase();
        let value;
        if (type === 'checkbox') {
            value = el.checked ? String(el.value || '1') : '';
        } else if (type === 'radio') {
            if (!el.checked) return;
            value = String(el.value || '');
        } else if (el instanceof HTMLSelectElement && el.multiple) {
            value = Array.from(el.selectedOptions).map((option) => String(option.value || ''));
        } else {
            value = String(el.value ?? '');
        }
        const payload = { value };
        if (annotationId) byAnnotationId.set(annotationId, payload);
        if (fieldName) byFieldName.set(fieldName, payload);
    });
    return { byAnnotationId, byFieldName };
}

function acroFormControlValue(el) {
    const type = String(el?.getAttribute?.('type') || '').toLowerCase();
    if (type === 'checkbox') {
        return el.checked ? String(el.value || '1') : '';
    }
    if (type === 'radio') {
        if (!el.checked) return null;
        return String(el.value || '');
    }
    if (el instanceof HTMLSelectElement && el.multiple) {
        return Array.from(el.selectedOptions).map((option) => String(option.value || ''));
    }
    return String(el?.value ?? '');
}

function collectRenderedAcroFormEntriesSnapshot(baseEntries = acroFormEntries) {
    const existingByKey = new Map();
    for (const entry of (Array.isArray(baseEntries) ? baseEntries : [])) {
        if (!entry) continue;
        const key = String(entry.key || entry.fieldName || '').trim();
        if (key) existingByKey.set(key, entry);
    }

    const entriesByKey = new Map(existingByKey);
    document.querySelectorAll('.annotationLayer input, .annotationLayer textarea, .annotationLayer select').forEach((el) => {
        const value = acroFormControlValue(el);
        if (value === null) return;
        const host = el.closest('[data-annotation-id]');
        const annotationId = String(host?.dataset?.annotationId || '').trim();
        const fieldName = String(el.getAttribute('name') || '').trim();
        const key = fieldName || annotationId;
        if (!key) return;
        const existing = existingByKey.get(key) || existingByKey.get(fieldName) || existingByKey.get(annotationId) || {};
        const type = String(el.getAttribute('type') || '').toLowerCase();
        const pageNumber = Number.parseInt(el.closest('.page')?.dataset?.pageNumber || '', 10);
        const pageIndex = Number.isFinite(pageNumber) && pageNumber > 0
            ? pageNumber - 1
            : (Number.isFinite(Number(existing.pageIndex)) ? Number(existing.pageIndex) : null);
        entriesByKey.set(key, {
            ...existing,
            key,
            fieldName: fieldName || String(existing.fieldName || key),
            pageIndex,
            fieldType: String(existing.fieldType || (type === 'checkbox' || type === 'radio' ? 'BTN' : 'TX')).toUpperCase(),
            checkBox: type === 'checkbox' || existing.checkBox === true,
            radioButton: type === 'radio' || existing.radioButton === true,
            combo: el instanceof HTMLSelectElement || existing.combo === true,
            multiLine: el instanceof HTMLTextAreaElement || existing.multiLine === true,
            multiSelect: (el instanceof HTMLSelectElement && el.multiple) || existing.multiSelect === true,
            exportValue: String(existing.exportValue || el.value || ''),
            rect: existing.rect || null,
            textColor: existing.textColor || null,
            value,
        });
    });

    return Array.from(entriesByKey.values());
}

// Snapshot the live AcroForm state out of pdf.js's annotationStorage and
// build entries shaped like the server's `acro_form_entries` payload.
// Untouched widgets (no storage value) fall back to the entry already
// echoed by documentInfo, so the round-trip is loss-less.
async function collectAcroFormEntriesForSave() {
    if (!currentPdfDoc) return Array.isArray(acroFormEntries) ? acroFormEntries : [];
    if (documentHasAcroFormWidgets === false) {
        // Avoid currentPdfDoc.getPage(...).getAnnotations(...) across every page
        // when the server's complete normalized extraction proves that the PDF
        // contains no widgets. A rendered widget is a cheap defensive override
        // for stale metadata; legacy/unknown documents never enter this branch.
        const renderedWidget = document.querySelector(
            '.annotationLayer input, .annotationLayer textarea, .annotationLayer select'
        );
        if (!renderedWidget) {
            return Array.isArray(acroFormEntries) ? acroFormEntries : [];
        }
        documentHasAcroFormWidgets = true;
    }
    if (document.activeElement?.matches?.('.annotationLayer input, .annotationLayer textarea, .annotationLayer select')) {
        document.activeElement.blur();
    }
    const storage = currentPdfDoc.annotationStorage;
    const storageMap = (storage && typeof storage.getAll === 'function') ? (storage.getAll() || {}) : {};
    const domValues = collectAcroFormDomValues();
    const existingByKey = new Map();
    for (const entry of (Array.isArray(acroFormEntries) ? acroFormEntries : [])) {
        if (!entry) continue;
        const k = String(entry.key || entry.fieldName || '').trim();
        if (k) existingByKey.set(k, entry);
    }
    const out = [];
    const seenKeys = new Set();
    await forEachWidget((w, pageIndex) => {
        const key = acroFieldKeyFromWidget(w);
        if (!key) return;
        if (seenKeys.has(key)) return; // dedupe widgets that share a field
        seenKeys.add(key);
        const stored = storageMap[w.id];
        const domValue = (w.id && domValues.byAnnotationId.get(String(w.id)))
            || (w.fieldName && domValues.byFieldName.get(String(w.fieldName)))
            || null;
        const existing = existingByKey.get(key) || existingByKey.get(String(w.fieldName || '')) || null;
        const isCheck = w.checkBox === true;
        const isRadio = w.radioButton === true;
        const forceClear = acroWidgetMatchesPendingClear(w, pageIndex, key);
        let value;
        if (forceClear) {
            value = '';
        } else if (domValue && Object.prototype.hasOwnProperty.call(domValue, 'value')) {
            value = domValue.value;
        } else if (stored && Object.prototype.hasOwnProperty.call(stored, 'value')) {
            value = stored.value;
        } else if (existing) {
            value = existing.value;
        } else {
            return; // never touched and no prior entry — skip
        }
        if (forceClear) {
            if (w.id && storage && typeof storage.setValue === 'function') {
                try { storage.setValue(w.id, { value: isCheck || isRadio ? false : '' }); } catch (_) {}
            }
            pendingClearedAcroFormKeys.add(key);
            if (w.fieldName) pendingClearedAcroFormKeys.add(String(w.fieldName));
        } else if (domValue && Object.prototype.hasOwnProperty.call(domValue, 'value')) {
            if (isCheck) {
                value = domValue.value ? (w.exportValue || domValue.value || '1') : '';
            } else if (isRadio) {
                value = domValue.value ? String(domValue.value) : '';
            }
        } else if (stored && Object.prototype.hasOwnProperty.call(stored, 'value')) {
            if (isCheck) {
                value = stored.value ? (w.exportValue || '1') : '';
            } else if (isRadio) {
                value = stored.value ? String(stored.value) : '';
            }
        }
        if (Array.isArray(value)) {
            value = value.map((s) => String(s ?? ''));
        } else if (value == null) {
            value = '';
        } else if (!isCheck && !isRadio) {
            value = String(value);
        }
        out.push({
            key,
            fieldName: String(w.fieldName || key),
            pageIndex,
            fieldType: String(w.fieldType || existing?.fieldType || '').toUpperCase(),
            checkBox: isCheck || existing?.checkBox === true,
            radioButton: isRadio || existing?.radioButton === true,
            combo: w.combo === true || existing?.combo === true,
            multiLine: w.multiLine === true || existing?.multiLine === true,
            multiSelect: w.multiSelect === true || existing?.multiSelect === true,
            exportValue: String(w.exportValue || existing?.exportValue || ''),
            rect: Array.isArray(w.rect) ? w.rect.slice(0, 4) : (existing?.rect || null),
            textColor: existing?.textColor || null,
            value,
        });
    });
    // Preserve any persisted entries that don't correspond to a widget
    // currently in the rendered PDF (defensive — keeps server state
    // intact even if a widget couldn't be resolved this round).
    for (const [key, entry] of existingByKey) {
        if (!seenKeys.has(key)) {
            out.push(pendingClearedAcroFormKeys.has(key) ? { ...entry, value: '' } : entry);
        }
    }
    return out;
}

function acroFormStatePayload(entries = null) {
    const acroEntries = Array.isArray(entries)
        ? entries
        : (latestAcroFormEntriesSnapshot.length ? latestAcroFormEntriesSnapshot : collectRenderedAcroFormEntriesSnapshot());
    return {
        _token: CSRF,
        session_id: getSessionId(),
        acro_form_entries: acroEntries,
    };
}

function scheduleAcroFormStateSave(delayMs = 700) {
    if (!SAVE_ACRO_FORM_URL || suppressAutoSaveForNavigation) return;
    if (acroFormSaveTimer) window.clearTimeout(acroFormSaveTimer);
    acroFormSaveTimer = window.setTimeout(() => {
        acroFormSaveTimer = 0;
        persistAcroFormStateOnly().catch((err) => {
            console.warn('Failed to save AcroForm state', err);
        });
    }, delayMs);
}

async function persistAcroFormStateOnly(options = {}) {
    if (!SAVE_ACRO_FORM_URL) return false;
    if (acroFormSaveInFlight) {
        acroFormSaveAgainAfterCurrent = true;
        return false;
    }
    if (acroFormSaveTimer) {
        window.clearTimeout(acroFormSaveTimer);
        acroFormSaveTimer = 0;
    }

    const entries = options.entries || latestAcroFormEntriesSnapshot || [];
    const payload = acroFormStatePayload(entries.length ? entries : collectRenderedAcroFormEntriesSnapshot());
    if (!Array.isArray(payload.acro_form_entries) || payload.acro_form_entries.length === 0) {
        return false;
    }

    if (options.beacon === true && navigator.sendBeacon) {
        const blob = new Blob([JSON.stringify(payload)], { type: 'application/json' });
        return navigator.sendBeacon(SAVE_ACRO_FORM_URL, blob);
    }

    acroFormSaveInFlight = true;
    try {
        const response = await fetch(SAVE_ACRO_FORM_URL, {
            method: 'POST',
            credentials: 'same-origin',
            keepalive: options.keepalive === true,
            headers: {
                'Content-Type': 'application/json',
                Accept: 'application/json',
                'X-CSRF-TOKEN': CSRF,
            },
            body: JSON.stringify(payload),
        });
        const result = await response.json().catch(() => ({}));
        if (!response.ok || !result?.success) {
            throw new Error(result?.message || result?.error || `AcroForm save failed (${response.status})`);
        }
        if (result.session_id && String(result.session_id).trim()) {
            safeLocalStorageSet(`edit_new_session_${DOC_ID}`, String(result.session_id).trim());
        }
        acroFormEntries = Array.isArray(payload.acro_form_entries) ? payload.acro_form_entries : [];
        latestAcroFormEntriesSnapshot = acroFormEntries;
        setSaveStatus('Saved');
        setStatus('Form fields saved.');
        return true;
    } finally {
        acroFormSaveInFlight = false;
        if (acroFormSaveAgainAfterCurrent && !suppressAutoSaveForNavigation) {
            acroFormSaveAgainAfterCurrent = false;
            scheduleAcroFormStateSave(150);
        }
    }
}

function isCleanModernGuidedInvoice() {
    if (!IS_GUIDED_MODE) return false;
    if (TEMPLATE_TYPE === 'invoice') return true;
    return Boolean(
        invoiceField('invoice_total')
        || document.querySelector('.annotationLayer input[name^="invoice_item_"], .annotationLayer textarea[name^="invoice_item_"]')
    );
}

function invoiceField(name) {
    return document.querySelector(`.annotationLayer input[name="${CSS.escape(name)}"], .annotationLayer textarea[name="${CSS.escape(name)}"]`);
}

function invoiceFieldValue(name) {
    return String(invoiceField(name)?.value ?? '').trim();
}

function parseInvoiceNumber(value) {
    const cleaned = String(value ?? '').replace(/[^0-9.-]/g, '');
    const number = Number.parseFloat(cleaned);
    return Number.isFinite(number) ? number : 0;
}

function formatInvoiceMoney(value) {
    return '$' + Number(value || 0).toLocaleString('en-US', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
    });
}

function collectInvoiceRowIndexes() {
    const indexes = new Set();
    document.querySelectorAll('.annotationLayer input[name], .annotationLayer textarea[name]').forEach((el) => {
        const match = String(el.getAttribute('name') || '').match(/^invoice_item_(\d+)_(qty|description|unit_price|amount)$/);
        if (match) indexes.add(Number(match[1]));
    });
    return Array.from(indexes).sort((a, b) => a - b);
}

function visibleInvoiceFieldRect(element) {
    if (!element) return null;
    const rect = element.getBoundingClientRect();
    if (rect.width <= 1 || rect.height <= 1) return null;
    return rect;
}

function positionGuidedInvoiceRowAddButton() {
    const button = document.getElementById('enpv-guided-invoice-row-add');
    if (!button || !isCleanModernGuidedInvoice()) return;

    const indexes = collectInvoiceRowIndexes();
    const lastIndex = indexes.length ? indexes[indexes.length - 1] : 0;
    const amountField = invoiceField(`invoice_item_${lastIndex}_amount`);
    const unitPriceField = invoiceField(`invoice_item_${lastIndex}_unit_price`);
    const totalField = invoiceField('invoice_total');
    const anchor = [amountField, unitPriceField, totalField].find((field) => visibleInvoiceFieldRect(field));

    if (!anchor) {
        button.hidden = true;
        return;
    }

    const rect = visibleInvoiceFieldRect(anchor);
    if (!rect) {
        button.hidden = true;
        return;
    }

    const topChrome = 66;
    const visible = rect.bottom > topChrome
        && rect.top < window.innerHeight - 8
        && rect.right > 0
        && rect.left < window.innerWidth;
    if (!visible) {
        button.hidden = true;
        return;
    }

    button.hidden = false;
    const size = button.offsetWidth || 36;
    const left = Math.max(8, rect.right + 12);
    const top = Math.max(topChrome, Math.min(window.innerHeight - size - 8, rect.top + (rect.height / 2) - (size / 2)));
    button.style.left = `${left}px`;
    button.style.top = `${top}px`;
}

function updateGuidedInvoiceTotals(options = {}) {
    if (!isCleanModernGuidedInvoice()) return;
    const rowIndexes = collectInvoiceRowIndexes();
    if (!rowIndexes.length) {
        positionGuidedInvoiceRowAddButton();
        return;
    }
    let subtotal = 0;
    for (const index of rowIndexes) {
        const qty = parseInvoiceNumber(invoiceFieldValue(`invoice_item_${index}_qty`));
        const unitPrice = parseInvoiceNumber(invoiceFieldValue(`invoice_item_${index}_unit_price`));
        const amount = Math.round(qty * unitPrice * 100) / 100;
        const amountField = invoiceField(`invoice_item_${index}_amount`);
        if (amountField) {
            const shouldShow = invoiceFieldValue(`invoice_item_${index}_qty`) !== ''
                || invoiceFieldValue(`invoice_item_${index}_unit_price`) !== '';
            amountField.value = shouldShow ? formatInvoiceMoney(amount) : '';
        }
        subtotal += amount;
    }
    const total = Math.max(subtotal, 0);
    const totalField = invoiceField('invoice_total');
    if (totalField) totalField.value = formatInvoiceMoney(total);

    const totalLabel = document.getElementById('enpv-guided-invoice-total');
    if (totalLabel) totalLabel.textContent = formatInvoiceMoney(total);

    latestAcroFormEntriesSnapshot = collectRenderedAcroFormEntriesSnapshot();
    if (options.save !== false) scheduleAcroFormStateSave(500);
    positionGuidedInvoiceRowAddButton();
}

function collectGuidedInvoicePayload() {
    const indexes = collectInvoiceRowIndexes();
    const items = indexes.map((index) => ({
        qty: invoiceFieldValue(`invoice_item_${index}_qty`) === '' ? null : parseInvoiceNumber(invoiceFieldValue(`invoice_item_${index}_qty`)),
        description: invoiceFieldValue(`invoice_item_${index}_description`),
        unit_price: invoiceFieldValue(`invoice_item_${index}_unit_price`) === '' ? null : parseInvoiceNumber(invoiceFieldValue(`invoice_item_${index}_unit_price`)),
    }));

    return {
        company_name: invoiceFieldValue('invoice_company_name'),
        company_address: invoiceFieldValue('invoice_company_address'),
        customer_name: invoiceFieldValue('invoice_customer_name'),
        customer_address: invoiceFieldValue('invoice_customer_address'),
        invoice_number: invoiceFieldValue('invoice_number'),
        invoice_date: invoiceFieldValue('invoice_date'),
        due_date: invoiceFieldValue('invoice_due_date'),
        items,
        style: 'default',
    };
}

function guidedInvoicePayloadToAcroEntries(payload) {
    const entries = [
        ['invoice_company_name', payload.company_name],
        ['invoice_company_address', payload.company_address],
        ['invoice_customer_name', payload.customer_name],
        ['invoice_customer_address', payload.customer_address],
        ['invoice_number', payload.invoice_number],
        ['invoice_date', payload.invoice_date],
        ['invoice_due_date', payload.due_date],
    ].map(([fieldName, value]) => ({
        key: fieldName,
        fieldName,
        pageIndex: 0,
        fieldType: 'TX',
        value: value ?? '',
    }));

    let total = 0;
    (payload.items || []).forEach((item, index) => {
        const qty = Number(item?.qty || 0);
        const unitPrice = Number(item?.unit_price || 0);
        const amount = Math.round(qty * unitPrice * 100) / 100;
        total += amount;
        [
            [`invoice_item_${index}_qty`, item?.qty ?? ''],
            [`invoice_item_${index}_description`, item?.description ?? ''],
            [`invoice_item_${index}_unit_price`, item?.unit_price ?? ''],
            [`invoice_item_${index}_amount`, item?.qty == null && item?.unit_price == null ? '' : formatInvoiceMoney(amount)],
        ].forEach(([fieldName, value]) => {
            entries.push({
                key: fieldName,
                fieldName,
                pageIndex: 0,
                fieldType: 'TX',
                value: value ?? '',
            });
        });
    });
    entries.push({
        key: 'invoice_total',
        fieldName: 'invoice_total',
        pageIndex: 0,
        fieldType: 'TX',
        value: formatInvoiceMoney(total),
    });
    return entries;
}

async function addGuidedInvoiceRow() {
    if (!REGENERATE_INVOICE_URL) return;
    updateGuidedInvoiceTotals({ save: false });
    const payload = collectGuidedInvoicePayload();
    payload.items.push({ qty: null, description: '', unit_price: null });
    const nextEntries = guidedInvoicePayloadToAcroEntries(payload);
    setStatus('Adding invoice row...');
    setSaveStatus('Regenerating...');

    const response = await fetch(REGENERATE_INVOICE_URL, {
        method: 'POST',
        credentials: 'same-origin',
        headers: {
            'Content-Type': 'application/json',
            Accept: 'application/json',
            'X-CSRF-TOKEN': CSRF,
        },
        body: JSON.stringify(payload),
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok || !result?.success) {
        throw new Error(result?.error || result?.message || `Failed to add invoice row (${response.status})`);
    }

    acroFormEntries = nextEntries;
    latestAcroFormEntriesSnapshot = nextEntries;
    queueAcroFormEntriesForNextPdfLoad(nextEntries);
    await persistAcroFormStateOnly({ entries: nextEntries });

    const reloadUrl = new URL(result.file_url || PDF_URL, window.location.origin);
    reloadUrl.searchParams.set('_', String(Date.now()));
    await loadPdfFromUrl(reloadUrl.toString());
    setSaveStatus('Saved');
    setStatus('Invoice row added.');
}

function installGuidedInvoiceControls() {
    if (!IS_GUIDED_MODE) return;
    if (document.getElementById('enpv-guided-invoice-row-add')) return;

    const addButton = document.createElement('button');
    addButton.type = 'button';
    addButton.id = 'enpv-guided-invoice-row-add';
    addButton.className = 'enpv-guided-invoice-row-add';
    addButton.title = 'Add invoice row';
    addButton.setAttribute('aria-label', 'Add invoice row');
    addButton.textContent = '+';
    addButton.hidden = true;
    document.body.appendChild(addButton);

    addButton.addEventListener('click', () => {
        addGuidedInvoiceRow().catch((error) => {
            console.error(error);
            setSaveStatus('Add row failed', true);
            setStatus(error?.message || 'Failed to add invoice row.', true);
            showError(error?.message || 'Failed to add invoice row.');
        });
    });

    document.addEventListener('input', (event) => {
        const fieldName = String(event.target?.getAttribute?.('name') || '');
        if (fieldName === 'invoice_total' || /^invoice_item_\d+_amount$/.test(fieldName)) return;
        if (fieldName.startsWith('invoice_')) updateGuidedInvoiceTotals();
    }, true);
    document.addEventListener('change', (event) => {
        const fieldName = String(event.target?.getAttribute?.('name') || '');
        if (fieldName.startsWith('invoice_')) updateGuidedInvoiceTotals();
    }, true);

    eventBus.on('annotationlayerrendered', () => updateGuidedInvoiceTotals({ save: false }));
    eventBus.on('pagerendered', () => window.setTimeout(() => updateGuidedInvoiceTotals({ save: false }), 50));
    container?.addEventListener?.('scroll', positionGuidedInvoiceRowAddButton, { passive: true });
    window.addEventListener('scroll', positionGuidedInvoiceRowAddButton, { passive: true });
    window.addEventListener('resize', positionGuidedInvoiceRowAddButton);
    window.setTimeout(() => updateGuidedInvoiceTotals({ save: false }), 500);
}

installGuidedInvoiceControls();

