function buildSourceRewriteEditForBox(box, annotation, previousText) {
    if (!REWRITE_URL || !box || !annotation) return null;
    if (box.dataset.sourceRewriteInFlight === '1') return null;
    if (editorModeForBox(box) !== 'source') return null;
    if (box.dataset.userForcedRichText === '1') return null;
    const dxPts = Number.parseFloat(box.dataset.dxPts || '0') || 0;
    const dyPts = Number.parseFloat(box.dataset.dyPts || '0') || 0;
    if (Math.abs(dxPts) > 0.01 || Math.abs(dyPts) > 0.01) return null;
    const tc = selectedBoxTextElement(box);
    const newText = String(tc?.textContent ?? annotation.text ?? '');
    const originalText = String(annotation.pdfjsSourceText || baseTextForBox(box) || originalTextForBox(box) || previousText || '');
    if (!originalText || newText === originalText || normalizeComparableText(newText) === normalizeComparableText(originalText)) return null;
    if (/\r|\n/.test(originalText) || /\r|\n/.test(newText)) return null;
    const page = Number.parseInt(box.dataset.pageIndex || '-1', 10);
    if (!Number.isFinite(page) || page < 0) return null;
    const occurrence = Number.parseInt(box.dataset.occurrence || annotation.pdfjsSourceOccurrence || '0', 10);
    return {
        page,
        original_text: originalText,
        new_text: newText,
        occurrence: Number.isFinite(occurrence) && occurrence >= 0 ? occurrence : 0,
        source_bbox: {
            x: Number(annotation.pdfjsSourceX ?? box.dataset.sourceBboxX ?? box.dataset.baseBboxX ?? 0),
            y: Number(annotation.pdfjsSourceY ?? box.dataset.sourceBboxY ?? box.dataset.baseBboxY ?? 0),
            w: Number(annotation.pdfjsSourceW ?? box.dataset.sourceBboxW ?? box.dataset.baseBboxW ?? 0),
            h: Number(annotation.pdfjsSourceH ?? box.dataset.sourceBboxH ?? box.dataset.baseBboxH ?? 0),
        },
    };
}

async function postPdfjsTextRewrite(edits) {
    if (!REWRITE_URL) throw new Error('Rewrite endpoint not configured.');
    if (currentPdfBytes) {
        const fd = new FormData();
        fd.append('pdf', new Blob([currentPdfBytes], { type: 'application/pdf' }), 'current.pdf');
        fd.append('edits', JSON.stringify(edits));
        return fetch(REWRITE_URL, {
            method: 'POST',
            credentials: 'same-origin',
            headers: { 'X-CSRF-TOKEN': CSRF, Accept: 'application/pdf' },
            body: fd,
        });
    }
    return fetch(REWRITE_URL, {
        method: 'POST',
        credentials: 'same-origin',
        headers: {
            'Content-Type': 'application/json',
            'X-CSRF-TOKEN': CSRF,
            Accept: 'application/pdf',
        },
        body: JSON.stringify({ edits }),
    });
}

async function postPdfjsSourceRedaction(edits) {
    if (!REDACT_URL) throw new Error('Source redaction endpoint not configured.');
    if (currentPdfBytes) {
        const fd = new FormData();
        fd.append('pdf', new Blob([currentPdfBytes], { type: 'application/pdf' }), 'current.pdf');
        fd.append('edits', JSON.stringify(edits));
        return fetch(REDACT_URL, {
            method: 'POST',
            credentials: 'same-origin',
            headers: { 'X-CSRF-TOKEN': CSRF, Accept: 'application/pdf' },
            body: fd,
        });
    }
    return fetch(REDACT_URL, {
        method: 'POST',
        credentials: 'same-origin',
        headers: {
            'Content-Type': 'application/json',
            'X-CSRF-TOKEN': CSRF,
            Accept: 'application/pdf',
        },
        body: JSON.stringify({ edits }),
    });
}

async function redactSourceTextForAnnotations(entries) {
    const usable = entries.filter((entry) => entry?.annotation && entry?.edit);
    if (!usable.length) return false;
    setStatus('Removing original source text…');
    const r = await postPdfjsSourceRedaction(usable.map((entry) => entry.edit));
    if (!r.ok) {
        let body = '';
        try { body = await r.text(); } catch (_) {}
        throw new Error(`Source text redaction failed (${r.status}): ${body.slice(0, 400)}`);
    }
    const buf = await r.arrayBuffer();
    usable.forEach((entry) => markAnnotationSourceRedacted(String(entry.annotation.id || '')));
    await loadPdfFromBytes(buf);
    setDownloadButtonsDisabled(false, 'Download PDF');
    setStatus('Original source text removed.');
    return true;
}

async function rewriteSourceAnnotationBoxText(annotationId, edit) {
    const current = annotationId ? persistedAnnotationsById.get(annotationId) : null;
    if (current?._pdfjsSourceRedacted === true) return;
    if (current?._pdfjsCanvasRewritten === true && String(current._pdfjsCanvasText || '') === String(edit.new_text || '')) {
        return;
    }
    setStatus('Applying source text…');
    const r = await postPdfjsTextRewrite([edit]);
    if (!r.ok) {
        if (current) {
            await redactSourceTextForAnnotations([{ annotation: current, edit }]);
            return;
        }
        let body = '';
        try { body = await r.text(); } catch (_) {}
        throw new Error(`Server rewrite failed (${r.status}): ${body.slice(0, 400)}`);
    }
    const buf = await r.arrayBuffer();
    pendingEditCount += 1;
    markAnnotationCanvasRewritten(annotationId, edit.new_text);
    await loadPdfFromBytes(buf);
    setDownloadButtonsDisabled(false, 'Download PDF');
    setStatus(`Applied ${pendingEditCount} edit${pendingEditCount === 1 ? '' : 's'}.`);
}

async function overwritePromotedAnnotationText(annotation, newText, originalTextHint = '') {
    if (!annotation?.id || !OVERWRITE_TEXT_URL) return false;
    const response = await fetch(OVERWRITE_TEXT_URL, {
        method: 'POST',
        credentials: 'same-origin',
        headers: {
            'Content-Type': 'application/json',
            Accept: 'application/json',
            'X-CSRF-TOKEN': CSRF,
        },
        body: JSON.stringify({
            document_id: Number(DOC_ID),
            annotation_id: String(annotation.id),
            text: String(newText ?? ''),
            original_text: String(originalTextHint || annotation.originalText || annotation.pdfjsSourceText || annotation.text || ''),
            session_id: getSessionId(),
            generate_new: 1,
        }),
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok || !result?.success) {
        throw new Error(result?.message || `Promoted text overwrite failed (${response.status})`);
    }

    const next = {
        ...annotation,
        text: String(newText ?? ''),
        sourceTextLines: [String(newText ?? '')],
        promotedDirty: true,
        savedTextOverlay: true,
        preserveSourceTypography: true,
    };
    upsertPersistedAnnotation(next);
    if (result.file_url) {
        await loadPdfFromUrl(String(result.file_url));
    }
    return true;
}

function buildPersistedSourceRewriteEdit(annotation) {
    if (!annotation || annotation._pdfjsCanvasRewritten === true) return null;
    if (annotation._pdfjsSourceRedacted === true) return null;
    if (String(annotation.type || '').toLowerCase() !== 'text') return null;
    if (annotation.pdfjsDeleted === true || isPromotedExtractionAnnotation(annotation)) return null;
    if (annotation.userForcedRichText === true || annotation.pdfjsEditorMode === 'rich') return null;
    const sourceText = String(annotation.pdfjsSourceText || annotation.originalText || '');
    const newText = String(annotation.text || '');
    if (!sourceText || !newText || sourceText === newText || normalizeComparableText(sourceText) === normalizeComparableText(newText)) return null;
    if (/\r|\n/.test(sourceText) || /\r|\n/.test(newText)) return null;
    const baseline = annotationBaselinePdfBox(annotation);
    const current = annotationCurrentPdfBox(annotation);
    if (!baseline || !current) return null;
    const sameGeometry = approxEqual(current.x, baseline.x)
        && approxEqual(current.y, baseline.y)
        && approxEqual(current.w, baseline.w)
        && approxEqual(current.h, baseline.h);
    if (!sameGeometry) return null;
    const page = annotationPageIndex(annotation);
    if (!Number.isFinite(page) || page < 0) return null;
    const occurrence = Number.parseInt(annotation.pdfjsSourceOccurrence || '0', 10);
    return {
        page,
        original_text: sourceText,
        new_text: newText,
        occurrence: Number.isFinite(occurrence) && occurrence >= 0 ? occurrence : 0,
        source_bbox: {
            x: Number(annotation.pdfjsSourceX ?? baseline.x),
            y: Number(annotation.pdfjsSourceY ?? baseline.y),
            w: Number(annotation.pdfjsSourceW ?? baseline.w),
            h: Number(annotation.pdfjsSourceH ?? baseline.h),
        },
    };
}

function buildPersistedSourceRedactionEdit(annotation) {
    if (!annotation || annotation._pdfjsCanvasRewritten === true || annotation._pdfjsSourceRedacted === true) return null;
    if (String(annotation.type || '').toLowerCase() !== 'text') return null;
    const isDeletedSource = boolish(annotation.pdfjsDeleted);
    if (!isDeletedSource) return null;
    if (!isDeletedSource && isPromotedExtractionAnnotation(annotation)) return null;
    if (!boolish(annotation.savedTextOverlay) && !isDeletedSource) return null;
    if (!isDeletedSource && isRedundantPdfjsSourceOverlay(annotation)) return null;
    const sourceText = String(annotation.pdfjsSourceText || annotation.originalText || '').trim();
    if (!sourceText) return null;
    const baseline = annotationBaselinePdfBox(annotation);
    if (!baseline) return null;
    const page = annotationPageIndex(annotation);
    if (!Number.isFinite(page) || page < 0) return null;
    const occurrence = Number.parseInt(annotation.pdfjsSourceOccurrence || '0', 10);
    const bbox = isDeletedSource
        ? deletedSourceRedactionBbox(annotation)
        : {
            x: Number(annotation.pdfjsSourceX ?? baseline.x),
            y: Number(annotation.pdfjsSourceY ?? baseline.y),
            w: Number(annotation.pdfjsSourceW ?? baseline.w),
            h: Number(annotation.pdfjsSourceH ?? baseline.h),
        };
    if (!bbox) return null;
    return {
        page,
        original_text: sourceText,
        occurrence: Number.isFinite(occurrence) && occurrence >= 0 ? occurrence : 0,
        source_bbox: bbox,
        redact_bbox_only: false,
        remove_graphics: false,
        fill_white: isDeletedSource,
    };
}

async function rewritePersistedSourceAnnotationsToCanvas() {
    const redactionEntries = Array.from(persistedAnnotationsById.values())
        .map((annotation) => ({ annotation, edit: buildPersistedSourceRedactionEdit(annotation) }))
        .filter((entry) => entry.edit);
    if (redactionEntries.length) {
        await redactSourceTextForAnnotations(redactionEntries);
        return true;
    }
    const entries = Array.from(persistedAnnotationsById.values())
        .map((annotation) => ({ annotation, edit: buildPersistedSourceRewriteEdit(annotation) }))
        .filter((entry) => entry.edit);
    if (!entries.length) return false;
    setStatus('Applying saved source text…');
    const r = await postPdfjsTextRewrite(entries.map((entry) => entry.edit));
    if (!r.ok) {
        await redactSourceTextForAnnotations(entries);
        return true;
    }
    const buf = await r.arrayBuffer();
    entries.forEach((entry) => markAnnotationCanvasRewritten(String(entry.annotation.id || ''), entry.edit.new_text));
    await loadPdfFromBytes(buf);
    return true;
}

async function applyEdit() {
    if (!activeRun) return;
    const newText = editInput.value;
    const activeSourceInfo = sourceInfoForSpan(activeRun);
    const original = activeSourceInfo?.text || sourceSpanOriginalText(activeRun) || activeRun.textContent || '';
    const displayOriginal = activeSourceInfo?.visualText || original;
    if (newText === displayOriginal || normalizeComparableText(newText) === normalizeComparableText(original)) { closeEditor(); return; }
    const existingAnnotation = (() => {
        const pageIndex = parseInt(activeRun.dataset.enpvPage || '-1', 10);
        const pageView = Number.isFinite(pageIndex) && pageIndex >= 0 ? pdfViewer.getPageView(pageIndex) : null;
        const viewport = pageView?.viewport;
        const layerEl = pageView?.textLayer?.div || pageView?.textLayer?.textLayerDiv;
        if (!viewport || !layerEl) {
            const persistentId = activeRun.dataset.enpvPersistentId;
            return persistentId ? (persistedAnnotationsById.get(String(persistentId)) || null) : null;
        }
        const scale = Number(viewport.scale) || Number(pdfViewer.currentScale) || 1;
        const sourceInfo = activeSourceInfo || sourceInfoForSpan(activeRun);
        const sourceRect = sourceInfo?.rect;
        const layerRect = layerEl.getBoundingClientRect();
        const spanRect = activeRun.getBoundingClientRect();
        const currentRect = {
            x: ((sourceRect?.left ?? (spanRect.left - layerRect.left))) / scale,
            y: (Number(viewport.height) - ((sourceRect?.top ?? (spanRect.top - layerRect.top)) + (sourceRect?.height ?? spanRect.height))) / scale,
            w: (sourceRect?.width ?? spanRect.width) / scale,
            h: (sourceRect?.height ?? spanRect.height) / scale,
        };
        const persistentId = activeRun.dataset.enpvPersistentId;
        if (persistentId) return persistedAnnotationsById.get(String(persistentId)) || null;
        const sourceUid = sourceInfo?.uid || `${pageIndex}:${activeRun.dataset.enpvIndex || activeRun.dataset.enpvOccurrence || '0'}`;
        return findPersistedAnnotationForSpan(pageIndex, currentRect, original, original, false, sourceUid);
    })();
    const edit = {
        page: parseInt(activeRun.dataset.enpvPage, 10),
        original_text: original,
        new_text: newText,
        occurrence: activeSourceInfo?.occurrence ?? parseInt(activeRun.dataset.enpvOccurrence, 10),
        source_bbox: sourceBboxForSpan(activeRun) || undefined,
    };
    setStatus('Applying edit…');
    editApply.disabled = true;
    try {
        if (isPromotedExtractionAnnotation(existingAnnotation)) {
            await overwritePromotedAnnotationText(existingAnnotation, newText, displayOriginal || original);
            pendingEditCount += 1;
            closeEditor();
            setDownloadButtonsDisabled(false, 'Download PDF');
            setStatus(`Applied ${pendingEditCount} edit${pendingEditCount === 1 ? '' : 's'}.`);
            return;
        }

        const r = await postPdfjsTextRewrite([edit]);
        if (!r.ok) {
            const fallbackAnnotation = buildAnnotationFromSpan(activeRun, newText, existingAnnotation);
            if (fallbackAnnotation) {
                upsertPersistedAnnotation(fallbackAnnotation);
                await redactSourceTextForAnnotations([{ annotation: fallbackAnnotation, edit }]);
                pendingEditCount += 1;
                closeEditor();
                setStatus(`Applied ${pendingEditCount} edit${pendingEditCount === 1 ? '' : 's'}.`);
                return;
            }
            let body = '';
            try { body = await r.text(); } catch (_) {}
            throw new Error(`Server rewrite failed (${r.status}): ${body.slice(0, 400)}`);
        }
        const buf = await r.arrayBuffer();
        pendingEditCount += 1;
        const persistedAnnotation = buildAnnotationFromSpan(activeRun, newText, existingAnnotation);
        closeEditor();
        if (persistedAnnotation) {
            persistedAnnotation._pdfjsCanvasRewritten = true;
            persistedAnnotation._pdfjsCanvasText = newText;
            upsertPersistedAnnotation(persistedAnnotation);
        } else if (existingAnnotation?.id) {
            deletePersistedAnnotation(existingAnnotation.id);
        }
        await loadPdfFromBytes(buf);
        setDownloadButtonsDisabled(false, 'Download PDF');
        setStatus(`Applied ${pendingEditCount} edit${pendingEditCount === 1 ? '' : 's'}.`);
    } catch (err) {
        console.error(err);
        showError(err.message);
        setStatus('Edit failed.', true);
    } finally {
        editApply.disabled = false;
    }
}
editApply.addEventListener('click', applyEdit);

async function buildPdfjsDownloadPayload() {
    syncSelectedBoxToPersistedAnnotations();
    syncDirtyBoxesToPersistedAnnotations();
    syncRenderedPersistedOverlayBoxesToPersistedAnnotations();
    const sessionAnnotationsPayload = Array.from(persistedAnnotationsById.values())
        .filter((annotation) => !isRedundantPdfjsSourceOverlay(annotation))
        .filter((annotation) => boolish(annotation.pdfjsDeleted) || !isSuppressedStalePdfjsOverlay(annotation))
        .map((annotation) => stripTransientAnnotationFields(annotation))
        .filter((annotation) => shouldIncludeInPdfjsSessionPayload(annotation))
        .filter(Boolean);
    const visibleAnnotationsPayload = sessionAnnotationsPayload
        .filter((annotation) => shouldIncludeInPdfjsVisibleExport(annotation));
    const acroPayload = await collectAcroFormEntriesForSave().catch((err) => {
        console.warn('Failed to collect AcroForm entries for download', err);
        return Array.isArray(acroFormEntries) ? acroFormEntries : [];
    });
    const deletedPromotedSourceKeys = Array.from(pendingDeletedAnnotationIds)
        .map((value) => String(value || '').trim())
        .filter((sourceKey) => /^block-\d+-\d+(?:-.+)?$/.test(sourceKey));
    const payload = {
        annotations: visibleAnnotationsPayload,
        session_annotations: sessionAnnotationsPayload,
        acro_form_entries: acroPayload,
        deleted_promoted_source_keys: deletedPromotedSourceKeys,
        use_exact_download_path: true,
        use_pdfjs_visible_export: true,
        use_conversion_safe_export: true,
        session_id: getSessionId(),
    };
    return payload;
}

async function requestEditedPdfBlob() {
    if (!DOWNLOAD_URL || !currentPdfDoc) throw new Error('PDF download endpoint is not available.');
    if (hydratingPersistedAnnotations
        && hydratingPersistedAnnotationsGeneration === viewerLoadGeneration) {
        throw new Error('The saved document state is still loading.');
    }
    const payload = await buildPdfjsDownloadPayload();
    const response = await fetch(DOWNLOAD_URL, {
        method: 'POST',
        credentials: 'same-origin',
        headers: {
            'Content-Type': 'application/json',
            Accept: 'application/pdf, application/json',
            'X-CSRF-TOKEN': CSRF,
            ...(documentUnlockToken ? { 'X-PDF-Unlock-Token': documentUnlockToken } : {}),
        },
        body: JSON.stringify(payload),
    });
    if (!response.ok) {
        let message = `PDF generation failed (${response.status})`;
        const contentType = String(response.headers.get('content-type') || '');
        if (contentType.includes('application/json')) {
            const result = await response.json().catch(() => ({}));
            message = result?.message || result?.error || message;
        } else {
            const responseText = await response.text().catch(() => '');
            if (responseText) message = responseText.slice(0, 500);
        }
        throw new Error(message);
    }
    return { blob: await response.blob(), payload };
}

async function downloadStampedPdf() {
    if (!DOWNLOAD_URL || !currentPdfDoc) return;
    const popup = window.open('', '_blank');
    if (popup) {
        popup.document.write('<!DOCTYPE html><title>Preparing PDF</title><body style="font-family:system-ui,sans-serif;padding:24px;color:#111827;">Preparing PDF...</body>');
        popup.document.close();
    }
    try {
        setDownloadButtonsDisabled(true, 'Preparing PDF...');
        setStatus('Preparing PDF...');
        const { blob, payload } = await requestEditedPdfBlob();
        let downloadBlob = blob;
        if (passwordProtectionIsActive()) {
            setStatus('Encrypting PDF…');
            downloadBlob = await encryptEditedPdfBlob(blob);
        }
        const url = URL.createObjectURL(downloadBlob);
        if (popup && !popup.closed) {
            popup.location.replace(url);
        } else if (!window.open(url, '_blank', 'noopener')) {
            window.location.assign(url);
        }
        setTimeout(() => { URL.revokeObjectURL(url); }, 60000);
        acroFormEntries = Array.isArray(payload.acro_form_entries) ? payload.acro_form_entries : acroFormEntries;
        latestAcroFormEntriesSnapshot = acroFormEntries;
        pendingClearedAcroFormKeys.clear();
        pendingAcroFormClearRegions = [];
        pendingDeletedAnnotationIds.clear();
        setSaveStatus(payload.annotations.length ? 'Saved' : 'No changes');
        setStatus(passwordProtectionIsActive() ? 'Password-protected PDF ready.' : 'PDF ready.');
        flashSaveToast(passwordProtectionIsActive() ? 'Protected PDF ready' : 'PDF ready');
    } catch (err) {
        if (popup && !popup.closed) popup.close();
        console.error(err);
        showError(err.message);
        setStatus('PDF generation failed.', true);
    } finally {
        setDownloadButtonsDisabled(false, 'Download PDF');
    }
}

for (const button of [downloadBtn, downloadPdfButton].filter(Boolean)) {
    button.addEventListener('click', () => {
        downloadStampedPdf().catch(() => {});
    });
}

async function saveAnnotationStateToDb(options = {}) {
    if (!SAVE_URL) {
        showError('Save endpoint not configured');
        return;
    }
    if (hydratingPersistedAnnotations
        && hydratingPersistedAnnotationsGeneration === viewerLoadGeneration) {
        saveAfterHydration = true;
        if (options.source !== 'autosave') {
            setSaveStatus('Loading…');
            setStatus('Saved edits are still loading. Please try again in a moment.');
        }
        return false;
    }
    if (saveInFlight) {
        saveAgainAfterCurrent = true;
        if (options.source !== 'autosave') {
            setSaveStatus('Saving…');
            setStatus('Save already running. Saving latest changes next…');
        }
        return;
    }
    if (autoSaveTimer) {
        window.clearTimeout(autoSaveTimer);
        autoSaveTimer = 0;
    }
    saveInFlight = true;

    try {
        const isAutosave = options.source === 'autosave';
        const preserveEmptyUserCreated = isAutosave;
        syncSelectedBoxToPersistedAnnotations({
            preserveEmptyUserCreated,
            preserveEditMode: isAutosave,
        });
        syncDirtyBoxesToPersistedAnnotations({
            preserveEmptyUserCreated,
            preserveEditMode: isAutosave,
        });
        syncRenderedPersistedOverlayBoxesToPersistedAnnotations();
        const sessionId = getSessionId();
        const annotationsPayload = Array.from(persistedAnnotationsById.values())
            .filter((annotation) => !isRedundantPdfjsSourceOverlay(annotation))
            .filter((annotation) => !isSuppressedStalePdfjsOverlay(annotation))
            .map((annotation) => stripTransientAnnotationFields(annotation))
            .filter((annotation) => shouldIncludeInPdfjsSessionPayload(annotation))
            .filter(Boolean);
        // Snapshot AcroForm field state from pdf.js's annotationStorage so
        // anything the user typed/checked since load is included in this
        // save. Falls back to the entries echoed by documentInfo when the
        // walk fails (e.g. no PDF loaded).
        const acroPayload = await collectAcroFormEntriesForSave().catch((err) => {
            console.warn('Failed to collect AcroForm entries for save', err);
            return Array.isArray(acroFormEntries) ? acroFormEntries : [];
        });

        setSaveStatus('Saving…');
        setStatus('Saving annotation state…');
        if (saveButton) saveButton.disabled = true;
        const response = await fetch(SAVE_URL, {
            method: 'POST',
            credentials: 'same-origin',
            headers: {
                'Content-Type': 'application/json',
                Accept: 'application/json',
                'X-CSRF-TOKEN': CSRF,
            },
            body: JSON.stringify({
                annotations: annotationsPayload,
                session_annotations: annotationsPayload,
                acro_form_entries: acroPayload,
                deleted_annotation_ids: Array.from(new Set([
                    ...Array.from(pendingDeletedAnnotationIds),
                    ...Array.from(suppressedStalePdfjsOverlayIds),
                ])),
                session_id: sessionId,
            }),
        });
        const result = await response.json().catch(() => ({}));
        if (!response.ok || !result?.success) {
            throw new Error(result?.message || `Save failed (${response.status})`);
        }
        if (result.session_id && String(result.session_id).trim()) {
            safeLocalStorageSet(`edit_new_session_${DOC_ID}`, String(result.session_id).trim());
        }
        acroFormEntries = Array.isArray(acroPayload) ? acroPayload : [];
        latestAcroFormEntriesSnapshot = acroFormEntries;
        pendingClearedAcroFormKeys.clear();
        pendingAcroFormClearRegions = [];
        const savedChangeCount = annotationsPayload.length + acroFormEntries.length;
        setSaveStatus(savedChangeCount ? 'Saved' : 'No changes');
        setStatus(savedChangeCount ? 'Document state saved.' : 'No changes to save.');
        flashSaveToast(savedChangeCount ? 'Saved' : 'No changes to save');
        pendingDeletedAnnotationIds.clear();
    } catch (err) {
        console.error(err);
        setSaveStatus('Save failed', true);
        setStatus('Save failed.', true);
        showError(err.message || 'Save failed.');
        throw err;
    } finally {
        if (saveButton) {
            saveButton.disabled = hydratingPersistedAnnotations
                && hydratingPersistedAnnotationsGeneration === viewerLoadGeneration;
        }
        saveInFlight = false;
        if (saveAgainAfterCurrent && !suppressAutoSaveForNavigation) {
            saveAgainAfterCurrent = false;
            setSaveStatus('Autosaving…');
            setStatus('Saving latest changes…');
            scheduleAutoSave();
        } else if (suppressAutoSaveForNavigation) {
            saveAgainAfterCurrent = false;
        }
    }
}

if (saveButton) {
    saveButton.addEventListener('click', () => {
        saveAnnotationStateToDb().catch(() => {});
    });
}

function loadGridlinesSettings() {
    try {
        const raw = safeLocalStorageGet(gridlinesSettingsStorageKey);
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        return parsed && typeof parsed === 'object' ? parsed : null;
    } catch (error) {
        console.warn('Failed to load gridlines settings:', error);
        return null;
    }
}

function persistGridlinesSettings() {
    safeLocalStorageSet(gridlinesSettingsStorageKey, JSON.stringify({
        enabled: !!gridlinesEnabled,
        spacing: gridlinesSpacing,
        color: gridlinesColor,
        opacity: gridlinesOpacity,
    }));
}

function normalizeGridlinesSettings(settings) {
    gridlinesEnabled = !!settings?.enabled;
    const spacing = Number.parseInt(String(settings?.spacing ?? ''), 10);
    gridlinesSpacing = Number.isFinite(spacing) ? Math.min(200, Math.max(10, spacing)) : 50;
    const color = String(settings?.color || '').trim();
    gridlinesColor = /^#[0-9a-f]{6}$/i.test(color) ? color : '#3b82f6';
    const opacity = Number(settings?.opacity);
    gridlinesOpacity = Number.isFinite(opacity)
        ? Math.min(0.5, Math.max(0.05, opacity > 1 ? opacity / 100 : opacity))
        : 0.15;
}

function syncGridlinesSettingsUi() {
    if (gridlinesToggle) gridlinesToggle.checked = gridlinesEnabled;
    if (gridlinesOptions) gridlinesOptions.hidden = !gridlinesEnabled;
    if (gridlinesSpacingInput) gridlinesSpacingInput.value = String(gridlinesSpacing);
    if (gridlinesSpacingLabel) gridlinesSpacingLabel.textContent = `${gridlinesSpacing}px`;
    if (gridlinesColorInput) gridlinesColorInput.value = gridlinesColor;
    if (gridlinesOpacityInput) gridlinesOpacityInput.value = String(Math.round(gridlinesOpacity * 100));
    settingsGearButton?.setAttribute('aria-pressed', gridlinesEnabled ? 'true' : 'false');
}

function removeGridlines(pageDiv = null) {
    const rootEl = pageDiv || document;
    rootEl.querySelectorAll?.('.enpv-gridlines-overlay')?.forEach((el) => el.remove());
}

function pageDivForGrid(pageIndex) {
    return Number.isFinite(pageIndex) && pageIndex >= 0
        ? pdfViewer.getPageView(pageIndex)?.div
        : null;
}

function renderGridlinesForPage(pageIndex) {
    const pageDiv = pageDivForGrid(pageIndex);
    if (!pageDiv) return;
    removeGridlines(pageDiv);
    if (!gridlinesEnabled) return;

    const width = pageDiv.clientWidth || pageDiv.offsetWidth || 0;
    const height = pageDiv.clientHeight || pageDiv.offsetHeight || 0;
    if (!(width > 0) || !(height > 0)) return;

    const scale = Number(pdfViewer.currentScale) || (currentZoomPercent / 100) || 1;
    const spacing = Math.max(4, gridlinesSpacing * scale);
    const svgNS = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(svgNS, 'svg');
    svg.classList.add('enpv-gridlines-overlay');
    svg.setAttribute('width', String(width));
    svg.setAttribute('height', String(height));
    svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
    svg.setAttribute('aria-hidden', 'true');

    const appendLine = (x1, y1, x2, y2) => {
        const line = document.createElementNS(svgNS, 'line');
        line.setAttribute('x1', String(x1));
        line.setAttribute('y1', String(y1));
        line.setAttribute('x2', String(x2));
        line.setAttribute('y2', String(y2));
        line.setAttribute('stroke', gridlinesColor);
        line.setAttribute('stroke-opacity', String(gridlinesOpacity));
        line.setAttribute('stroke-width', '1');
        line.setAttribute('stroke-dasharray', '4,4');
        line.setAttribute('vector-effect', 'non-scaling-stroke');
        svg.appendChild(line);
    };

    for (let x = spacing; x < width; x += spacing) appendLine(x, 0, x, height);
    for (let y = spacing; y < height; y += spacing) appendLine(0, y, width, y);
    pageDiv.appendChild(svg);
}

let gridlinesRenderFrame = 0;

function renderGridlines() {
    removeGridlines();
    if (!gridlinesEnabled) return;
    const pageCount = pdfViewer.pagesCount || currentPdfDoc?.numPages || 0;
    for (let pageIndex = 0; pageIndex < pageCount; pageIndex += 1) {
        renderGridlinesForPage(pageIndex);
    }
}

function scheduleRenderGridlines() {
    if (gridlinesRenderFrame) window.cancelAnimationFrame(gridlinesRenderFrame);
    gridlinesRenderFrame = window.requestAnimationFrame(() => {
        gridlinesRenderFrame = 0;
        renderGridlines();
    });
}

function setSettingsPopoverOpen(open) {
    if (!settingsPopover || !settingsGearButton) return;
    settingsPopover.hidden = !open;
    settingsGearButton.setAttribute('aria-expanded', open ? 'true' : 'false');
}

function installGridlinesSettingsControls() {
    normalizeGridlinesSettings(loadGridlinesSettings());
    syncGridlinesSettingsUi();

    settingsGearButton?.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        setSettingsPopoverOpen(settingsPopover?.hidden !== false);
    });
    settingsPopover?.addEventListener('click', (event) => event.stopPropagation());
    document.addEventListener('click', (event) => {
        if (!settingsPopover || settingsPopover.hidden) return;
        const target = event.target;
        if (settingsPopover.contains(target) || settingsGearButton?.contains(target)) return;
        setSettingsPopoverOpen(false);
    });
    document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') setSettingsPopoverOpen(false);
    });

    gridlinesToggle?.addEventListener('change', () => {
        gridlinesEnabled = !!gridlinesToggle.checked;
        syncGridlinesSettingsUi();
        persistGridlinesSettings();
        scheduleRenderGridlines();
    });
    gridlinesSpacingInput?.addEventListener('input', () => {
        const spacing = Number.parseInt(gridlinesSpacingInput.value || '50', 10);
        gridlinesSpacing = Math.min(200, Math.max(10, Number.isFinite(spacing) ? spacing : 50));
        syncGridlinesSettingsUi();
        persistGridlinesSettings();
        scheduleRenderGridlines();
    });
    gridlinesColorInput?.addEventListener('input', () => {
        if (/^#[0-9a-f]{6}$/i.test(gridlinesColorInput.value)) {
            gridlinesColor = gridlinesColorInput.value;
            persistGridlinesSettings();
            scheduleRenderGridlines();
        }
    });
    gridlinesOpacityInput?.addEventListener('input', () => {
        const opacity = Number.parseInt(gridlinesOpacityInput.value || '15', 10);
        gridlinesOpacity = Math.min(0.5, Math.max(0.05, (Number.isFinite(opacity) ? opacity : 15) / 100));
        persistGridlinesSettings();
        scheduleRenderGridlines();
    });
}

installGridlinesSettingsControls();

eventBus.on('pagesinit', () => {
    applyZoom(currentZoomPercent, { preserveAnchor: false });
    scheduleRenderGridlines();
});

// ---- Zoom bar (legacy /edit-new chrome) ---------------------------------
//
// Uses a 50%–400% range with proportional 1.25× steps, matching the
// focal-point zoom behavior of modern PDF viewers.
let currentZoomPercent = initialZoomPercent;
let suppressNextScaleEvent = false;
let zoomAnchorGeneration = 0;

const zoomLabel = document.getElementById('zoom-label');
const zoomInBtn = document.getElementById('zoom-in');
const zoomOutBtn = document.getElementById('zoom-out');
const pageJumpInput = document.getElementById('page-jump');
const pageTotalLabel = document.getElementById('page-total');
const pagePrevBtn = document.getElementById('page-prev');
const pageNextBtn = document.getElementById('page-next');

function clampZoom(p) {
    return Math.max(ZOOM_MIN_PERCENT, Math.min(ZOOM_MAX_PERCENT, Math.round(p)));
}

function captureZoomAnchor(clientX = null, clientY = null) {
    if (!container || !viewerElement) return null;
    const containerRect = container.getBoundingClientRect();
    const anchorX = Number.isFinite(clientX)
        ? Math.max(containerRect.left, Math.min(containerRect.right, clientX))
        : containerRect.left + (container.clientWidth / 2);
    const anchorY = Number.isFinite(clientY)
        ? Math.max(containerRect.top, Math.min(containerRect.bottom, clientY))
        : containerRect.top + (container.clientHeight / 2);
    const pageDivs = Array.from(viewerElement.querySelectorAll('.page[data-page-number]'));
    let best = null;
    let bestDistance = Number.POSITIVE_INFINITY;
    pageDivs.forEach((pageDiv) => {
        const rect = pageDiv.getBoundingClientRect();
        if (!(rect.width > 0) || !(rect.height > 0)) return;
        const dx = anchorX < rect.left ? rect.left - anchorX : (anchorX > rect.right ? anchorX - rect.right : 0);
        const dy = anchorY < rect.top ? rect.top - anchorY : (anchorY > rect.bottom ? anchorY - rect.bottom : 0);
        const distance = (dx * dx) + (dy * dy);
        if (distance >= bestDistance) return;
        bestDistance = distance;
        best = { pageDiv, rect };
    });
    if (!best) return null;
    const pageNumber = Number.parseInt(best.pageDiv.dataset.pageNumber || '', 10);
    if (!Number.isFinite(pageNumber)) return null;
    return {
        pageNumber,
        relativeX: Math.max(0, Math.min(1, (anchorX - best.rect.left) / best.rect.width)),
        relativeY: Math.max(0, Math.min(1, (anchorY - best.rect.top) / best.rect.height)),
        clientX: anchorX,
        clientY: anchorY,
    };
}

function scheduleZoomAnchorRestore(anchor) {
    if (!anchor) return;
    const generation = ++zoomAnchorGeneration;
    let attempts = 0;
    const restore = () => {
        if (generation !== zoomAnchorGeneration) return;
        const pageView = pdfViewer?.getPageView?.(anchor.pageNumber - 1) || null;
        const pageDiv = pageView?.div || viewerElement?.querySelector?.(`.page[data-page-number="${anchor.pageNumber}"]`);
        if (!(pageDiv instanceof HTMLElement)) return;
        const rect = pageDiv.getBoundingClientRect();
        if (!(rect.width > 0) || !(rect.height > 0)) return;
        const pointX = rect.left + (rect.width * anchor.relativeX);
        const pointY = rect.top + (rect.height * anchor.relativeY);
        container.scrollLeft += pointX - anchor.clientX;
        container.scrollTop += pointY - anchor.clientY;
        attempts += 1;
        if (attempts < 3) window.requestAnimationFrame(restore);
    };
    window.requestAnimationFrame(restore);
}

function applyZoom(percent, opts = {}) {
    const zoomAnchor = !opts.skipViewer && opts.preserveAnchor !== false
        ? captureZoomAnchor(opts.anchorClientX, opts.anchorClientY)
        : null;
    const nextZoom = clampZoom(percent);
    currentZoomPercent = nextZoom;
    if (zoomLabel) zoomLabel.textContent = `${currentZoomPercent}%`;
    if (zoomInBtn) zoomInBtn.disabled = currentZoomPercent >= ZOOM_MAX_PERCENT;
    if (zoomOutBtn) zoomOutBtn.disabled = currentZoomPercent <= ZOOM_MIN_PERCENT;
    if (!opts.skipViewer) {
        suppressNextScaleEvent = true;
        // pdf.js uses a multiplier (1.0 = 100%).
        pdfViewer.currentScale = currentZoomPercent / 100;
        scheduleZoomAnchorRestore(zoomAnchor);
    }
}

if (zoomInBtn) {
    zoomInBtn.addEventListener('click', () => applyZoom(currentZoomPercent * ZOOM_STEP_FACTOR));
}
if (zoomOutBtn) {
    zoomOutBtn.addEventListener('click', () => applyZoom(currentZoomPercent / ZOOM_STEP_FACTOR));
}

// React to viewer-side scale changes (e.g. page-width fit, ctrl+wheel) so
// the label tracks the actual rendered scale.
eventBus.on('scalechanging', (evt) => {
    if (suppressNextScaleEvent) {
        suppressNextScaleEvent = false;
        scheduleRenderAllAnnotationBoxLayers();
        scheduleRenderGridlines();
        if (notesLoaded) window.requestAnimationFrame(() => renderNoteMarkers());
        return;
    }
    const percent = Math.round((evt.scale || pdfViewer.currentScale) * 100);
    if (percent && percent !== currentZoomPercent) {
        applyZoom(percent, { skipViewer: true });
    }
    scheduleRenderAllAnnotationBoxLayers();
    scheduleRenderGridlines();
    if (notesLoaded) window.requestAnimationFrame(() => renderNoteMarkers());
});

// Ctrl/Cmd + wheel zoom anchored to the cursor (matches pdf.js viewer UX).
container.addEventListener('wheel', (ev) => {
    if (!ev.ctrlKey && !ev.metaKey) return;
    ev.preventDefault();
    const nextZoom = ev.deltaY < 0
        ? currentZoomPercent * ZOOM_STEP_FACTOR
        : currentZoomPercent / ZOOM_STEP_FACTOR;
    applyZoom(nextZoom, {
        anchorClientX: ev.clientX,
        anchorClientY: ev.clientY,
    });
}, { passive: false });

// ---- Page nav (prev / next / jump-to) -----------------------------------

function refreshPageBar(pageNum, total) {
    if (pageJumpInput) {
        pageJumpInput.value = String(pageNum);
        pageJumpInput.max = String(total);
    }
    if (pageTotalLabel) pageTotalLabel.textContent = String(total);
    if (pagePrevBtn) pagePrevBtn.disabled = pageNum <= 1;
    if (pageNextBtn) pageNextBtn.disabled = pageNum >= total;
}

if (pagePrevBtn) {
    pagePrevBtn.addEventListener('click', () => {
        if (pdfViewer.currentPageNumber > 1) pdfViewer.currentPageNumber -= 1;
    });
}
if (pageNextBtn) {
    pageNextBtn.addEventListener('click', () => {
        if (pdfViewer.currentPageNumber < pdfViewer.pagesCount) pdfViewer.currentPageNumber += 1;
    });
}
if (pageJumpInput) {
    const jump = () => {
        const v = parseInt(pageJumpInput.value, 10);
        if (Number.isFinite(v) && v >= 1 && v <= pdfViewer.pagesCount) {
            pdfViewer.currentPageNumber = v;
        } else {
            pageJumpInput.value = String(pdfViewer.currentPageNumber);
        }
    };
    pageJumpInput.addEventListener('change', jump);
    pageJumpInput.addEventListener('keydown', (ev) => { if (ev.key === 'Enter') jump(); });
}

eventBus.on('pagechanging', (evt) => {
    const wasEditing = document.body.classList.contains('enpv-edit-on');
    refreshPageBar(evt.pageNumber, pdfViewer.pagesCount);
    window.requestAnimationFrame(() => {
        syncEditModeRotationAvailability({ showDialog: wasEditing });
    });
});
eventBus.on('pagesloaded', async () => {
    const loadGeneration = viewerLoadGeneration;
    refreshPageBar(pdfViewer.currentPageNumber || 1, pdfViewer.pagesCount);
    if (notesLoaded) renderNoteMarkers();
    if (pageManagerModal?.hidden === false) renderPageManagerGrid();
    scheduleRenderGridlines();
    syncEditModeRotationAvailability();
    await revealWhenEditedDocumentReady(loadGeneration);
});

eventBus.on('pagerendered', (evt) => {
    const pageIndex = evt.pageNumber - 1;
    const currentPageView = pdfViewer.getPageView(pageIndex);
    // The page canvas just changed, so every memoized pixel sample taken from
    // it is stale (pdf.js may repaint an existing canvas in place).
    invalidateCanvasSampleCache(currentPageView?.div);
    if (attachedPdfGeneration !== viewerLoadGeneration
        || !currentPageView?.div
        || (evt.source && evt.source !== currentPageView)) return;
    if (pageIndex === 0 && attachedPdfGeneration === viewerLoadGeneration) {
        firstPageRenderedGeneration = viewerLoadGeneration;
        retryRevealAfterFirstPageRendered(viewerLoadGeneration);
    }
    renderAnnotationBoxLayer(pageIndex);
    syncRotatedPageSnapshot(pageIndex);
    if (pageIndex === Math.max(0, Number(pdfViewer.currentPageNumber || 1) - 1)) {
        syncEditModeRotationAvailability();
    }
    renderGridlinesForPage(pageIndex);
    if (notesLoaded) renderNoteMarkers(pageIndex);
});

function retryRevealAfterFirstPageRendered(loadGeneration, attempt = 0) {
    if (!isCurrentViewerLoad(loadGeneration)
        || attachedPdfGeneration !== loadGeneration
        || revealedLoadGeneration === loadGeneration) return;
    if (revealingLoadGeneration === loadGeneration) {
        if (attempt < 200) {
            window.setTimeout(
                () => retryRevealAfterFirstPageRendered(loadGeneration, attempt + 1),
                50,
            );
        }
        return;
    }
    revealWhenEditedDocumentReady(loadGeneration).catch((err) => {
        console.warn('First-page ready reveal retry failed', err);
    });
}

function preparePdfViewerLoad(options = {}) {
    setStatus('Rendering…');
    hideViewerUntilOverlaysReady();
    setLoadingScreenMessage('Preparing PDF...');
    viewerLoadGeneration += 1;
    const supersededLoadingTask = activePdfLoadingTask;
    if (supersededLoadingTask && supersededLoadingTask !== currentPdfLoadingTask) {
        Promise.resolve(supersededLoadingTask.task?.destroy?.()).catch(() => {});
    }
    // Keep the currently displayed PDF alive until its replacement parses.
    // This lets a failed rotate/merge/rewrite restore the working document
    // instead of leaving the editor blank.
    activePdfLoadingTask = currentPdfLoadingTask;
    firstPageRenderedGeneration = 0;
    hydratingPersistedAnnotations = Boolean(INFO_URL);
    hydratingPersistedAnnotationsGeneration = INFO_URL ? viewerLoadGeneration : 0;
    if (saveButton) saveButton.disabled = true;
    setDownloadButtonsDisabled(true, 'Loading PDF...');
    if (Array.isArray(options.annotationStateOverride)) {
        pendingAnnotationStateOverride = {
            generation: viewerLoadGeneration,
            records: options.annotationStateOverride.map((annotation) => cloneForHistory(annotation)),
            excludedAnnotationIds: Array.from(new Set(
                (options.excludedAnnotationIds || []).map((id) => String(id || '').trim()).filter(Boolean),
            )),
        };
    }
    revealingLoadGeneration = 0;
    annotationBoxesLoadPromise = null;
    annotationBoxesFetchPromise = null;
    if (pendingAcroFormEntriesOverride?.generation < viewerLoadGeneration) {
        pendingAcroFormEntriesOverride = null;
    }
    pageOccurrenceCounts.clear();
    // Start editor metadata and font work immediately. PDF parsing/rendering
    // is independent, so these requests should overlap instead of forming the
    // old PDF -> fonts -> annotations waterfall.
    preloadInitialAnnotationBoxes().catch(() => { /* surfaced by reveal */ });
    loadEmbeddedFontsForDocument().catch((err) => {
        console.warn('Embedded PDF font preload failed', err);
    });
    return viewerLoadGeneration;
}

async function attachLoadedPdfDocument(loadingRecord, loadGeneration, nextPdfBytes) {
    const pdfDoc = await loadingRecord.task.promise;
    if (!isCurrentViewerLoad(loadGeneration)) {
        await loadingRecord.task.destroy?.().catch?.(() => {});
        return false;
    }

    const previousPdfDocument = currentPdfDoc;
    const previousLoadingTask = currentPdfLoadingTask;
    currentPdfDoc = pdfDoc;
    currentPdfBytes = nextPdfBytes;
    attachedPdfGeneration = loadGeneration;
    currentPdfLoadingTask = loadingRecord;
    activePdfLoadingTask = loadingRecord;
    resetPdfjsRuntimeFontMetadata(pdfDoc);
    pdfViewer.setDocument(pdfDoc);
    linkService.setDocument(pdfDoc, null);
    loadPdfjsRuntimeFontsForDocument(pdfDoc).catch((error) => {
        console.warn('PDF.js document font discovery failed', error);
    });
    if (previousLoadingTask && previousLoadingTask !== loadingRecord) {
        Promise.resolve(previousLoadingTask.task?.destroy?.()).catch(() => {});
    } else if (previousPdfDocument && previousPdfDocument !== pdfDoc) {
        Promise.resolve(previousPdfDocument.destroy?.()).catch(() => {});
    }
    window.setTimeout(() => {
        revealWhenEditedDocumentReady(loadGeneration).catch((err) => {
            console.warn('Fallback ready reveal failed', err);
        });
    }, 250);
    return true;
}

function handleCurrentPdfLoadFailure(loadingRecord, loadGeneration) {
    if (activePdfLoadingTask === loadingRecord) {
        activePdfLoadingTask = currentPdfLoadingTask;
    }
    Promise.resolve(loadingRecord?.task?.destroy?.()).catch(() => {});
    if (hydratingPersistedAnnotationsGeneration === loadGeneration) {
        hydratingPersistedAnnotations = false;
        hydratingPersistedAnnotationsGeneration = 0;
    }
    revealingLoadGeneration = 0;
    if (!currentPdfDoc) return;
    attachedPdfGeneration = loadGeneration;
    firstPageRenderedGeneration = loadGeneration;
    revealedLoadGeneration = loadGeneration;
    revealViewer();
    setDownloadButtonsDisabled(false, 'Download PDF');
    if (saveButton) saveButton.disabled = false;
    if (saveAfterHydration && !suppressAutoSaveForNavigation) {
        saveAfterHydration = false;
        scheduleAutoSave();
    }
}

async function loadPdfFromUrl(url, options = {}) {
    setStatus('Fetching PDF…');
    const loadGeneration = preparePdfViewerLoad(options);
    let loadingRecord = { task: null, generation: loadGeneration };
    try {
        // Let PDF.js own the URL request so it can stream and issue byte
        // ranges for large/linearized files. Keep setup inside this guarded
        // path so even a synchronous PDF.js error restores the prior viewer.
        const loadingTask = pdfjsLib.getDocument({
            url: appendDocumentUnlockToken(url),
            withCredentials: true,
            isEvalSupported: false,
        });
        loadingRecord = { task: loadingTask, generation: loadGeneration };
        activePdfLoadingTask = loadingRecord;
        await attachLoadedPdfDocument(loadingRecord, loadGeneration, null);
    } catch (error) {
        if (!isCurrentViewerLoad(loadGeneration)) return;
        handleCurrentPdfLoadFailure(loadingRecord, loadGeneration);
        throw error;
    }
}

async function loadPdfFromBytes(buf, options = {}) {
    // Byte-returning rewrite/reflow endpoints change the rendered PDF but do
    // not persist the annotation table. Preserve the complete live snapshot
    // across the reload so the concurrent /info response cannot roll a fresh
    // local edit back to older server state or resurrect a pending deletion.
    syncSelectedBoxToPersistedAnnotations();
    syncDirtyBoxesToPersistedAnnotations();
    syncRenderedPersistedOverlayBoxesToPersistedAnnotations();
    const resolvedOptions = { ...options };
    // Always recapture after the final live-DOM sync. In particular, a burn
    // request may have waited on a save while another box was still being
    // edited; an older caller-supplied snapshot must not roll that edit back.
    resolvedOptions.annotationStateOverride = Array.from(persistedAnnotationsById.values())
        .map((annotation) => cloneForHistory(annotation));
    resolvedOptions.excludedAnnotationIds = Array.from(new Set([
        ...(Array.isArray(resolvedOptions.excludedAnnotationIds)
            ? resolvedOptions.excludedAnnotationIds
            : []),
        ...pendingDeletedAnnotationIds,
    ].map((id) => String(id || '').trim()).filter(Boolean)));
    const acroEntriesByKey = new Map();
    for (const entry of [
        ...(Array.isArray(acroFormEntries) ? acroFormEntries : []),
        ...(Array.isArray(latestAcroFormEntriesSnapshot) ? latestAcroFormEntriesSnapshot : []),
    ]) {
        const key = String(entry?.key || entry?.fieldName || '').trim();
        if (key) acroEntriesByKey.set(key, entry);
    }
    queueAcroFormEntriesForNextPdfLoad(
        collectRenderedAcroFormEntriesSnapshot(Array.from(acroEntriesByKey.values())),
    );

    const loadGeneration = preparePdfViewerLoad(resolvedOptions);
    let loadingRecord = { task: null, generation: loadGeneration };
    try {
        const data = buf.slice(0); // pdf.js mutates/transfers the input buffer
        // Keep `buf` as the current bytes only after this replacement parses;
        // `data` is the disposable PDF.js copy, avoiding a third full copy.
        const loadingTask = pdfjsLib.getDocument({ data, isEvalSupported: false });
        loadingRecord = { task: loadingTask, generation: loadGeneration };
        activePdfLoadingTask = loadingRecord;
        await attachLoadedPdfDocument(loadingRecord, loadGeneration, buf);
    } catch (error) {
        if (!isCurrentViewerLoad(loadGeneration)) return;
        handleCurrentPdfLoadFailure(loadingRecord, loadGeneration);
        throw error;
    }
}

async function revealWhenEditedDocumentReady(loadGeneration) {
    if (!isCurrentViewerLoad(loadGeneration)) return;
    if (attachedPdfGeneration !== loadGeneration) return;
    if (revealedLoadGeneration === loadGeneration) return;
    if (revealingLoadGeneration === loadGeneration) return;
    revealingLoadGeneration = loadGeneration;
    try {
        setStatus('Loading saved edits...');
        const [pagesReady, firstPageReady, , , annotationsLoaded] = await Promise.all([
            waitForViewerPagesReady(loadGeneration),
            waitForFirstPageRendered(loadGeneration),
            loadEmbeddedFontsForDocument(),
            loadPdfjsRuntimeFontsForDocument(currentPdfDoc),
            loadAnnotationBoxes(loadGeneration),
        ]);
        if (!pagesReady || !firstPageReady || !annotationsLoaded || !isCurrentViewerLoad(loadGeneration)) return;

        // textlayerrendered may have started the async face lookup while the
        // remaining document state was loading. Join those lookups before the
        // global render/reveal pass so a user cannot beat mixed typography
        // hydration to the first edit.
        await hydrateRenderedPdfjsTextLayerFontMetadata();
        if (!isCurrentViewerLoad(loadGeneration)) return;

        // Reuse an event-rendered layer only when its scale, edit mode and
        // annotation snapshot revision all match the freshly hydrated state.
        renderAllAnnotationBoxLayers({ preserveCurrent: true });
        applyAcroFormEntriesToDom();
        await nextAnimationFrame();
        // Event-driven page/text/annotation renders may already have produced
        // the correct layer. Only fill a missing/stale layer on this pass.
        renderAllAnnotationBoxLayers({ preserveCurrent: true });
        if (!isCurrentViewerLoad(loadGeneration)) return;
        setStatus(`Loaded ${currentPdfDoc.numPages} page${currentPdfDoc.numPages === 1 ? '' : 's'}.`);
        setDownloadButtonsDisabled(false, 'Download PDF');
        if (saveButton) saveButton.disabled = false;
        revealedLoadGeneration = loadGeneration;
        revealViewer();
        if (saveAfterHydration && !suppressAutoSaveForNavigation) {
            saveAfterHydration = false;
            scheduleAutoSave();
        }
    } finally {
        if (revealingLoadGeneration === loadGeneration && revealedLoadGeneration !== loadGeneration) {
            revealingLoadGeneration = 0;
        }
    }
}

// Anchor #pages-wrap below the visible fixed editor chrome so the PDF does
// not render underneath the floating toolbars.
function getTopChromeBottomEdge() {
    let bottom = 0;
    [
        document.querySelector('.top-bar'),
        document.getElementById('floating-tool-bar'),
    ].forEach((element) => {
        if (!(element instanceof HTMLElement)) return;
        const style = window.getComputedStyle(element);
        if (style.display === 'none' || style.visibility === 'hidden') return;
        const rect = element.getBoundingClientRect();
        if (rect.height <= 0 || rect.bottom <= 0) return;
        bottom = Math.max(bottom, rect.bottom);
    });
    return Math.max(0, bottom);
}

function syncPagesTop() {
    const wrap = document.getElementById('pages-wrap');
    const topBar = document.querySelector('.top-bar');
    if (topBar instanceof HTMLElement) {
        const topBarBottom = Math.max(0, topBar.getBoundingClientRect().bottom);
        document.body.style.setProperty('--enpv-topbar-offset', `${Math.ceil(topBarBottom)}px`);
    }
    if (!wrap) return;
    const chromeBottom = getTopChromeBottomEdge();
    wrap.style.top = `${Math.ceil(chromeBottom + 28)}px`;
}
window.addEventListener('load', syncPagesTop);
window.addEventListener('resize', () => {
    syncPagesTop();
});
syncPagesTop();

const topChromeElements = [
    document.querySelector('.top-bar'),
    document.getElementById('floating-tool-bar'),
].filter((element) => element instanceof HTMLElement);

if (typeof ResizeObserver !== 'undefined') {
    const topChromeResizeObserver = new ResizeObserver(() => syncPagesTop());
    topChromeElements.forEach((element) => topChromeResizeObserver.observe(element));
}

if (typeof MutationObserver !== 'undefined') {
    const topChromeMutationObserver = new MutationObserver(() => syncPagesTop());
    topChromeElements.forEach((element) => {
        topChromeMutationObserver.observe(element, {
            attributes: true,
            attributeFilter: ['class', 'style', 'hidden'],
        });
    });

}

// ---- Edit-mode toggle (legacy topbar + floating toolbar controls) --------
//
// Mirrors the classic /edit-new affordance: clicking "Edit PDF" turns
// the click-to-edit hover/click on text spans on or off. The legacy
// CSS already swaps the button label/colour via the .is-active class,
// so we just toggle that and a body class our textLayer styles look at.
let rotatedEditDialogReturnFocus = null;

function pageRotationDegrees(pageIndex) {
    const normalizedPageIndex = Number(pageIndex);
    if (!Number.isFinite(normalizedPageIndex) || normalizedPageIndex < 0) return 0;
    const pageView = pdfViewer?.getPageView?.(Math.floor(normalizedPageIndex));
    const viewportRotation = Number(pageView?.viewport?.rotation);
    if (Number.isFinite(viewportRotation)) return normalizePageRotationDegrees(viewportRotation);
    return normalizePageRotationDegrees(pageView?.pdfPage?.rotate ?? pageView?.rotation ?? 0);
}

function pageHasUnsupportedEditRotation(pageIndex) {
    const rotation = pageRotationDegrees(pageIndex);
    return rotation !== 0;
}

function currentPageEditRotationState() {
    const pageIndex = Math.max(0, Number(pdfViewer?.currentPageNumber || 1) - 1);
    const rotation = pageRotationDegrees(pageIndex);
    return {
        pageIndex,
        pageNumber: pageIndex + 1,
        rotation,
        blocked: rotation !== 0,
    };
}

function editRotationStateForPage(pageIndex) {
    const normalizedPageIndex = Math.max(0, Number(pageIndex) || 0);
    const rotation = pageRotationDegrees(normalizedPageIndex);
    return {
        pageIndex: normalizedPageIndex,
        pageNumber: normalizedPageIndex + 1,
        rotation,
        blocked: rotation !== 0,
    };
}

function preventUnsupportedRotatedPageEdit(pageIndex, trigger = null) {
    const state = editRotationStateForPage(pageIndex);
    if (!state.blocked) return false;
    setStatus(`Edit PDF is unavailable on page ${state.pageNumber} while it is rotated ${state.rotation}°.`, true);
    showRotatedEditDialog(state, trigger);
    return true;
}

function closeRotatedEditDialog() {
    if (!rotatedEditDialog || rotatedEditDialog.hidden) return;
    rotatedEditDialog.hidden = true;
    rotatedEditDialog.setAttribute('aria-hidden', 'true');
    const returnFocus = rotatedEditDialogReturnFocus;
    rotatedEditDialogReturnFocus = null;
    if (returnFocus?.isConnected) returnFocus.focus?.();
}

function showRotatedEditDialog(state = currentPageEditRotationState(), trigger = null) {
    if (!rotatedEditDialog || !state?.blocked) return;
    rotatedEditDialogReturnFocus = trigger instanceof HTMLElement
        ? trigger
        : document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;
    if (rotatedEditDialogDescription) {
        rotatedEditDialogDescription.textContent = `Page ${state.pageNumber} is rotated ${state.rotation}°. `
            + 'This page is shown as one flattened image so its saved masks and edits stay aligned. '
            + 'Rotate the page back to 0° to edit it.';
    }
    rotatedEditDialog.hidden = false;
    rotatedEditDialog.setAttribute('aria-hidden', 'false');
    window.requestAnimationFrame(() => rotatedEditDialogClose?.focus());
}

function syncEditModeRotationAvailability(options = {}) {
    const state = currentPageEditRotationState();
    document.body.classList.toggle('enpv-edit-rotation-blocked', state.blocked);
    for (const button of editModeButtons) {
        if (!button.dataset.rotationEnabledTitle) {
            button.dataset.rotationEnabledTitle = button.getAttribute('title') || 'Edit PDF';
        }
        button.classList.toggle('is-rotation-disabled', state.blocked);
        if (state.blocked) {
            button.setAttribute('aria-disabled', 'true');
            button.title = `Edit PDF unavailable: page ${state.pageNumber} is rotated ${state.rotation}°`;
        } else {
            button.removeAttribute('aria-disabled');
            button.title = button.dataset.rotationEnabledTitle;
        }
    }
    const wasEditing = document.body.classList.contains('enpv-edit-on');
    if (state.blocked && wasEditing && options.keepEditMode !== true) {
        setEditMode(false, { skipRotationCheck: true });
    }
    if (state.blocked && options.showDialog === true) {
        showRotatedEditDialog(state, options.trigger || null);
    }
    return state;
}

const editModeBtn = document.getElementById('edit-mode-toggle');
const editModeLabel = document.getElementById('edit-mode-toggle-label');
const floatingEditModeBtn = document.getElementById('ftb-edit-mode');
